			%\Statex $\mathbf{A}_M(l) \leftarrow \mathbf{0}$

			%\Function{Construct level 0 sub-matrix}{$\mathbf{A}$}
			\vspace{0.1cm}
			\Statex{\textbf{Method:}}
			\For{ $GlobalThreadId$ $=$ $0$, $1$, ..., $len(\mathbf{AG})-1$} \textbf{in parallel}
			% \Statex {\color[rgb]{0,0.61,0.33}// load each $3\times3$ sub-matrix with indices information}
			\State $[r,c, \mathbf{M3}] = \mathbf{AG}(GlobalThreadId)$ \Comment{{\color[rgb]{0,0.61,0.33} get $3\times 3$ block}}
			% \Statex {\color[rgb]{0,0.61,0.33} // map the node indices to MAS subdomain}
                \State $[domain\_Idx] = \mathbf{Map}(r)$
			\State $[domain\_Idy] = \mathbf{Map}(c)$ \Comment{{\color[rgb]{0,0.61,0.33} align METIS and MAS subdomain with padding (\autoref{fig:align_metis_mas})}}
