			\If{$domain\_Idx/N == domain\_Idy/N$} \Comment{{\color[rgb]{0,0.61,0.33} if nodes $r$ and $c$ belong to the same level-0 MAS subdomain, write $\mathbf{M3}$ to the level-0 MAS matrix}}
