			\vspace{0.1cm}
			\Statex{\textbf{Method:}}
			\State $UK \gets$ \Call{RunLengthEncode}{$K$} \Comment{{\color[rgb]{0,0.61,0.33} get unique keys ($UK$), which are used to recover the row/column indices in the global Hessian}}
			% \Statex {\color[rgb]{0,0.61,0.33}// get the length of unique key array}
			\State $Num \gets$ \Call{len}{K}
			% \Statex {\color[rgb]{0,0.61,0.33}// get prefix sum , start from 0}
			%\State $ESum \gets$ \Call{ExclusiveSum}{$NK$} \Comment{{\color[rgb]{0,0.61,0.33} get prefix sum, starting from 0}}
			% \Statex {\color[rgb]{0,0.61,0.33}// init $P$ array with 0}
			\Statex {\color[rgb]{0,0.61,0.33}// assign the unique key index to $O$ for each key in $K$:}
			%\State $P \gets $ \Call{Zeros}{len(K)}
			\For {$tid = 0, 1, ..., Num-2$} \textbf{in parallel} 
			%\State $P[ESum[tid] + NK[tid] - 1] \gets 1$ 
                \State $P[i] \gets K[i]\neq K[i+1]$ 
			\EndFor

			\State $O \gets$ \Call{ExclusiveSum}{$P$} \Comment{{\color[rgb]{0,0.61,0.33}map each $K$ to unique key}}

			\State $R \gets$ \Call{FastSegmentReduction}{$O$,$V$}
                \State $\mathbf{AG} \gets$ \Call{ConstructGlobalHessian}{$UK$, $R$}
