	\paragraph{FastSegmentReduction}
	In Algorithm \autoref{alg:fast_hash_reduction}, we create a mapping array $O$ to associate each key-value pair with its target memory location, as illustrated in \autoref{fig:fsreduction}. Array $O$ is also used to generate tag information for the CUB intrinsic function \emph{\textbf{HeadSegmentedReduce(values, tags)}}. The \emph{\textbf{tags}} are determined by comparing adjacent entries in $O$, as described in Algorithm \autoref{alg:fast_segment_reduction}.
	{Here, $b^{-}$ and $b$ represent the previous and current unique key indices, respectively. A new segment begins when $b^{-} \neq b$ or when the corresponding thread is the head of its warp. This is indicated using the \emph{\textbf{IsHead}} flag. This flag is set per thread, but only the thread with the flag equal to $1$ is allowed to write to the output array.}



	This hash key reduction method efficiently constructs the global Hessian matrix, critical for the subsequent linear system solve and preconditioner computation. Additionally, our Hessian assembly method ensures that \(3 \times 3\) sub-blocks in each row are sorted in the memory by column index, enabling an efficient SpMV algorithm with warp reduction to enhance PCG solver performance.


	\begin{algorithm}
		\caption{FastSegmentReduction}\label{alg:fast_segment_reduction}
		\begin{algorithmic}[1]
			\Statex \textbf{Input:}
			\Statex \hspace{0.4cm} $O$ \Comment{{\color[rgb]{0,0.61,0.33}The result in line 6 of \autoref{alg:fast_hash_reduction} }}
			\Statex \hspace{0.4cm} $V$ \Comment{{\color[rgb]{0,0.61,0.33}An array of values, sorted by the hash keys}}
			\Statex \textbf{Output:}
			\Statex \hspace{0.4cm} $R$ \Comment{{\color[rgb]{0,0.61,0.33}An array of reduced values, one value for each hash key}}
			%\State $M \gets$ \Call{Len}{V}

			\vspace{0.1cm}
			\Statex{\textbf{Method:}}
			\State \textbf{define} BD = BLOCK\_DIM
			%\State \textbf{define} WD = WARP\_DIM
			\State BlockCount $\gets$ (\Call{len}{V} + BD - 1) / BD
			\For {GlobalThreadId $=$ $0$, $1$, ..., BlockCount$\times$BD-1 } \textbf{in parallel}

			%\State LocalThreadId $\gets$ GlobalThreadId \% BLOCK\_DIM
			%\State WarpId $\gets$ LocalThreadId / WARP\_DIM
			\Statex \hspace{0.4cm} {\color[rgb]{0,0.61,0.33}// get tags for \emph{\textbf{cub::WarpReduce(values, tags)}}:} 
                \State $b^{-},b \gets -1$ \Comment{{\color[rgb]{0,0.61,0.33}$-1$ for invalid value}}
			\State LaneId $\gets$ GlobalThreadId \% WARP\_DIM
                %\State $b^{-},b,b^{+} \gets -1$

			%\State IsValid, IsHead $\gets$ 0
                \State IsHead $\gets$ 0
			\State Value $\gets$ $\mathbf{0}$
			%\If {$0 <$ GlobalThreadId $<$ \Call{len}{O}}
			%\State $b^{-} \gets O[$GlobalThreadId $-1]$
			%\EndIf
			%\If {GlobalThreadId $<$ \Call{len}{V} - 1}
			%\State $b^{+} \gets O[$GlobalThreadId $+1]$
			%\EndIf
			\If {GlobalThreadId $<$ \Call{len}{O}}
			\State $b \gets O[$GlobalThreadId$]$
			\State Value $\gets V[$GlobalThreadId$]$
                    \If {GlobalThreadId $>$ 0}
                        \State $b^{-} \gets O[$GlobalThreadId $-1]$
                    \EndIf
			%\State IsValid $\gets 1$
			\EndIf
			\If {LaneId $== 0$ \textbf{Or} $b^{-} \neq b$}
			%\State IsHead $\gets 1$, IsCrossWarp $\gets b^{-} == b$
                \State IsHead $\gets 1$
			%\Else
			%\State IsHead $\gets b^{-} \neq b$
%			\If {LaneId $=$ WARP\_DIM $- 1$}
			%\State IsCrossWarp $\gets b^{+} == b$
			%\EndIf
			\EndIf
			%\State Tuple $\gets$ (IsValid, IsCrossWarp)
			%\State \modify{IsValid $\gets$ {\emph{\textbf{cub::WarpReduce}}}(IsValid, IsHead)}
			% \Statex {\color[rgb]{0,0.61,0.33}// conduct reduction on the values}
			\State Value $\gets$ {\emph{\textbf{HeadSegmentedReduce}}}(Value, IsHead)
			\Statex \hspace{0.4cm} {\color[rgb]{0,0.61,0.33}// write the result to the corresponding memory location:}
			\If {IsHead \textbf{and} GlobalThreadId $<$ \Call{len}{O}}
			%\If {IsCrossWarp}
			\State \Call{AtomicAdd}{$R[b]$, Value}
			%\Else
			%\State $R[b] \gets$ Value
			%\EndIf
			\EndIf
			\EndFor
		\end{algorithmic}
	\end{algorithm}



