\title{DecentPeeR: A Self-Incentivised \& Inclusive \\ Decentralized Peer Review System}

\author{\IEEEauthorblockN{Johannes Gruendler$^1$ \quad Darya Melnyk$^1$ \quad Arash Pourdamghani$^{1,2}$ \quad Stefan Schmid$^{1,2}$}
\IEEEauthorblockA{$^1$TU Berlin, Germany $^2$Weizenbaum Institute, Germany}
