    \centering
    \includegraphics[width=1.05\columnwidth, trim=0cm 0cm 0cm 0cm, clip]{Pics/Why_CNF.png}
    \caption{The SAT solvers utilize CNF representation of circuits to check equivalence.}
    % \vspace{-0.15cm}
