Together with \Cref{lem:prodlem1}, the following statement play a crucial role in proving one of our main results. They establish that the set of $m$-fold indicator sequences is multiplicatively closed.

\begin{lemma}[Product of $m$-fold indicator sequences]\label{lem:prodmfold} The product of two distinct $m$-fold indicator sequences of distinct remainders is an $m$-fold indicator sequence.
\end{lemma}
\begin{proof} Let $\mfoldind[]{j_1}{m_1}$ and $\mfoldind[]{j_2}{m_2}$ be two $m$-fold indicator sequences such that $j_1\neq j_2$. Let $\mu=\lcm(m_1,m_2)$ and
\begin{dmath}\label{eq:mathcalN}
    \mathcal{N}\coloneqq \left\{j\in\NN:~ j<\mu~ \text{ and there exist}~j_1,j_2\in\NN,j_1<m_1,j_2<m_2,~ \begin{cases}j\equiv j_1 \mmod m_1,\\ j\equiv j_2 \mmod m_2.
    \end{cases}  \right\}.
\end{dmath}
We consider two cases: $\mathcal{N}=\emptyset$ and $\mathcal{N}\neq \emptyset$.
\begin{itemize}
    \item[Case 1:] $\mathcal{N} = \emptyset$. This means that for indices less that $\mu$, there is no coincidence of $1$ between $\mfoldind{j_1}{m_1}$ and $\mfoldind{j_2}{m_2}$. We show that when this happens, the coincidence will not occur, and thus, the corresponding product of $m$-fold indicator sequences is the zero sequence. Let $n\in\NN$ such that $n\equiv j_1\mmod m_1 \equiv j_2\mmod m_2$. So there exist $k_1,k_2\in\NN,$ such that $m_1\cdot k_1 + j_1 = m_2\cdot k_2 + j_2$. Since $\mathcal{N}=\emptyset$, there exist $k_3,j_3\in\NN$, $k_3>0$ and $j_3< \mu$ such that $n=\mu\cdot k_3 + j_3$. Thus we have
    \[ m_1\cdot k_1 + j_1 = m_2\cdot k_2 + j_2 = \mu\cdot k_3 + j_3. \]
    We obtain a contradiction since this implies $j_3\in\mathcal{N}$. Therefore if $\mathcal{N}=\emptyset$ then $\mfoldind{j_1}{m_1}\cdot \mfoldind{j_2}{m_2}=0$ for all $n\in\NN$.
    \item[Case 2:] $\mathcal{N}\neq \emptyset$. To prove that the product is an $m$-fold indicator sequence, we only need to show that $|\mathcal{N}|=1$, i.e., $\mathcal{N}$ has only one element. We proceed by contradiction. As a subset of $\NN$, $\mathcal{N}$ has a least element. Let $j_0$ be that element. Then, following the reasoning of the first case, we can find integers $k_1,k_2$ such that
    \[j_0 = m_1\cdot k_1 + j_1 = m_2\cdot k_2 + j_2.\]
    Let $j_0'\in\mathcal{N}, j_0'\neq j_0$. Then $j_0'>j_0$ and we can find $k_1'$ and $k_2'$ such that
    \[j_0' = m_1\cdot k_1' + j_1' = m_2\cdot k_2' + j_2'.\]
    Thus
    \begin{eqnarray*}
        j_0'-j_0 &=& m_1(k_1'-k_1) + j_1'-j_1\\
                 &=& m_2(k_2'-k_2) + j_2'-j_2.
    \end{eqnarray*}
    Hence $j_0'-j_0\in\mathcal{N}$. In fact, for every $l\in\NN$, if $j_0'-l\cdot j_0\geq 0$, then $j_0'-l\cdot j_0\in\mathcal{N}$. By Euclidean division, let us write $j_0'=j_0\cdot q + r$, $0\leq r <j_0$. Then $r=j_0'- j_0\cdot q \in \mathcal{N}$, contradicting the fact that $j_0$ is the smallest element in $\mathcal{N}$. Therefore if $\mathcal{N}\neq\emptyset$ then 
    \[\mfoldind{j_1}{m_1}\cdot \mfoldind{j_2}{m_2}=\mfoldind{j_0}{\mu}\] 
    for all $n\in\NN$, where $j_0$ is the unique element of $\mathcal{N}$.
\end{itemize}
\CQFD
\end{proof}
One can also prove \Cref{lem:prodmfold} using the \textit{Chinese Remainder Theorem}. The proof of \Cref{lem:prodmfold} is constructive and gives an algorithmic way to find products of $m$-fold indicator sequences. Remark that they form a multiplicative group where the one sequence $\mfoldind[]{0}{1}$ is the unit element.
\begin{example}\item
\begin{itemize}
    \item $(\mfoldind[]{1}{4})_n\cdot (\mfoldind[]{2}{6})_n = (\mfoldind[]{}{0})_n=0$.
    \item $(\mfoldind[]{3}{4})_n\cdot (\mfoldind[]{2}{5})_n = (\mfoldind[]{7}{20})_n$.
    \item $(\mfoldind[]{1}{2})_n\cdot (\mfoldind[]{1}{3})_n = (\mfoldind[]{1}{6})_n=0$.
\end{itemize}
\QEDA
\end{example}

\subsection{Definition and structure}

We are now ready to define hypergeometric-type sequences. The idea is to encompass every possible linear combination of interlaced hypergeometric terms we can think of.
\begin{definition}[Hypergeometric-type sequence]\label{def:hyptypseq} A sequence $(s)_n$ is said to be of hypergeometric type if there exist finitely many $m$-fold indicator sequences $(\mfoldind[]{j_1}{m_1})_n,\ldots,(\mfoldind[]{j_l}{m_l})_n$ such that its general term $s_n$ writes
\begin{equation}\label{eq:hyptypseq}
    s_n = H_1(\sigma_1(n))\cdot \mfoldind{j_1}{m_1} + H_2(\sigma_2(n))\cdot \mfoldind{j_2}{m_2} + \cdots + H_l(\sigma_l(n))\cdot \mfoldind{j_l}{m_l},
\end{equation}
where $\sigma_i\colon \NN \longrightarrow \QQ$ is such that $\sigma_i(m_i\cdot n + j_i)\in\NN$, and $H_i(n)$ is a $\KK$-linear combination of hypergeometric terms, $i=1,\ldots,l$. We call the $H_i$'s the coefficients of $s_n$ (or $(s)_n$).
\end{definition}
\begin{remark}\item 
\begin{itemize}
    \item In \Cref{def:hyptypseq}, we used $H_i(\sigma(n))$ instead of ${H_i}_{\sigma(n)}$ to ease the notation and avoid confusion with indices.
    \item The specification of ``finitely many'' is mainly considered for algorithmic computation, though it seems unfeasible to envision arithmetic operations when the sum in \eqref{eq:hyptypseq} is infinite.    
    \item When one of the $m$-fold indicator terms in \eqref{eq:hyptypseq} is $\mfoldind[]{0}{1}$, the corresponding summand is replaced by its coefficient.
\end{itemize}
\end{remark}

Let $(\mathcal{H}_T)$ denote the set of hypergeometric-type sequences, and $\mathcal{H}_T$ be the set of their general terms. Unless otherwise stated, we assume that if $(s)_n\in(\mathcal{H}_T)$ then $s_n\in\mathcal{H}_T$. Every hypergeometric sequence is of hypergeometric type; in particular, every polynomial and rational sequence is of hypergeometric type.
\begin{example}[An example from the OEIS \cite{sloane2003line}]\label{ex:oeis1} The general term, say $a_n$, of the sequence \href{https://oeis.org/A307717}{A307717} counts the number of palindromic squares, $n^2$, of length $n$ (in the decimal basis) such that $n$ is also palindromic. Its explicit formula (see for instance \cite{kauers2022guessing,teguia2022fps}) is given by
\begin{equation}
    a_n \coloneqq \begin{cases} 0\phantom{195 + 203n- n^2}\quad \text{ if } n\equiv 0 \mmod 2\\
                              \frac{195 + 203n - 15n^2 + n^3}{192} \quad \text{ if } n\equiv 1 \mmod 4\\
                              \frac{501 + 107n - 9n^2 + n^3}{384}\phantom{5}  \quad \text{ if } n\equiv 3 \mmod 4
                    \end{cases}.
\end{equation}
The sequence $(a)_n$ is, of course, of hypergeometric type since its general term can be written as
\begin{equation}\label{eq:oeis1}
a_n = \frac{195 + 203n - 15n^2 + n^3}{192} \mfoldind{1}{4} + \frac{501 + 107n - 9n^2 + n^3}{384} \mfoldind{3}{4}.
\end{equation}
\QEDA
\end{example}

\begin{example}\label{ex:sumprod1} Let us consider two hypergeometric terms $h_n$ and $g_n$. By using subsequences of $(h)_n$ and $(g)_n$, we can construct several hypergeometric-type sequences. For instance, the two general terms
\begin{align}
    &u_n \coloneqq h_{(n-1)/4}\mfoldind{1}{4} + h_{(n-2)/5}\mfoldind{2}{5},\\
    &v_n \coloneqq g_{(n-2)/6}\mfoldind{2}{6} + g_{(n-3)/4}\mfoldind{3}{4},
\end{align}
are of hypergeometric type. Moreover, by definition, their sum
\begin{dmath}\label{eq:sumhyp1}
    u_n+v_n = h_{(n-1)/4}\mfoldind{1}{4} + g_{(n-3)/4}\mfoldind{3}{4} + h_{(n-2)/5}\mfoldind{2}{5} + g_{(n-2)/6}\mfoldind{2}{6},
\end{dmath}
is also of hypergeometric type. For their product, using \Cref{lem:prodmfold}, one can easily show that
\begin{dmath}\label{eq:prodhyp1}
    u_nv_n = h_{(n-2)/5} g_{(n-3)/4} \mfoldind{7}{20}.
\end{dmath}
Thus their product is also of hypergeometric type since the product of hypergeometric terms is a hypergeometric term. 
\QEDA
\end{example}
The previous example illustrates a general fact concerning the closure properties of hypergeometric-type sequences. We establish it in the following theorem.
\begin{theorem}\label{th:ringtheo} The set $(\mathcal{H}_T)$ of hypergeometric-type sequences is a ring.
\end{theorem}
\begin{proof}
Let $(s)_n,(s')_n\in(\mathcal{H}_T)$, and denote by $\mathfrak{M}$ and $\mathfrak{M}'$ the sets of $m$-fold indicator terms occurring in $s_n$ and $s_n'$, respectively. So we have
\begin{align*}
    &s_n = \sum_{\chi_i\in\mathfrak{M}} H_i(\sigma_i(n)) \chi_i(n),\\
    &s_n'= \sum_{\chi_i'\in\mathfrak{M}'} H_i'(\sigma_i'(n)) \chi_i'(n).
\end{align*}
Then, we can write
\begin{dmath}\label{eq:sumproof}
    s_n+s_n'= \sum_{\chi_i\in\mathfrak{M}\cap \mathfrak{M}'} \left(H_i(\sigma_i(n)) +  H_i'(\sigma_i'(n))\right)\chi_i(n) + \sum_{\chi_i\in\mathfrak{M}\setminus \mathfrak{M}'} H_i(\sigma_i(n)) \chi_i(n) + \sum_{\chi_i'\in\mathfrak{M}'\setminus \mathfrak{M}} H_i'(\sigma_i'(n)) \chi_i'(n) \in\mathcal{H}_T.
\end{dmath}
Hence $(s+s')_n\in(\mathcal{H}_T)$.

By distributivity of the multiplication with respect to addition, the product $s_n\cdot s_n'$ yields a sum of terms of the form
\begin{equation}\label{eq:prodproof}
    H_i(\sigma_i(n))\cdot H_j'(\sigma_j'(n)) \cdot \chi_i(n)\cdot\chi_j'(n),\quad \chi_i\in\mathfrak{M}, \chi_j'\in\mathfrak{M}'.
\end{equation}
Since the product of hypergeometric terms is a hypergeometric term, and that from \Cref{lem:prodlem1} and \Cref{lem:prodmfold} we know that $\chi_i(n)\cdot\chi_j'(n)$ is an $m$-fold indicator term, say $\chi_{i,j}''$, we deduce that \eqref{eq:prodproof} can be written as $H_{i,j}''(\sigma_{i,j}''(n)) \chi_{i,j}''(n)$, where $H_{i,j}''$ is a linear combination of hypergeometric terms. Hence $(s\cdot s')_n\in(\mathcal{H}_T)$. 

In conclusion $(\mathcal{H}_T)$ is a subring of $\KK^{\NN}$.
\CQFD
\end{proof}

\subsection{Generating functions}

With their LLL-based technique of guessing, Kauers and Koutschan were able to find a $6$th-order holonomic recurrence equation of degree $9$ for the OEIS sequence \href{https://oeis.org/A307717}{A307717} of \Cref{ex:oeis1} from its first $70$ terms. We have seen that this sequence is of hypergeometric type. We want to prove that such an equation always exists for any hypergeometric-type sequence.
\begin{proposition}\label{prop:holonomicity} Every hypergeometric-type sequence is P-recursive.
\end{proposition}
\begin{proof} We give sufficient arguments that show how to construct a holonomic recurrence equation satisfied by a given hypergeometric-type term. A basic example is given in \Cref{sec:holo}. Let $(s)_n\in(\mathcal{H}_T)$ such that
\[s_n\coloneqq \sum_{i=1}^l H_i(\sigma_i(n))\mfoldind{j_i}{m_i}.\]
Then for all $n\in\NN$, $1\leq i \leq l$, $s_{m_i n + j_i}=H_i(\sigma_i(m_i n + j_i))+\epsilon_i(n)$. We neglect $\epsilon_i(n)$ and look for a recurrence equation for $u_i(m_i n + j_i)\coloneqq H_i(\sigma_i(m_i n + j_i))$. Let $l_i$ be the number of $m_i$-fold hypergeometric terms in $u_i(m_i n + j_i)$. Since $u_i(m_i n + j_i)$ is a linear combination of $m_i$-fold hypergeometric terms, a recurrence equation of order at most $m_i\cdot l_i$ can be computed (see, e.g., \cite[Section 2]{BTvariant}). This yields a recurrence equation for the index $m_i n + j_i$. To obtain a recurrence in $n$, one substitutes $n$ by $(n-j_i)/m_i$ in the equation. Let us denote by $r_i$ the order of the resulting holonomic equation.

Notice that for all $1\leq i \leq l$, any $m_j$-fold hypergeometric terms in $\epsilon_i(n)$, $j\neq i$, is considered in one of the $u_k(n)$, $k=1,\ldots,l$. Therefore the span of all $m$-fold hypergeometric terms in $s_n$ is fully covered by the solution space of the system defined by the $l$ constructed holonomic recurrence equations.

Finally, using the addition closure property of P-recursive sequences, one can compute a holonomic equation of order at most $r_1+\cdots+r_l$ (see \cite{salvy1994gfun,mallinger1996algorithmic,koutschan2014holonomic,kauers2015ore}) satisfied by $s_n$. Hence $(s)_n$ is P-recursive. \CQFD
\end{proof}
From \Cref{prop:holonomicity}, we can say that the generating functions of hypergeometric-type sequences are D-finite functions (\cite{KauersDfinite}). However, we can be more specific. From \Cref{def:hyptypseries}, we can establish a natural link between hypergeometric-type sequences and proper hypergeometric-type power series \cite{BTphd,BTWKsymbconv}.
\begin{example} Let us consider the proper hypergeometric-type power series $\cos(z) + \sin(z)$. We have
\begin{align}
    \cos(z) + \sin(z) &\coloneqq \sum_{n=0}^{\infty} \frac{(-1)^n}{(2n)!}z^{2n} + \sum_{n=0}^{\infty} \frac{(-1)^{2n+1}}{(2n+1)!}z^{2n+1}\\
                      &= \sum_{n=0}^{\infty} \left(\frac{(-1)^{n/2}}{n!}\mfoldind{0}{2} + \frac{(-1)^{(n-1)/2}}{n!}\mfoldind{1}{2}\right) z^n.
\end{align}
Thus, the general coefficient of the power series of $\cos(z)+\sin(z)$ is a hypergeometric-type term. \QEDA
\end{example}

\begin{proposition}\label{prop:seriestoseq} There is a one-to-one correspondence between proper hypergeometric-type power series and hypergeometric-type sequences.
\end{proposition}
\begin{proof} This is established by the following equality
\begin{equation}\label{eq:propcorresp}
    \sum_{i=0}^{m_j-1}\sum_{n=0}^{\infty} a_i(m_j\,n+i)\,z^{m_j\,n+i} = \sum_{n=0}^{\infty}\left(\sum_{i=0}^{m_j-1} a_i(n) \mfoldind{i}{m_j}\right) z^n,
\end{equation}
which naturally links \Cref{def:hyptypseries} and \Cref{def:hyptypseq}. 
\CQFD
\end{proof}
In other words, the generating functions of hypergeometric-type sequences are hypergeometric-type functions. Thanks to the correspondence in \Cref{prop:seriestoseq}, we can relate hypergeometric-type sequences to $\KK(x)$-linear combinations of some special functions such as Bessel functions, Airy functions, and trigonometric functions. 

\section{Algorithmic approach}\label{sec:sec2}

Our motivation to study hypergeometric-type sequences came from the purpose of this section. Hypergeometric-type terms may be present in the sciences as trigonometric or elliptic functions with discrete arguments. A connection between hypergeometric terms and elliptic curves can be found in \cite[Section 1.3]{saito2013grobner}. Our purpose is to bring those representations into ``standard'' forms. Recent results in \cite{dreyfus2022hypertranscendence} show that the only meromorphic differentially algebraic functions (\cite{RSB2023,teguia2023arithmetic}) that are P-recursive are made with periodic functions and exponentials. It is thus reasonable to think of an algorithmic approach to convert the related discrete functions into hypergeometric-type normal forms. 

In this section, it is essential to understand the difference between an object $(1,-1,1,\ldots)\in(\mathcal{H}_T)$ and its term $(-1)^n\in\mathcal{H}_T$. The former represents the sequence $((-1)^n)_n$ as a mathematical object, and the latter as its `closed' mathematical writing. We recommend \cite[Chapter 3]{geddes1992algorithms} to remove any ambiguity in this formalism.

\subsection{Canonical and normal forms}

The definition of normal and canonical forms for hypergeometric-type sequences entails assessing computability in the ring $(\mathcal{H}_T)$. Indeed, an element of $(\mathcal{H}_T)$ may have many equivalent representations in $\mathcal{H}_T$.
\begin{example}[Distinct representations of same hypergeometric-type terms, part I]\label{ex:tworep} The sequence $(\sin^2(n\pi/4))$ is of hypergeometric type and has the two following representations:
\begin{align}
    \sin^2\left(\frac{n\pi}{4}\right) &=\frac{1}{2}\left(1-(-1)^{\frac{n}{2}} \mfoldind{0}{2}\right) \label{eq:canform1}\\
                                      &= \frac{1}{2}\left(1-\frac{I^n+(-I)^n}{2}\right)\label{eq:canform2}, 
\end{align}
where $I=\sqrt{-1}$ is the imaginary unit.
\QEDA
\end{example}
The idea of a canonical form is to have a unique and ``simple'' representation of a mathematical object in a certain class, here $\mathcal{H}_T$. Observe that the representation \eqref{eq:canform2} of $s_n\coloneqq \sin^2\left(n\pi/4\right)$ requires to work on $\QQ(I)$, whereas \eqref{eq:canform1} is a formula over $\QQ$ (no extension field). Thus, \eqref{eq:canform1} and \eqref{eq:canform2} are valid in $\QQ(I)$, making \eqref{eq:canform2} less appropriate as a canonical form of $s_n$. Hence writing formulas over the minimal field extension reduces the possible representations of a hypergeometric-type term. Unfortunately, uniqueness remains an issue even in base fields. We give two examples below.
\begin{example}[Distinct representations of same hypergeometric-type terms, part II]\label{ex:nocanform}\item 
\begin{enumerate}
    \item The general coefficient of $\cosh(z)$ has the two formulas: 
    \begin{align}
    \frac{1}{n!}\mfoldind{0}{2} &= \frac{1+(-1)^n}{2\cdot n!} \label{eq:canform3}.
    \end{align}
    \item The following was observed from different formulas of the general term of \href{https://oeis.org/A212579}{A212579}:
    \begin{align}
    \frac{31}{3} - \mfoldind{0}{2} &= \frac{1}{2}\left(\frac{59}{3} - (-1)^n \right). \label{eq:canform4}
\end{align}
\end{enumerate}
\QEDA
\end{example}
While for compactness reasons, one might prefer the left-hand side for the first item in \Cref{ex:nocanform}, both sides seem to have a relatively similar compactness for the second item. We may also choose to define a canonical form by eliminating all alternations in the formula. For instance, $(-1)^n$ can be written as $\mfoldind{0}{2}-\mfoldind{1}{2}$, the latter form being seen as canonical. In this view, our canonical forms would be the left-hand sides in \Cref{ex:nocanform}. For \Cref{ex:tworep}, \eqref{eq:canform1} may be further simplified since $(-1)^{n/2}\mfoldind{0}{2}$ alternates between $-\mfoldind{0}{2}$ and $\mfoldind{0}{2}$. So, a hypergeometric-type canonical form of $\sin^2\left(n\pi/4\right)$ would contain $4$-fold indicator terms, which sounds reasonable with the $4$ occurring in its expression. However, as the second item in \Cref{ex:nocanform} shows, further simplifications need to be done to reduce the number of $m$-fold indicator terms after substituting alternating elements. The fact that $\mfoldind{0}{2}$ survived allows us to think that there might be another way to write the formula with $\mfoldind{1}{2}$. Therefore, uniqueness may not still be guaranteed.

Why do we care about canonical form at all? The main reason is that it completely solves (theoretically) the zero-equivalence problem in $\mathcal{H}_T$. However, our motivation is to bring expressions not written as elements of $\mathcal{H}_T$ into easily recognizable hypergeometric-type terms whenever possible. The above discussion presents the difficulty of defining a canonical form in $\mathcal{H}_T$ and forces us to reduce ourselves to normal forms. We have already introduced them, but we give the definition below for formal reference.
\begin{definition}[A normal form in $\mathcal{H}_T$] Any representation of a hypergeometric-type term as in \eqref{eq:hyptypseq} is a normal form.
\end{definition}

Having stated our normal form, we need to give an algorithm for the normalization. Note that this still solves the zero equivalence problem by the unique representation of the zero sequence. The remaining part of the paper describes the algorithm sustaining this fact.

\subsection{Finding holonomic recurrence equations}\label{sec:holo}
This subsection addresses finding a holonomic recurrence equation satisfied by a given hypergeometric-type ``expression''. It means that the given formula is not necessarily in the form of \eqref{eq:hyptypseq}. The algorithm behind this conversion is the first step of our general algorithm toward finding hypergeometric-type normal forms. We mention that there is no fundamental result in this part of the paper because there are many existing software to compute univariate holonomic (differential and difference) equations. Some references are \cite{salvy1994gfun,mallinger1996algorithmic,koutschan2014holonomic,kauers2015ore,FPS}. However, unlike the differential case for which software packages are easily accessible for any computer algebra system, general-purpose algorithms for finding recurrences from holonomic expressions do not seem available in the difference case. For instance, the well-known \texttt{GFUN} package \cite{salvy1994gfun} misses such an implementation. That is one reason why we decided to include this subsection. We adapt the \texttt{HolonomicDE} algorithm (available within Maple 2022 as \texttt{DEtools:-FindODE}) of \cite{FPS} to the case of recurrences. For details on the original algorithm, see the explanation from \cite{koepf1992power}. Given a term $s_n$, the aim is to find $C_1,\ldots,C_N\in\QQ(n)$ such that
\[s_{n+N}+C_N\cdot s_{n+N-1} +\cdots + C_1\cdot s_n=0.\]
We consider an efficient variant of this method as proposed in \cite[Section 4.1.2]{BTphd},\cite[Section 2]{BTWKsymbconv}. The idea is to write $s_n$ and its $N$ first shifts in the same basis and solve the linear system that expresses their linear dependency over $\KK(n)$. We explain how the algorithm works in the following example.
\begin{example}\label{ex:recn1n} Let $s_n\coloneqq n! + \frac{1}{n!}$.
\begin{enumerate}
    \item $N=0$: since $\frac{n!}{1/n!}=n!^2\notin \QQ(n)$, we consider the basis $(e_1,e_2)$, where $e_1=n!$ and $e_2=1/n!$. Thus
                            \[s_n = e_1 + e_2,\]
and at this stage, the matrix $H$ of the components is $H=[1, 1]$. The rows of $H$ are the components of $s_{n+N}$ in the $(N+1)$st basis.
    \item $N=1$: 
    \[s_{n+1}=(n+1)! + \frac{1}{(n+1)!} = (n+1)\cdot e_1 + \frac{1}{(n+1)} \cdot e_2.\]
    \[H=\begin{bmatrix}1 & 1\\ n+1 & \frac{1}{n+1}\end{bmatrix}.\] 
    Since $s_{n+1}$ and $s_n$ are written in the same basis, we try to solve the system
    \[\begin{bmatrix}1\\ 1\end{bmatrix}\cdot C = \begin{bmatrix}-(n+1) \\ -\frac{1}{n+1}\end{bmatrix},~ C\in \QQ(n).\]
    The right-hand side is the negative transpose of the last row of $H$, and the matrix of the left-hand side is the transpose of the first $N$ rows of $H$. The obtained system has no solution, so we move on to the next iteration.
    \item  $N=2$:
    \[s_{n+2}= (n+2)(n+1)\cdot e_1 + \frac{1}{(n+2)(n+1)} \cdot e_2.\]
    \[H=\begin{bmatrix}1 & 1\\ n+1 & \frac{1}{n+1}\\ (n+2)(n+1) & \frac{1}{(n+2)(n+1)}\end{bmatrix}.\] 
    We solve the system
    \[\begin{bmatrix}1 & n+1\\ 1 & \frac{1}{n+1}\end{bmatrix}\cdot C = \begin{bmatrix}-(n+2)(n+1)\\ -\frac{1}{(n+2)(n+1)}\end{bmatrix},~ C\in \QQ(n)^2,\]
    and get a unique solution
    \[C=\begin{bmatrix}C_1\coloneqq\frac{(n+3)(n+1)^2}{n(n+2)^2}\\ C_2\coloneqq-\frac{(n^2+3n+1)(n^2+3n+3)}{n(n+2)^2}\end{bmatrix}.\]
    Thus $s_n$ satisfies the equation
    \[a_{n+2} + C_2 a_{n+1} + C_1 a_n =0.\]
    After clearing denominators, we get the holonomic recurrence equation
    \begin{equation}\label{eq:recn1n}
        (n+3)(n+1)^2a_n - (n^2+3n+1)(n^2+3n+3) a_{n+1} + n(n+2)^2 a_{n+2}=0,
    \end{equation}
    satisfied by $s_n$.
\end{enumerate}
\QEDA
\end{example}

\begin{example}\label{ex:recsin2} For $\sin^2(n\pi/4)$ the algorithm leads to the recurrence
\begin{equation}
    -a_n+a_{n+1}-a_{n+2}+a_{n+3}=0.
\end{equation}
Of course, the algorithm works in this case because the expansion formulas of trigonometric functions are used.
\QEDA
\end{example}

The above-outlined algorithm cannot apply to hypergeometric-type terms written in normal forms. For those terms we use the construction highlighted in the proof of \Cref{prop:holonomicity}. We give one basic example to illustrate how it works.
\begin{example} Let $s_n= \left(\frac{1}{3^{\frac{n}{2}}}+(-5)^{\frac{n}{2}}\right)\mfoldind{0}{2} + 2^{\frac{n}{3}} \mfoldind{0}{3}$. 

We consider $u_1(2n)=\frac{1}{3^n}+(-5)^n$ and $u_2(3n)=2^n$. To find a recurrence for $u_1(2n)$, we use the addition algorithm with $2$-shifts and find
\[ 5\,u_1(2n)-14\,u_1(2n+2)-3\,u_1(2n+4)=0. \]
Hence the equation for $u_1(n)$:
\[ 5\,u_1(n) - 14\,u_1(n+2)-3\,u_1(n+4)=0. \]
Similarly, $u_2(n)$ satisfies
\[ 2\, u_2(n) - u_2(n+3) = 0.\]
Finally, using the addition closure property for holonomic sequences we get the equation
\begin{equation}
 10\,a_{n} - 28\,a_{n + 2} - 5\,a_{n + 3} - 6\,a_{n+4} + 14\,a_{n+5} +  3\,a_{n + 7} = 0,
\end{equation}
satisfied by $s_n$.
\QEDA    
\end{example}

We will denote by HolonomicRE($s_n$,$a(n)$,$d$) the algorithm that applies the algorithm in the proof of \Cref{prop:holonomicity} if $s_n$ is already in normal form, i.e., $s_n\in\mathcal{H}_T$, and the algorithm outlined in \Cref{ex:recn1n} otherwise. The output is either a holonomic recurrence equation of order at most $d\in\NN$ in the indeterminate $a(n)$, or \texttt{FAIL} when such an equation is not found. We can omit $d$ for hypergeometric-type terms since the recurrence is obtained by construction and not by search. 

We mention that $\sin^2(z\pi/4)$ also satisfies a holonomic differential equation. The work in \cite{dreyfus2022hypertranscendence} suggests that we can use trigonometric functions to generate terms that satisfy holonomic recurrence equations. The remaining steps of our algorithm help to verify whether these terms are of hypergeometric type or not.

\subsection{Finding normal forms}

Let $(s)_n\in(\mathcal{H}_T)$ such that the given expression $s_n$ is not an element of $\mathcal{H}_T$. We want to find a representation of $s_n$ in $\mathcal{H}_T$. Suppose that $s_n$ is a solution of the following $d$th-order recurrence equation:
\begin{equation}\label{eq:REnform}
    P_d(n) a_{n+d} + P_{d-1}(n)a_{n+d-1}+\cdots+ P_0(n)a_n=0, 
\end{equation}
with polynomial coefficients $P_d,P_{d-1},\ldots,P_0\in\KK[x],$ $P_dP_0\neq 0$. Using mfoldHyper \cite[Section 3]{BTWKsymbconv}, we can compute a basis of $m$-fold hypergeometric term solutions of \eqref{eq:REnform}. This may be written as
\begin{equation}\label{eq:nformbasis}
    \mathfrak{B}\coloneqq \left\lbrace \left\lbrace m_i,\mathfrak{B}_i\right\rbrace, i=1,\ldots,N\right\rbrace \coloneqq  \left\lbrace \left\lbrace m_i,\left\lbrace h_{i,1}(m_in),\ldots,h_{i,l_i}(m_in)\right\rbrace\right\rbrace, i=1,\ldots,N\right\rbrace,
\end{equation}
$m_i\in\NN\setminus \lbrace 0 \rbrace$. For each $h_{i,j}\in \mathfrak{B}_i$, there are $m_i-1$ other solutions, namely $h_{i,j}(m_in+k_j)$, $k_j=1,~\ldots,m_i-1$. These other solutions can also be generated by mfoldHyper at the user's request. Note that the reason why the basis \eqref{eq:nformbasis} is written in this form is because the primary purpose of mfoldHyper is to find general coefficients of formal power series. We recall that mfoldHyper is an extension of the algorithms by Petkov\v{s}ek (Hyper) and van Hoeij \cite{petkovvsek1992hypergeometric,van1999finite,BTvariant}. Thanks to the correspondence of \Cref{prop:seriestoseq}, the output of mfoldHyper can be easily used to find a hypergeometric-type representation of $s_n$.

To obtain a hypergeometric-type formula for $s_n$, we look for constant coefficients $c_{i,j,k_j}\in\KK, i=1,\ldots,N,$ $j=1,\ldots,l_i$, $k_j=0,\ldots,m_i-1$, such that
\begin{equation}\label{eq:ansatz}
    s_n = \sum_{0\leq k_j\leq m_i-1, 1\leq j\leq l_i, 1\leq i\leq N} c_{i,j,k_j} h_{i,j,k_j}(n) \mfoldind{k_j}{m_i}.
\end{equation}
We evaluate both sides of \eqref{eq:ansatz} to obtain a Cramer system for the unknown $c_{i,j,k_j}$'s. Its solutions lead to a hypergeometric-type representation of $s_n$. We mention that the resulting system can have many solutions because some sub-bases or mixing of elements from the basis in \eqref{eq:nformbasis} may span the same vector space over different field extensions. Nevertheless, we need to select one of them to get the normal form we want. Let us give some examples.

\begin{example}[$s_n\coloneqq\sin^2\left(\frac{n\pi}{4}\right)$]\label{ex:sin2nform} As presented in \Cref{ex:recsin2}, $s_n$ satisfies the recurrence equation:
\[-a_n+a_{n+1}-a_{n+2}+a_{n+3}=0.\]
Algorithm mfoldHyper finds the following basis of solutions over $\QQ$:
\begin{equation}
    \left\{ \left\{1,\{1\}\right\}, \left\{2,\{(-1)^n\}\right\}\right\}.
\end{equation}
More solutions can be found if one enables computations over field extensions. This is avoided as much as possible to have the chance to obtain a normal form over the base field. We write
\[s_n = c_1 + c_2 (-1)^{\frac{n}{2}}\mfoldind{0}{2} + c_3 (-1)^{\frac{n-1}{2}}\mfoldind{1}{2},\]
and use the first terms $s_0,s_1,s_2$ to obtain the linear system
\[
    \begin{cases}
        c_1 + c_2 = 0\\
        c_1 + c_3 = \frac{1}{2}\\
        c_1 - c_2 = 1
    \end{cases}.
\]
The system has a unique solution which leads to the following normal form for $s_n$:
\begin{equation}
    s_n=\sin^2\left(\frac{n\pi}{4}\right) = \frac{1}{2} - \frac{(-1)^{\frac{n}{2}}}{2}\mfoldind{0}{2}
\end{equation}
\QEDA
\end{example}

\begin{example}[$s_n\coloneqq \sin\left(\frac{\pi}{6}\cos\left(n\pi\right)\right)\sin\left(\frac{n\pi}{4}\right)$]\label{ex:nformex2} The given term satisfies the recurrence equation:
\begin{equation}\label{eq:recnformex2}
    a_n + \sqrt{2} a_{n+1} + a_{n+2}=0.
\end{equation}
This equation does not have $m$-fold hypergeometric term solutions over $\QQ$, not even over $\QQ(\sqrt{2})$. Enabling extension fields allows mfoldHyper to find the basis of solutions
\begin{equation}\label{eq:b1nformex2}
    \left\{\left\{1, \left\{\left(\texttt{RootOf}\left(1+\sqrt{2} X + X^2\right)\right)^n\right\}\right\}\right\},
\end{equation}
where $\texttt{(RootOf(P(X)))}^n$ is a compact notation of $\alpha^n$, for all $\alpha, P(\alpha)=0$. Thus we have two hypergeometric terms over $\QQ(\sqrt{2}, I)$. The algorithm can proceed as in \Cref{ex:sin2nform} and find a hypergeometric-type representation of $s_n$. However, as this is not what our implementation will do (\Cref{sec:sec3}), we want to present a technique that our implementation does to avoid field extensions. This may also justify why we cannot always find normal forms over base fields. The point is, as designed, the algorithm of \Cref{sec:holo} tries to compute a holonomic recurrence equation of the smallest order. However, the least-order recurrence equation may not contain term solutions over the base field of the given hypergeometric-type sequence. Thus, it might be relevant to look for other recurrence equations. To do so, we ask the algorithm to search for a recurrence equation between $2$-shifts of $s_n$, i.e., $s_n, s_{n+2}, s_{n+4},$ $\ldots$. We obtain the two-term recurrence equation
\begin{equation}\label{eq:rec2nformex2}
    a_n + a_{n+4} = 0.
\end{equation}
Hence, the basis of term solutions over $\QQ$:
\begin{equation}
    \left\{\left\{4,\left\{\left(-1\right)^{n}\right\}\right\}\right\}.
\end{equation}
At this stage, we are sure to obtain a normal form in the corresponding base field since any algebraic number in the formula will come from the evaluation of $s_n$. For the ansatz
\begin{dmath*}
    s_n = c_0 (-1)^{\frac{n}{4}}\mfoldind{0}{4} +  c_1 (-1)^{\frac{n-1}{4}}\mfoldind{1}{4} +  c_2 (-1)^{\frac{n-2}{4}}\mfoldind{2}{4} +  c_3 (-1)^{\frac{n-3}{4}}\mfoldind{3}{4},
\end{dmath*}
we get the linear system:
\[
\begin{cases}
c_0=0\\
c_1=-\frac{\sqrt{2}}{4}\\
c_2=\frac{1}{2}\\
c_3=-\frac{\sqrt{2}}{4}
\end{cases}.
\]
Therefore
\begin{dmath*}
    s_n = \sin\left(\frac{\pi}{6}\cos\left(n\pi\right)\right)\sin\left(\frac{n\pi}{4}\right) =  -\frac{(-1)^{\frac{n-1}{4}}\,\sqrt{2}}{2}\mfoldind{1}{4} +  \frac{1}{2} (-1)^{\frac{n-2}{4}}\mfoldind{2}{4} +  -\frac{(-1)^{\frac{n-3}{4}}\,\sqrt{2}}{4}\mfoldind{3}{4}
\end{dmath*}
\QEDA
\end{example}

Let us present all the steps of our algorithmic approach to detecting hypergeometric-type terms by writing them in normal forms.

\vspace{-0.25cm}

\begin{algorithm}[ht]\caption{ Finding hypergeometric type formulas }\label{algo:Algo1}
    \begin{algorithmic} 
    \\ \Require A general term $s_n$ of a sequence $(s)_n\in\KK^{\NN}$, and a positive integer $d$. If $s_n\in\mathcal{H}_T$, then $d$ may be computed as: the sum of (number of hypergeometric term in each coefficient) $\times$ (the corresponding characteristic).
    \Ensure Either 
    \begin{itemize}
        \item \texttt{FAIL}, meaning that ``no holonomic recurrence equation of order at most $d$ was found'';
        \item a holonomic recurrence equation of order at most $d$ with enough initial values to identify $(s)_n$ uniquely: this means that ``$(s)_n\notin (\mathcal{H}_T)$'';
        \item a hypergeometric-type normal form, meaning that ``$(s)_n\in(\mathcal{H}_T)$''.
    \end{itemize} 
    \begin{enumerate}
    \item Apply HolonomicRE$(s_n,a(n),d)$ (\Cref{sec:holo}) and call the result $RE$.
    \item If $RE=\texttt{FAIL}$ then stop and return it. //comment: $d$ may be small.
    \item \label{setp:retohts} $RE$ is a holonomic recurrence equation of order $r\leq d$. Use \texttt{mfoldHyper} to compute a basis of $m$-fold hypergeometric term solutions of $RE$ over $\KK$ and denote it $\mathfrak{B}$.
    \item If $\mathfrak{B}$ is empty then stop and return $RE$ together with $a_0=s_0,\ldots,a_{r-1}=s_{r-1}$.
    \item $\mathfrak{B}$ is not empty and has the form 
            \[\mathfrak{B}\coloneqq \left\lbrace \left\lbrace m_i,\left\lbrace h_{i,1}(m_in),\ldots,h_{i,l_i}(m_in)\right\rbrace\right\rbrace, i=1,\ldots,N\right\rbrace,\]
        as in \eqref{eq:nformbasis}. Let
        \[u_n \coloneqq \sum_{0\leq k_j\leq m_i-1, 1\leq j\leq l_i, 1\leq i\leq N} c_{i,j,k_j} h_{i,j,k_j}(n) \mfoldind{k_j}{m_i},\]
        as in \eqref{eq:ansatz}, with the unknown constants $c_{i,j,k_j}\in\KK, i=1,\ldots,N,$ $j=1,\ldots,l_i$, $k_j=0,\ldots,m_i-1$.
    \item\label{step:p} Let $p$ be the number of constant $c_{i,j,k_j}$. $p=\sum_{i=1}^N m_i\cdot l_i$
    \item\label{step:E0} Let $E_0$ be a finite set of non-negative integers that are not roots of the leading and the trailing polynomial coefficients of $RE$, such that $E_0$ evaluates $u_n=s_n$ to a linear system of rank at least $p$.
    \item Solve the linear system $u_j=s_j, j\in E_0$, and let $S$ be the set of solutions.
    \item \label{step:solsys} If $S$ is empty then stop and return $RE$ together with $a_0=s_0,\ldots,a_{r-1}=s_{r-1}$.
    \item Return the substitution of a solution in $S$ into $u_n$.
    \end{enumerate}	
    \end{algorithmic}
\end{algorithm}

\vspace{-0.75cm}

\begin{remark}\label{rem:rem1}\item 
\begin{itemize}
    \item Note that we omitted the steps where we try to avoid field extensions to simplify the algorithm. The idea is to use mfoldHyper over $\QQ$ in step \ref{setp:retohts} with a few more recurrences satisfied by $s_n$, and see if it leads to a non-empty $S$ at step \ref{step:solsys}.
    \item The reason for avoiding roots of the leading and the trailing coefficients is a singularity issue. See the discussion in \cite[Section 2.2]{KauersDfinite}.
    \item The set $E_0$ in step \ref{step:E0} can be chosen as $\{n_0,\ldots,n_0+p\}$, where $n_0$ is a non-negative integer strictly greater than the maximum integer root of the leading and the trailing polynomial coefficients. However, finding $n_0$ that way may not be the best approach when symbolic values occur in the equation. One could look for such integer intervals by evaluation at consecutive indices starting from $0$. The latter approach would be inappropriate in today's computer only if the recurrence equation has thousands or billions of $m$-fold hypergeometric term solutions.
\end{itemize}
\end{remark}

\begin{theorem}\label{th:theo2} \Cref{algo:Algo1} is correct.
\end{theorem}

\Cref{th:theo2} is deduced from the previous paragraphs and \Cref{rem:rem1}. \Cref{algo:Algo1} is a transformation for finding normal forms of hypergeometric-type terms for which holonomic recurrence equations are found in its first step. The zero sequence may be returned as $0$ or as the zeroth-order holonomic recurrence equation. Thus, we can identify distinct hypergeometric-type terms.

\section{Implementation}\label{sec:sec3}

We implemented \Cref{algo:Algo1} with Maple as a command in the package \texttt{HyperTypeSeq} \cite{HyperTypeSeq}. The package currently contains three commands: \texttt{HolonomicRE}, \texttt{REtoHTS}, and \texttt{HTS}.
\begin{enumerate}
    \item \texttt{HolonomicRE} adapts \texttt{HolonomicDE} from \texttt{FPS} \cite{FPS} to search for a holonomic recurrence equation from an expression and a given bound. The syntax is 
    \[\texttt{HolonomicRE}(\texttt{expr},\texttt{a}(\texttt{n}),\texttt{maxreorder}=\texttt{d},\texttt{reshift}=\texttt{t}),\]
    where \texttt{maxreorder} and \texttt{reshift} are optional with default values $10$ and $1$, respectively. \texttt{expr} is a term in \texttt{n}, and \texttt{a} is the name of the unknown for the equation. \texttt{maxreorder} is the maximum order of the holonomic recurrence equation sought, and \texttt{reshift} is the minimal possible shift of $\texttt{a}(\texttt{n})$ in the recurrence equation sought. The current version of \texttt{HolonomicRE} still misses an implementation for finding recurrence equations from hypergeometric-type terms containing $m$-fold indicator terms.
    \item \texttt{REtoHTS} applies \Cref{algo:Algo1} from step \ref{setp:retohts}. The syntax is
    \[\texttt{REtoHTS}(\texttt{RE},\texttt{a}(\texttt{n}),\texttt{P}).\]
    \texttt{RE} is the holonomic recurrence equation and \texttt{a}(\texttt{n}) is the unknown term in it. \texttt{P} is a procedure for computing values of the sequence at any index. \texttt{P} can also be a list of initial values; however, the list must contain the values of the evaluations of \texttt{expr} starting from $0$. 

    With finding holonomic recurrence equations for sequences in enumerative combinatorics, \texttt{REtoHTS} may be useful for finding new formulas.
    \item \texttt{HTS} implements \Cref{algo:Algo1} with the syntax
    \[\texttt{HTS}(\texttt{expr},\texttt{n}),\]
    with self-explanatory arguments from the previous commands. The argument \texttt{maxreorder} is also optional for \texttt{HTS}.
\end{enumerate}

