  (\emph{v}) a composition, 
  %
  $$ (⨾) ፡ ℂ_A(X;Y) × ℂ_B(Y;Z) → ℂ_{A ⊲ B}(X;Z);$$
  %
  and (\emph{vi}) a tensoring operation on morphisms,
  %
  $$ (⊗) ፡ ℂ_A(X;Y) × ℂ_{A'}(X';Y') → ℂ_{A ⊗ A'}(X ⊗ X'; Y ⊗ Y');$$
  %
  apart from (\emph{vii}) a special identity on the monoidal unit, $i_I ∈ ℂ_I(I;I)$.

  It must satisfy the following axioms, wherever well-typed.
  \begin{enumerate}
    \item $f ⨾ \id{} = f = \id{} ⨾ f$;
    \item $f ⨾ (g ⨾ h) = (f ⨾ g) ⨾ h$;
    \item $f ⊗ \id_I = f = \id_I ⊗ f$;
    \item $f ⊗ (g ⊗ h) = (f ⊗ g) ⊗ h$;
    \item $f[\id{}] = f$, and, in particular, $\id_X[\id_N] = \id_X$;
    \item $f[α ⨾ β] = f[α][β]$;
    \item $f[α] ⨾ g[β] = (f ⨾ g)[α ⊲ β]$;
    \item $f[α] ⊗ g[β] = (f ⊗ g)[α ⊗ β]$;
    \item $((f ⨾ g) ⊗ (f' ⨾ g'))[ψ] = (f ⊗ f') ⨾ (g ⊗ g')$;
    \item $i_I[ψ'] = \id_I$;
  \end{enumerate}  
  where we use the structure maps, $ψ ፡ (A ⊲ B) ⊗ (C ⊲ D) → (A ⊗ C) ⊲ (B ⊗ D)$ and $ψ' ፡ I → N$.
\end{definition}
\end{toappendix}

\begin{definition}[Duoid-graded monoidal category]
  For a \kl{duoid}, $(A,≤, ⊕, 0, ↑, ⊥)$, an $A$-graded (strict) monoidal
  category, $(ℂ,⊗,I)$, consists of (\emph{i}) a monoid of objects $(ℂ_{obj},⊗,I)$;
  (\emph{ii}) a set of morphisms, $ℂ_a(X;Y)$, for each grade $a ∈ A$ and each pair of
  objects $X,Y ∈ ℂ_{obj}$; (\emph{iii}) a regrading operation
  %
  $$(•)[a ≤ b] ፡ ℂ_a(X;Y) → ℂ_b(X;Y)\mbox{, for each inequality }a ≤ b;$$
  %
  (\emph{iv}) an identity morphism, $\id_X ∈ ℂ_0(X;X)$; (\emph{v}) a composition,
  %
  $$(⨾) ፡ ℂ_a(X;Y) × ℂ_b(Y;Z) → ℂ_{a ⊕ b}(X;Z);$$
  %
  and (\emph{vi}) a tensoring operation on morphisms
  %
  $$
  (⊗) ፡ ℂ_a(X;Y) × ℂ_{a'}(X';Y') → ℂ_{a ↑ a'}(X ⊗ X'; Y ⊗ Y');
  $$
  %
  apart from a special identity on the monoidal unit, $i_I ∈ ℂ_{⊥}(I;I)$.

  It must satisfy the following axioms, whenever well-typed.
  \begin{enumerate}
    \item $f ⨾ \id{} = f = \id{} ⨾ f$;
    \item $f ⨾ (g ⨾ h) = (f ⨾ g) ⨾ h$;
    \item $f ⊗ \id_I = f = \id_I ⊗ f$;
    \item $f ⊗ (g ⊗ h) = (f ⊗ g) ⊗ h$;
    \item $f[a ≤ a] = f$, and, in particular, $\id_X[⊥ ≤ ⊥] = \id_X$;
    \item $f[a ≤ c] = f[a ≤ b][b ≤ c]$;
    \item $f[a ≤ b] ⨾ g[c ≤ d] = (f ⨾ g)[a ⊕ c ≤ b ⊕ d]$;
    \item $f[a ≤ b] ⊗ g[c ≤ d] = (f ⊗ g)[a ↑ c ≤ b ↑ d]$;
    \item $((f ⨾ g) ⊗ (f' ⨾ g'))[(a ⊕ b) ↑ (c ⊕ d) ≤ (a ↑ c) ⊕ (b ↑ d)] = (f ⊗ f') ⨾ (g ⊗ g')$;
    \item $i_I[⊥ ≤ 0] = \id_I$;
  \end{enumerate}
\end{definition}


