\begin{remark}
  We will be mostly concerned with symmetric monoidal categories graded over a
  normal and commutative maximum-duoid. Note how the interchange law does
  not hold automatically, $(f ⨾ h) ⊗ (g ⨾ k)$ takes equal or less time than $(f
  ⊗ g) ⨾ (h ⊗ k)$; but we can equate both by waiting during that difference of time.
\end{remark}

\section{Double categories}

\subsection{Double categories}
The usual definition of a \kl{double category} is that of a category internal to
the finitely complete category of small categories.

\begin{definition}[Double categories]
  A (strict) \emph{\intro{double category}} $𝔻$ consists of (\emph{1}) a set of
  objects, $𝔻_{obj}$; (\emph{2}) sets of arrows (or, \emph{horizontal arrows})
  $\smash{𝔻_{h}(X; Y)}$ for each pair of objects, $X,Y ∈ 𝔻_{obj}$;
  (\emph{3}) sets of arrows (or, \emph{vertical arrows})
  $\smash{𝔻_{v}(X; Y)}$ for each pair of objects, $X, Y ∈ 𝔻_{obj}$;
  and (\emph{4}) sets of cells, $𝔻(U;H;K;V)$, for each compatible quadruple of two
  vertical arrows $U ∈ 𝔻_{v}(X;Y)$ and $V ∈ 𝔻_{v}(Z;W)$, and two horizontal arrows
  $H ∈ 𝔻_{h}(X;Z)$ and $K ∈ 𝔻_{h}(Y;W)$.

  \kl{Double categories} have operations for vertical and horizontal composition of
  compatible 2-cells along their horizontal and vertical boundaries. These compositions
  are associative and unital and moreover respect the interchange law.
\end{definition}

\begin{definition}[Double signature]
  \AP A \emph{\intro{double signature}}, $Σ = (𝒪,ℋ,𝒱,𝓓)$, consists of (\emph{1}) a set
  of objects, $𝒪$; (\emph{2}) two graphs on these objects, given by sets $ℋ(X;Y)$ and
  $𝒱(X;Y)$ for each pair of objects, $X, Y ∈ 𝒪$; (\emph{3}) sets of generators,
  %
  $$𝓓_{X,Y,Z,W}(u_1,...,u_n;h_1,...,h_p;k_1,...,k_q;v_1,...,v_m),$$
  %
  for each four objects $X,Y,Z,W ∈ 𝒪$, and each quadruple of composable paths
  given by $\pmb{u} = u₁,...,u_n ∈ \Path(𝒱)(X;Y)$ and $\pmb{h} = h_1,...,h_p ∈
  \Path(ℋ)(Y;W)$, with $\pmb{v} = v_1,...,v_m ∈ \Path(Z;W)$, and $\pmb{k} =
  k_1,...,k_q ∈ \Path(ℋ)(X;Z)$.
\end{definition}

\begin{proposition}[Double signature morphism]
  \AP A \emph{\intro{double signature morphism}}, $α ፡ Σ → Σ'$, between
  two \kl{double signatures}, $Σ = (𝒪,ℋ,𝒱,𝓓)$ and $Σ' = (𝒪',ℋ',𝒱',𝓓')$,
  consists of 
  \begin{enumerate}
    \item a function on objects, $α_{obj} ፡ 𝒪 → 𝒪'$;
    \item two graph homomorphisms, with that same underlying function on
    objects, $α_H ፡ ℋ → ℋ'$ and $α_V ፡ 𝒱 → 𝒱'$, which extend to functors,
    $α_H^{∗}$ and $α_V^{∗}$; and
    \item a function on cells, preserving the boundary graphs,
    $$α ፡ 𝓓_{X,Y,Z,W}(\pmb{u};\pmb{h};\pmb{k};\pmb{v}) → 
    𝓓'_{α(X),α(Y),α(Z),α(W)}(α_V^{∗}(\pmb{u});α_H^{∗}(\pmb{h});α_H^{∗}(\pmb{k});α_V^{∗}(\pmb{v})).$$
  \end{enumerate}
  \kl{Double signatures} and \kl{double signature morphisms} form a category, $\doubleSig$.
\end{proposition}

\begin{proposition}[Forgetful double signatures]
  \AP The \intro{forgetful double signature} of a \kl{double category},
  $𝔻$, is a \kl{double signature} $Σ = (𝒪,ℋ,𝒱,𝓓)$ given by
  \begin{enumerate}
    \item the objects of the \kl{double category}, $𝒪 = 𝔻_{obj}$;
    \item the horizontal cells of the \kl{double category}, $ℋ(X;Y) = 𝔻_h(X;Y)$;
    \item the vertical cells of the \kl{double category}, $𝒱(X;Y) = 𝔻_v(X;Y)$;
    \item the 2-cells of the \kl{double category}, for each quadruple of composable paths
    given by $\pmb{u} = u₁,...,u_n ∈ \Path(𝒱)(X;Y)$ and $\pmb{h} = h_1,...,h_p ∈
    \Path(ℋ)(Y;W)$, with $\pmb{v} = v_1,...,v_m ∈ \Path(Z;W)$, and $\pmb{k} =
    k_1,...,k_q ∈ \Path(ℋ)(X;Z)$, we have
    $𝓓(\pmb{u}; \pmb{h}; \pmb{k}; \pmb{v}) = 
    𝔻(u_1 ⊗ ... ⊗ u_n; h_1 ⊗ ... ⊗ h_p; k_1 ⊗ ... ⊗ k_q; v_1 ⊗ ... ⊗ v_m).$
  \end{enumerate}
  The construction of the \kl{forgetful double signature} induces a functor from
  \kl{double categories} to \kl{double signatures} with strict double functors
  $\mathsf{forget} ፡ \mathsf{doubleCat} → \doubleSig$.
\end{proposition}

\subsection{Double categories from timed polygraphs}

Polygraphs are signatures for monoidal categories: they comprise some generating
objects and some basic processes from which all the others are built. If we
declare how much time these building blocks take, we can deduce how much every
composite process will take. This is the idea behind a \kl{timed polygraph}:
they are signatures for timed process theories.

\begin{definition}[Timed polygraph]
  \AP A \emph{\intro{timed polygraph}} $Ψ$ consists of a set of objects, $Ψ_obj$,
  and for each two lists of objects, $X_1,...,X_n ∈ Ψ_{obj}$ and $Y_1,...,Y_m ∈
  Ψ_{obj}$, and each natural number $t ∈ ℕ$, a set of generators,
  $Ψ_t(X_1,...,X_n; Y_1,...,Y_m)$.
\end{definition}

\begin{definition}[Timed polygraph morphism]
  \AP A \emph{\intro{timed polygraph morphism}}, $α ፡ Ψ → Ξ$, consists of a function
  between the object sets, $α_{obj} ፡ Ψ_{obj} → Ξ_{obj}$, and a function between generators
  that preserves time, inputs and outputs,
  $$α ፡ Ψ_{t}(X_1,...,X_n; Y_1,...,Y_m) → Ξ_{t}(α(X_1),...,α(X_n); α(Y_1),...,α(Y_m)).$$
\end{definition}

\begin{proposition}[Double signature from a timed polygraph]
  Every \kl{timed polygraph} $Ψ$ induces a \kl{double signature},
  $\mathsf{draw}(Ψ) = (𝒪,ℋ,𝒱,𝓓)$, containing
  \begin{enumerate}
    \item a single object, $𝒪 = \{ ∗ \}$;
    \item a single horizontal generator, $ℋ(∗,∗) = \{ 1 \}$;
    \item a vertical generator for each object, $𝒱(∗,∗) = Ψ_{obj}$;
    \item and three kinds of cells: a cell for each timed generator, 
    $$𝓓(X_1,...,X_n;t;t;Y_1,...,Y_m) = Ψ_t(X_1,...,X_n;Y_1,...,Y_m),$$
    and, additionally, ``waiting'' cell, $𝓓(X;1;1;X) = Ψ_1(X;X) + \{\mathrm{wait}\}$, and a ``braiding'' cell
    $𝓓(X,Y;0;0;Y,X) = Ψ_0(X,Y;Y,X) + \{σ\}$ (see \Cref{fig:timing-signature}).
  \end{enumerate}
  This assignment extends to a functor $\mathsf{draw} ፡ \tPolygraph → \doubleSig$.
\end{proposition}

\begin{figure}[!ht]
  \includegraphics[width=0.7\textwidth]{fig-timing-signature.pdf}
  \caption{Double signature from a timed polygraph.}
  \label{fig:timing-signature}
\end{figure}

\begin{proposition}[Double category from a timed polygraph]
  Every \kl{timed polygraph}, $Ψ$ induces a \kl{double category} freely
  generated by its associated \kl{double signature}, $\mathsf{draw}(Ψ)$, and
  quotiented by the equations in \Cref{fig:timing-equations}.
\end{proposition}

\begin{figure}[!ht]
  \includegraphics[width=0.75\textwidth]{fig-timing-equations.pdf}
  \caption{Equations for the double category from a timed polygraph.}
  \label{fig:timing-equations}
\end{figure}


\subsection{Towards pinwheel double categories}
String diagrams for double categories face a problem: not every plane
arrangement of composable cells can be explained in terms of the algebra of
double categories \cite{dawson1995forbidden}. Those that can be explained were described by Dawson as
``neat tilings'' and characterized as those that do not contain a full
\emph{pinwheel} (\Cref{fig:pinwheels}): the only obstruction to composition in double categories
are pinwheels.

\begin{example}
  Consider a quintuple of timed processes: $f$ and $h$ take two units of time,
  while $g$, $k$, and $a$ take a single unit. The resources of $a$ and $h$
  depend on $g$, while the resouces of $k$ depend on $f$ and $a$. 
  %
  We could: %
  \emph{(1)} execute $f$ and $g$ in parallel; %
  \emph{(2)} when $g$ finishes, execute $a$ and $h$ in parallel; %
  \emph{(3)} when both $f$ and $a$ finish, execute $k$; %
  and \emph{(4)} both $h$ and $k$ will finish at the same time, after 4 units of time.
  There is no physical limitation for this arrangement, but it is disallowed by
  the algebra of double categories (\Cref{fig:pinwheels}, left).

\begin{figure}[!ht]
  \includegraphics[width=0.5\textwidth]{fig-pinwheels.pdf}
  \caption{Two valid timings that form pinwheels.}
  \label{fig:pinwheels}
\end{figure}
\end{example}

However, this means double categories cannot be the algebraic structure that
encodes all possible combinations of timing processes. The pinwheel represents a
valid timing, and so we should account for it. Instead, we need more algebraic
structure: we need double categories \emph{with pinwheels}. Recent work by
Delpeuch will enable this route \cite{delpeuch20:word}.



\section{Double categories with pinwheels}%
\label{sec:doubleWithPinwheels}%

All uses the double categories that do not rely on the exclusion of pinwheels
can be recasted for 2-categories, gaining the  extra expressivity for pinwheels
in the process \cite{delpeuch20:word}. The main idea is that any 2-cell in a
double category can be ``tilted'' and interpreted as a 2-cell in a corresponding
2-category that has, as generating objects, both the vertical and horizontal
cells of the double category (\Cref{fig:tilted-double-cell}).

\begin{figure}[!ht]
  \includegraphics[width=0.5\textwidth]{fig-tilted-double-cell.pdf}
  \caption{Double cells can be tilted to 2-cells.}
  \label{fig:tilted-double-cell}
\end{figure}

In formal terms, each \kl{double signature} can be translated into a
\kl{2-graph} that generates the free double category with pinwheels.

\begin{definition}[Tilted 2-graph]
  The \emph{\intro{tilted 2-graph}} of a \kl{double signature} $Σ =
  (𝒪,ℋ,𝒱,𝓓)$ is the \kl{2-graph}, $\tilt(Σ)$, defined as having
  \begin{itemize}
    \item the same 0-cells, $\tilt(Σ)_{obj} = 𝒪$;
    \item both vertical and horizontal 1-cells, $\tilt(Σ)(X;Y) = 𝒱(X;Y) +
    ℋ(X;Y)$;
    \item the same 2-cells between $X ∈ 𝒪$ and $W ∈ 𝒪$ when paths are composed
    precisely of $\pmb{u} = u_1,...u_n ∈ \Path(𝒱)(X;Y)$ and $\pmb{h} =
    h_1,...,h_p ∈ \Path(ℋ)(Y;W)$, with $\pmb{v} = v_1,...,v_m ∈ \Path(𝒱)(Z;W)$
    and $\pmb{k} = k_1,...,k_q ∈ \Path(ℋ)(X;Z)$, for any two $Y, Z ∈ 𝒪$; that
    is,
    $$
    \qquad\qquad \tilt(Σ)_{X,W}(u_1,...,u_n,h_1,...,h_p; k_1,...,k_q,v_1,...,v_n) = 
    𝓓_{X,Y,Z,W}(\pmb{u};\pmb{h};\pmb{k};\pmb{v});
    $$
    and empty otherwise, with $\tilt(Σ)(x_1,...,x_n;y_1,...,y_m) = ∅$ for any
    other two given paths $\pmb{x} = x_1,...,x_n ∈ \Path(\tilt(Σ))(X;W)$ and $\pmb{y}
    = y_1,...,y_m ∈ \Path(\tilt(Σ))(X;W)$.
  \end{itemize}
\end{definition}


From this \kl{2-graph}, we can construct its free \kl{2-category}, 
$\mathsf{string}(\tilt(Σ))$. String diagrams for this category contain the cells
of the pinwheel double category we want to construct, but they also contain many
diagrams that cannot be interpreted as double cells: we use those that do to
construct the tentative \emph{free \kl{pinwheel double category}} over a
\kl{double signature}.

\begin{definition}[Pinwheel double category]
  Any \kl{double signature}, $Σ = (𝒪,ℋ,𝒱,𝓓)$, generates a strict \kl{double category},
  $\mathsf{pinwheel}(Σ)$, having
  \begin{enumerate}
    \item objects from its signature $\mathsf{pinwheel}(Σ)_{obj} = 𝒪$;
    \item horizontal paths, composing as such, $\mathsf{pinwheel}(Σ)_{h} = \Path(ℋ)$;
    \item vertical paths, composing as such, $\mathsf{pinwheel}(Σ)_{v} = \Path(𝒱)$;
    \item cells the string diagrams constructed from the \kl{tilted 2-graph};
    that is, for $\pmb{u} = u_1,...u_n ∈ \Path(𝒱)(X;Y)$ and $\pmb{h} =
    h_1,...,h_p ∈ \Path(ℋ)(Y;W)$, with $\pmb{v} = v_1,...,v_m ∈ \Path(𝒱)(Z;W)$
    and $\pmb{k} = k_1,...,k_q ∈ \Path(ℋ)(X;Z)$, we have that the set of cells
    $\mathsf{pinwheel}(Σ)(\pmb{u};\pmb{h};\pmb{k};\pmb{v})$ is defined by
    $$\mathsf{string}(\tilt(Σ))(u_1 ⊗ ... ⊗ u_n ⊗ h_1 ⊗ ... ⊗ h_p; k_1 ⊗ ... ⊗ k_q ⊗ v_1 ⊗ ... ⊗ v_m).$$
  \end{enumerate}
  Horizontal and vertical composition for this double category are given by compositions of 2-categorical
  string diagrams, following \Cref{fig:tilted-compositions}.
\end{definition}

\begin{figure}[!ht]
  \includegraphics[width=0.5\textwidth]{fig-tilted-compositions.pdf}
  \caption{Horizontal and vertical compositions in the tilted 2-category.}
  \label{fig:tilted-compositions}
\end{figure}


\begin{proposition}[Pinwheel monad]
  \AP Pinwheel forms a monad
  $$\mathsf{Pinwheel} = (\mathsf{forget} ⨾ \mathsf{pinwheel}) ፡ \doubleSig → \doubleSig.$$
\end{proposition}

\begin{definition}[Pinwheel double category]
  \AP \intro{Pinwheel double categories} are the algebras of the pinwheel monad on
  \kl{double signatures}.
\end{definition}


\begin{toappendix}
\section{String Diagrams of Bicategories}
\label{sec:strings-bicategories}

\begin{definition}
  \defining{linktwocategory}{}
  A strict \emph{2-category} $𝔹$ consists of a collection of \emph{objects}, or
  0-cells, $𝔹_{obj}$, and a category of \emph{morphisms} or 1-cells between any
  two objects, $𝔹(A;B)$. A strict \emph{2-category} is endowed with operations
  for the parallel composition of 1-cells,
  \begin{align*}
    (\comp) &፡ 𝔹(A; B) × 𝔹(B; C) → 𝔹(A; C), \\
    (I_A) &፡ 𝔹(A;A),
  \end{align*}
  that are associative and unital both on objects and morphisms, meaning that
  $(X \comp Y) \comp Z = X \comp (Y \comp Z)$, and $I_A \comp X = X = X \comp I_B$.
  Bicategories must satisfy the following axioms, making parallel composition a functor:
  \begin{enumerate}
    \item parallel composition is unital, $f \comp \id = f$, and $\id \comp f = f$;
    \item parallel composition is associative, $f \comp (g \comp h) = (f \comp g) \comp h$;
    \item compositions are unital, $\id \comp \id = \id$;
    \item compositions interchange, $(f ⨾ g) \comp (f' ⨾ g') = (f \comp f') ⨾ (g \comp g')$.
  \end{enumerate}
\end{definition}
\begin{remark}
  A single-object strict 2-category is exactly a \strictMonoidalCategory{}.
\end{remark}


\subsection{String diagrams of 2-categories}
Let us assume any construction of bicategorical string diagrams. There are
multiple options when constructing bicategorical string diagrams: we could
propose a combinatorial description or a topological one, we could decide that
0-cells appear as part of the structure, or simply as the property of being
well-typed. These constructions are all left adjoints to the same forgetful functor
from 2-categories to \emph{\kl{2-graphs}}.

%

\begin{definition}[2-graph]
  \AP A \emph{\intro{2-graph}}, or \emph{bigraph}, $𝓑$ is given by a set of objects, $𝓑_{obj}$; a set of arrows between any two objects, $𝓑(A; B)$; and a set of 2-arrows between any two paths of arrows, $𝓑(X₀,…,Xₙ; Y₀,…,Yₘ)$.
\end{definition}

\begin{definition}[2-graph morphism]
  \AP A \emph{\intro{2-graph morphism}}, $f ፡ 𝓐 → 𝓑$, is a function between
  their object sets, $f_o ፡ 𝓐_{obj} → 𝓑_{obj}$; a family of functions between
  their corresponding arrow sets, $f ፡ 𝓐(A;B) → 𝓑(f(A),f(B))$; and a family of
  functions between their corresponding 2-arrow sets,
  $$f ፡ 𝓐(X_0,…,X_n; Y_0,…,Y_m) → 𝓑(f(X_0),…,f(X_n); f(Y_0),…,f(Y_m)).$$
  \kl{2-Graphs} with \kl{2-graph morphisms} form a category, $\Bigraph$.
\end{definition}

\begin{definition}[Forgetful 2-graph]
  The forgetful \kl{2-graph}, $\mathsf{forget}(𝔸)$, of a \kl{2-category}, $𝔸$,
  has the same set of objects as the \kl{2-category}, $\mathsf{forget}(𝔸)_{obj}
  = 𝔸_{obj}$; and morphism sets given by all the morphisms of the \kl{2-category},
  $$
  \mathsf{forget}(𝔸)(X_1,...,X_n;Y_1,...,Y_n) =
  𝔸(X_1 ⊗ ... ⊗ X_n; Y_1 ⊗ ... ⊗ Y_n).
  $$
\end{definition}

\begin{theorem}[Free bicategories]
  The functor $\mathsf{forget} ፡ \Twocat → \Twograph$ is a right adjoint.
\end{theorem}

That is, there is a right adjoint from \kl{2-categories} to \kl{2-graphs}. A
left adjoint can be constructed by bicategorical string diagrams over the
bigraph; let us write $\mathsf{string} ፡ \Twograph → \Twocat$ for this left
adjoint. However, let us still not assume any particular construction for this
left adjoint.
\end{toappendix}

