\subsection{Interaction Components}

\begin{figure}[t]
    \centering
    \includegraphics[height=150pt]{Interaction_Diagram_New.pdf}
    \caption{Interaction components for a generic centralized feed-based social media platform.}
    \label{fig:interaction_components_centralized}
