\subsection{Synonymous Variational Inference}
\label{section_III_2}

Unlike the usual variational inference, the two distributions of \eqref{SVI} work at different levels: The parametric density $q\left(\tilde{\boldsymbol{y}}|\boldsymbol{x}\right)$ works at the syntactic level, while the true posterior $p_{\tilde{\boldsymbol{y}}_s|\boldsymbol{\mathcal{X}}}\left(\tilde{\boldsymbol{y}}_s|\boldsymbol{\mathcal{X}}\right)$ operates at the semantic level, represented in the form of synsets. However, since $\tilde{\boldsymbol{y}}$ can be decomposed into a combination or concatenation of a synonymous representation $\tilde{\boldsymbol{y}}_s$ and a detailed representation $\tilde{\boldsymbol{y}}_\epsilon$, it is possible to effectively process the minimization of the partial semantic KL divergence. To distinguish from the existing variational inference methods, we give the following definition.
\begin{definition}
    \emph{Synonymous Variational Inference} (SVI) is a generic variational inference method that approximates the true posterior of the synonymous representations with a parametric density at the syntactic level by minimizing the partial semantic KL divergence \eqref{SVI}.
\end{definition}

By applying the proposed synonymous variational inference, the optimization direction of perceptual image compression can be determined. To facilitate the subsequent derivation, we first state the following lemma (the detailed proof can be found in \cref{section_A_1}):

\begin{lemma}\label{ENLSL}
    When the source considers the existence of an ideal synset $\boldsymbol{\mathcal{X}}$ and the decoder places the reconstructed sample in a reconstructed synset $\tilde{\boldsymbol{\mathcal{X}}}$, the minimization of the expected negative log synonymous likelihood term
    \begin{equation}
    \begin{aligned}
        & \min \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left[-\log p_{\boldsymbol{\mathcal{X}}|\tilde{\boldsymbol{y}}_s}\left(\boldsymbol{\mathcal{X}}|\tilde{\boldsymbol{y}}_s \right)\right] \\
        & \quad \Longleftrightarrow \min \lambda_d \cdot \mathbb{E}_{\boldsymbol{x} \sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_i \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[d\left(\boldsymbol{x}, \tilde{\boldsymbol{x}}_i\right)\right] \\
        & \quad\quad\quad\quad  + \lambda_p \cdot \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_i \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\tilde{\boldsymbol{x}}_i}\right],
    \end{aligned}
    \end{equation}
    in which $\lambda_d$ and $\lambda_p$ are the tradeoff factors for the expected distortion (typically expected means-squared error, i.e., E-MSE) term and the expected KL divergence (E-KLD) term, respectively.
\end{lemma}

Based on this, we propose the following theorem:

\begin{theorem}\label{SICtheorem}
    For an image source  $\boldsymbol{x} \sim p\left(\boldsymbol{x}\right)$ together with its bounded expected distortion $\mathbb{E}_{\boldsymbol{x} \sim p\left(\boldsymbol{x}\right)}  \mathbb{E}_{\hat{\boldsymbol{x}}_i \in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} \left[d\left(\boldsymbol{x}, \hat{\boldsymbol{x}}_i\right)\right]$ and expected KL divergence $\mathbb{E}_{\hat{\boldsymbol{x}}_i\in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} D_{\text{KL}} \left[p_{\boldsymbol{x}} || p_{\hat{\boldsymbol{x}}_i}\right]$, the minimum achievable rate of perceptual image compression is
    \begin{equation}\label{SVIgoal}
    \begin{aligned}
        R\left(\boldsymbol{\mathcal{X}}\right) = & \min_{p(\hat{\boldsymbol{\mathcal{X}}}|\boldsymbol{x})} I\left(\boldsymbol{X}; \hat{\mathring{\boldsymbol{X}}}\right) \\
        & \mathrm{s}.\mathrm{t}. \quad \mathbb{E}_{\boldsymbol{x} \sim p\left(\boldsymbol{x}\right)}  \mathbb{E}_{\hat{\boldsymbol{x}}_i \in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} \left[d\left(\boldsymbol{x}, \hat{\boldsymbol{x}}_i\right)\right] \leq D, \\
        & \quad\quad\,\, \mathbb{E}_{\hat{\boldsymbol{x}}_i \in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} D_{\text{KL}} \left[p_{\boldsymbol{x}} || p_{\hat{\boldsymbol{x}}_i}\right] \leq P,
    \end{aligned}
    \end{equation}
    where $ I\left(\boldsymbol{X}; \hat{\mathring{\boldsymbol{X}}}\right) = H_s\left(\hat{\mathring{\boldsymbol{X}}}\right) - H_s\left(\hat{\mathring{\boldsymbol{X}}}|\boldsymbol{X}\right)$ with semantic variable $\hat{\mathring{\boldsymbol{X}}}$ corresponds to the reconstructed synset $\hat{\boldsymbol{\mathcal{X}}}$.
\end{theorem}

