\section{The Proof of the Key Theoretical Results}
\label{section_A}

In the main text, we present \cref{ENLSL} and provide a brief proof of the optimization direction of SIC in \cref{SICtheorem}, based on this lemma. In this appendix section, we first provide detailed proofs of \cref{ENLSL} and \cref{SICtheorem}, and briefly discuss their relationships with the existing image compression theories.

\subsection{The Proof of \cref{ENLSL}}
\label{section_A_1}

\renewcommand{\thetheorem}{3.2}
\begin{lemma}
    When the source considers the existence of an ideal synset $\boldsymbol{\mathcal{X}}$ and the decoder places the reconstructed sample in a reconstructed synset $\tilde{\boldsymbol{\mathcal{X}}}$, the minimization of the expected negative log synonymous likelihood term
    \begin{equation}\label{DPequivalent}
         \min \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left[-\log p_{\boldsymbol{\mathcal{X}}|\tilde{\boldsymbol{y}}_s}\left(\boldsymbol{\mathcal{X}}|\tilde{\boldsymbol{y}}_s \right)\right]
        \, \Longleftrightarrow \, \min \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_i \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s}
        \left\{\lambda_d \cdot \mathbb{E}_{\boldsymbol{x} \sim p\left(\boldsymbol{x}\right)}\left[d\left(\boldsymbol{x}, \tilde{\boldsymbol{x}}_i\right)\right] + \lambda_p \cdot  D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\tilde{\boldsymbol{x}}_i}\right] \right\},
    \end{equation}
    in which $\lambda_d$ and $\lambda_p$ are the tradeoff factors for the expected distortion term and the expected KL divergence term, respectively.
\end{lemma}

\begin{proof}
    According to the generative model presented in \cref{figure2}, any sample $\boldsymbol{x}_i$ in the ideal synset $\boldsymbol{\mathcal{X}}$ is expected to be capable of being generated using a synonymous representation $\tilde{\boldsymbol{y}}_s$ and a detailed sample $\boldsymbol{\hat{y}}_{\epsilon, j}$, in which the detailed sample $\boldsymbol{\hat{y}}_{\epsilon, j}$ is sampled based on a specific prior $p_{\boldsymbol{\hat{y}}_\epsilon | \tilde{\boldsymbol{y}}_s}\left(\boldsymbol{\hat{y}}_\epsilon | \tilde{\boldsymbol{y}}_s; \boldsymbol{\psi}, \boldsymbol{\theta}_p \right)$. It should be noted that $\boldsymbol{\hat{y}}_{\epsilon, j} \ne \tilde{\boldsymbol{y}}_\epsilon$ since the detailed representation $\tilde{\boldsymbol{y}}_\epsilon$ is not required to be coded and transmitted to the decoder end.

    Additionally, according to the semantic information theory based on synonymity \cite{niu2024mathematical}, the probability of a synset is equal to the sum of the probability or the integral of the density of each sample within the set. Herein, we consider the integral form because image samples within an ideal synset can typically be transformed into one another through continuous changes.

    Based on the above factors, we can expand the expression on the left side of \eqref{DPequivalent} as follows:
    \begin{equation}\label{ENLSL_step1}
    \begin{aligned}
        & \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left[-\log p_{\boldsymbol{\mathcal{X}}|\tilde{\boldsymbol{y}}_s}\left(\boldsymbol{\mathcal{X}}|\tilde{\boldsymbol{y}}_s ; \boldsymbol{\theta}_g \right)\right] \\
        & \quad \overset{(\mathrm{a})}{=} \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left[ - \log \int_{\boldsymbol{\hat{\boldsymbol{y}}_{\epsilon, j}}} p_{\boldsymbol{\mathcal{X}}|\tilde{\boldsymbol{y}}_s, \hat{\boldsymbol{y}}_{\epsilon, j}} \left(\boldsymbol{\mathcal{X}}|\tilde{\boldsymbol{y}}_s, \hat{\boldsymbol{y}}_{\epsilon, j} ; \boldsymbol{\theta}_g \right) \cdot p_{\hat{\boldsymbol{y}}_{\epsilon, j} | \tilde{\boldsymbol{y}}_s} \left(\hat{\boldsymbol{y}}_{\epsilon, j} | \tilde{\boldsymbol{y}}_s ; \boldsymbol{\psi}, \boldsymbol{\theta}_p\right) d \hat{\boldsymbol{y}}_{\epsilon, j} \right] \\
        & \quad \overset{(\mathrm{b})}{=} \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left\{ -\log \mathbb{E}_{\hat{\boldsymbol{y}}_{\epsilon, j} | \tilde{\boldsymbol{y}}_s \sim p_{\hat{\boldsymbol{y}}_{\epsilon, j} | \tilde{\boldsymbol{y}}_s}} \left[p_{\boldsymbol{\mathcal{X}}|\tilde{\boldsymbol{y}}_s, \hat{\boldsymbol{y}}_{\epsilon, j}} \left(\boldsymbol{\mathcal{X}}|\tilde{\boldsymbol{y}}_s, \hat{\boldsymbol{y}}_{\epsilon, j} ; \boldsymbol{\theta}_g \right)\right] \right\} \\
        & \quad \overset{(\mathrm{c})}{=} \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}
        \left\{-\log \mathbb{E}_{\hat{\boldsymbol{y}}_{\epsilon, j} | \tilde{\boldsymbol{y}}_s \sim p_{\hat{\boldsymbol{y}}_{\epsilon, j} | \tilde{\boldsymbol{y}}_s}} \left[\int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}} p_{\boldsymbol{x}_i | \tilde{\boldsymbol{y}}_s, \hat{\boldsymbol{y}}_{\epsilon, j}} \left(\boldsymbol{x}_i | \tilde{\boldsymbol{y}}_s, \hat{\boldsymbol{y}}_{\epsilon, j} ; \boldsymbol{\theta}_g \right) d \boldsymbol{x}_i \right] \right\} \\
        & \quad \overset{(\mathrm{d})}{=} \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left\{ - \log \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}}|\tilde{\boldsymbol{y}}_s} \left[\int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}} p_{\boldsymbol{x}_i| \tilde{\boldsymbol{x}}_j} \left(\boldsymbol{x}_i| \tilde{\boldsymbol{x}}_j\right) d \boldsymbol{x}_i \right] \right\},
    \end{aligned}
    \end{equation}
    where $(\mathrm{a})$ is achieved by introducing $\boldsymbol{\hat{y}}_{\epsilon, j}$ into the conditional probability with a corresponding integral; $(\mathrm{b})$ is according to the definition of mathematical expectation; $(\mathrm{c})$ is according to the integral relationship between the probability of the ideal synset and its samples as stated before; $(\mathrm{d})$ is based on a determined generator $\boldsymbol{\theta}_g$ which can definitely map the input $\tilde{\boldsymbol{y}}_s$ and $\hat{\boldsymbol{y}}_{\epsilon, j}$ to the output $\tilde{\boldsymbol{x}}_j$, i.e., $\tilde{\boldsymbol{x}}_j = g_s\left(\tilde{\boldsymbol{y}}_s, \hat{\boldsymbol{y}}_{\epsilon, j} ; \boldsymbol{\theta}_g\right)$. It should be noted that in the equation $(\mathrm{d})$, the reconstructed sample $\tilde{\boldsymbol{x}}_j$ is not required to be completely aligned with the source synonymous sample $\boldsymbol{x}_i$ but for the overall ideal synset $\boldsymbol{\mathcal{X}}$, which is why two subscripts, i.e., $i$ and $j$, are used here.  By minimizing this term, we can use the synonym representation $\hat{\boldsymbol{y}}_s$ to obtain the reconstructed synset $\hat{\boldsymbol{\mathcal{X}}}$, bringing it closer to the ideal synset $\boldsymbol{\mathcal{X}}$, thus achieving the optimization objective shown in \cref{figure1}.

    Since the above results only involve the sample $\boldsymbol{x}_i$ from the ideal synset centered by the original image $\boldsymbol{x}$ and the reconstructed sample $\tilde{\boldsymbol{x}}_j$ obtained by the SIC codec, the influence of the original image sample $\boldsymbol{x}$ has not directly involved. To this end, we consider to rewrite \eqref{ENLSL_step1} as
    \begin{equation}\label{ENLSL_step2}
    \begin{aligned}
        & \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left\{ - \log \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[\int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}} p_{\boldsymbol{x}_i| \tilde{\boldsymbol{x}}_j} \left(\boldsymbol{x}_i| \tilde{\boldsymbol{x}}_j\right) d \boldsymbol{x}_i \right] \right\} \\
        & \quad \overset{(\mathrm{a})}{=} \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left\{ - \log \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[\int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
        p_{\tilde{\boldsymbol{x}}_j| \boldsymbol{x}_i} \left(\tilde{\boldsymbol{x}}_j | \boldsymbol{x}_i \right)
        \cdot \frac{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} d \boldsymbol{x}_i \right] \right\} \\
        & \quad \overset{(\mathrm{b})}{=} \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left\{ - \log \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[\int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
        p_{\tilde{\boldsymbol{x}}_j| \boldsymbol{x}_i} \left(\tilde{\boldsymbol{x}}_j | \boldsymbol{x}_i \right)
        \cdot \frac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}
        \cdot \frac{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}
        \cdot \frac{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} d \boldsymbol{x}_i \right] \right\},
    \end{aligned}
    \end{equation}
    in which $(\mathrm{a})$ is by the Bayes' theorem, and $(\mathrm{b})$ is achieved by introducing the reciprocal terms $\dfrac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}$ and $\dfrac{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}$.

    Furthermore, since any sample $\boldsymbol{x}_i$  in the ideal synset (including the original image sample $\boldsymbol{x}$) shares the same synonymous representation $\tilde{\boldsymbol{y}}_s$ by the ideal parametric SIC encoder with $\boldsymbol{\phi^*_g}$,  the posterior term in the \eqref{ENLSL_step2} satisfy the following equations:
    \begin{equation}\label{replaceEquations}
        p_{\tilde{\boldsymbol{x}}_j| \boldsymbol{x}_i} \left(\tilde{\boldsymbol{x}}_j | \boldsymbol{x}_i \right)
        = p_{\tilde{\boldsymbol{x}}_j| \tilde{\boldsymbol{y}}_s} \left(\tilde{\boldsymbol{x}}_j | \tilde{\boldsymbol{y}}_s \right)
        = p_{\tilde{\boldsymbol{x}}_j| \boldsymbol{x}} \left(\tilde{\boldsymbol{x}}_j | \boldsymbol{x} \right).
    \end{equation}

    Therefore, the result of \eqref{ENLSL_step2} can be further derived as
    \begin{equation}\label{ENLSL_step3}
    \begin{aligned}
        & \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left\{ - \log \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[\int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
        p_{\tilde{\boldsymbol{x}}_j| \boldsymbol{x}_i} \left(\tilde{\boldsymbol{x}}_j | \boldsymbol{x}_i \right)
        \cdot \frac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}
        \cdot \frac{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}
        \cdot \frac{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} d \boldsymbol{x}_i \right] \right\} \\
        & \quad \overset{(\mathrm{a})}{=} \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left\{ - \log \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[\int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
        \left(
            p_{\tilde{\boldsymbol{x}}_j| \boldsymbol{x}} \left(\tilde{\boldsymbol{x}}_j | \boldsymbol{x} \right)
            \cdot \frac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}
        \right)
        \cdot \frac{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}
        \cdot \frac{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} d \boldsymbol{x}_i \right] \right\} \\
        & \quad \overset{(\mathrm{b})}{=} \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left\{ - \log \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[\int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
        p_{\boldsymbol{x} | \tilde{\boldsymbol{x}}_j} \left(\boldsymbol{x} | \tilde{\boldsymbol{x}}_j \right)
        \cdot \frac{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}
        \cdot \frac{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} d \boldsymbol{x}_i \right] \right\} \\
        & \quad = \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left\{ - \log \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s}
        \left[ p_{\boldsymbol{x} | \tilde{\boldsymbol{x}}_j} \left(\boldsymbol{x} | \tilde{\boldsymbol{x}}_j \right)
        \cdot \frac{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}
        \cdot \int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
        \frac{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} d \boldsymbol{x}_i \right] \right\} \\
        & \quad \overset{(\mathrm{c})}{=} \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left\{ - \log \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s}
        \left[ p_{\boldsymbol{x} | \tilde{\boldsymbol{x}}_j} \left(\boldsymbol{x} | \tilde{\boldsymbol{x}}_j \right)
        \cdot \frac{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}
        \cdot \left(\frac{1}{\left|\boldsymbol{\mathcal{X}}\right|} \int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
        \frac{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}
        d \boldsymbol{x}_i \right)
        \cdot \left|\boldsymbol{\mathcal{X}}\right| \right] \right\} \\
        & \quad \overset{(\mathrm{d})}{\leq}
        \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}
        \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[
            - \log p_{\boldsymbol{x} | \tilde{\boldsymbol{x}}_j} \left(\boldsymbol{x} | \tilde{\boldsymbol{x}}_j \right)
            + \log \frac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}
            - \log \frac{1}{\left|\boldsymbol{\mathcal{X}}\right|} \int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
            \frac{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} d \boldsymbol{x}_i
            - \log \left|\boldsymbol{\mathcal{X}}\right|
        \right] \\
        & \quad \overset{(\mathrm{e})}{\leq}
        \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}
        \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[
            - \log p_{\boldsymbol{x} | \tilde{\boldsymbol{x}}_j} \left(\boldsymbol{x} | \tilde{\boldsymbol{x}}_j \right)
            + \log \frac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}
            - \frac{1}{\left|\boldsymbol{\mathcal{X}}\right|} \int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
            \log \frac{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} d \boldsymbol{x}_i
            - \log \left|\boldsymbol{\mathcal{X}}\right|
        \right],
    \end{aligned}
    \end{equation}
    where $(\mathrm{a})$ replaces $p_{\tilde{\boldsymbol{x}}_j| \boldsymbol{x}_i} \left(\tilde{\boldsymbol{x}}_j | \boldsymbol{x}_i \right)$ with $p_{\tilde{\boldsymbol{x}}_j| \boldsymbol{x}} \left(\tilde{\boldsymbol{x}}_j | \boldsymbol{x} \right)$ using \eqref{replaceEquations}; $(\mathrm{b})$ is derived by the Bayes' theorem in reverse; $(\mathrm{c})$ introduces $\left|\boldsymbol{\mathcal{X}}\right|$ and its reciprocal, in which $\left|\boldsymbol{\mathcal{X}}\right|$ denotes the size of the ideal synset $\boldsymbol{\mathcal{X}}$, and can be used to express an arithmetic mean along with the followed integral over $\boldsymbol{\mathcal{X}}$; (d) and (e) can be scaled based on the Jensen's inequalities, respectively, since $-\log \left(\cdot\right)$ is a convex function.

    Next, we examine the result of \eqref{ENLSL_step3} separately.

    \begin{enumerate}
        \item \textbf{The Derivation of the First Term.} $\mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}
        \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s}\left[-\log p_{\boldsymbol{x} | \tilde{\boldsymbol{x}}_j} \left(\boldsymbol{x} | \tilde{\boldsymbol{x}}_j \right)\right]$ denotes an expected distortion which averaged on the source images and the corresponding samples of the reconstructed synsets. As a typical case, when the likelihood probability $p_{\boldsymbol{x} | \tilde{\boldsymbol{x}}_j} \left(\boldsymbol{x} | \tilde{\boldsymbol{x}}_j \right)$ follows a Gaussian distribution $\mathcal{N}\left(\boldsymbol{x}|\tilde{\boldsymbol{x}}_j, \sigma^2\boldsymbol{I}_d\right)$ (in which $d$ denotes the dimension of the original image $\boldsymbol{x}$), this term will be equivalent to
        \begin{equation}
            \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}
            \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s}\left[-\log p_{\boldsymbol{x} | \tilde{\boldsymbol{x}}_j} \left(\boldsymbol{x} | \tilde{\boldsymbol{x}}_j \right)\right] = \frac{1}{2\sigma^2} \cdot \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}
            \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left|\left|\boldsymbol{x} - \tilde{\boldsymbol{x}}\right|\right|^2 + \frac{d}{2}\log\left(2\pi\sigma^2\right),
        \end{equation}
        in which the $\sigma^2$ is the variance term of the set Gaussian distribution, i.e., the power of the quantization noise. In this case, the term can be considered as a weighted Expected Mean Squared Error (E-MSE) loss (instead of the Mean Squared Error (MSE) loss) plus a constant.

        In typical LIC methods \cite{balle2016end, balle2018variational}, the multiplier $\dfrac{1}{2\sigma^2}$ is often replaced with a hyperparameter $\lambda$ as the tradeoff factor to the MSE loss to the balance with the coding rate. However, in SIC, if E-MSE is used as the distortion loss term, it is incomplete to define the physical meaning of the hyperparameter as $\dfrac{1}{2\sigma^2}$ alone: The effect of scaling, due to the inequality in \eqref{ENLSL_step3}(d), should be also considered. Therefore, we summarize the analysis results as
        \begin{equation}
            \lambda_d \cdot \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}
            \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left|\left|\boldsymbol{x} - \tilde{\boldsymbol{x}}_j\right|\right|^2 + \text{const},
        \end{equation}
        in which $\lambda_d = \alpha_d\left(\big|\tilde{\boldsymbol{\mathcal{X}}}\big|\right) \cdot \dfrac{1}{2\sigma^2}$. The multiplier $\alpha_d\left(\big|\tilde{\boldsymbol{\mathcal{X}}}\big|\right)$ is a scaling factor influenced by the size of the reconstructed synset $\tilde{\boldsymbol{\mathcal{X}}}$, and it can be implicitly incorporated into the value of the hyperparameter $\lambda_d$ thus it does not need to be explicitly assigned. It should be noted that when the equality condition of Jensen inequality \eqref{ENLSL_step3}(d) is satisfied or the reconstructed synset contains only one sample, the multiplier $\alpha_d\left(\big|\tilde{\boldsymbol{\mathcal{X}}}\big|\right) = 1$, and the analysis result will be degraded into $\lambda \cdot \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left|\left|\boldsymbol{x} - \tilde{\boldsymbol{x}}\right|\right|^2 + \text{const}$.

        When other distortion measures (such as Expected MS-SSIM, abbreviated as E-MS-SSIM) are used instead of E-MSE, the situation is similar and will not be discussed further. Herein, we give a general analysis result as
        \begin{equation}
            \lambda_d \cdot \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}
            \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[d\left(\boldsymbol{x}, \tilde{\boldsymbol{x}}_j\right)\right] + \text{const},
        \end{equation}
        in which $d\left(\cdot\right)$ denotes any distortion measure between the original image $\boldsymbol{x}$ and the reconstructed sample $\tilde{\boldsymbol{x}}_j$.

        \item \textbf{The Derivation of the Second Term and the Third Term.} These two terms should be firstly considered together due to their linkage, which can be derived as
        \begin{equation}\label{combine}
        \begin{aligned}
            & \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s}
            \left[
                \log \frac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}
                - \frac{1}{\left|\boldsymbol{\mathcal{X}}\right|} \int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
                \log \frac{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} d \boldsymbol{x}_i
            \right] \\
            & \quad = \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s}
            \left[
                \frac{1}{\left|\boldsymbol{\mathcal{X}}\right|} \int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
                \left( \log \frac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} - \log \frac{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}\right) d \boldsymbol{x}_i
            \right] \\
            & \quad = \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s}
            \left[
                \frac{1}{\left|\boldsymbol{\mathcal{X}}\right|} \int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
                \log \frac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}
                \cdot \frac{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}
                d \boldsymbol{x}_i
            \right] \\
            & \quad = \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)}
            \left[
                \frac{1}{\left|\boldsymbol{\mathcal{X}}\right|} \int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
                \log \frac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}
                d \boldsymbol{x}_i
            \right] \\
            & \quad = \frac{1}{\left|\boldsymbol{\mathcal{X}}\right|} \int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
            \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)}
            \left[\log \frac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}\right]
            d \boldsymbol{x}_i \\
            & \quad = \frac{1}{\left|\boldsymbol{\mathcal{X}}\right|} \int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
            D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\boldsymbol{x}_i}\right]
            d \boldsymbol{x}_i = f\left(\boldsymbol{x}, \boldsymbol{\mathcal{X}}\right),
        \end{aligned}
        \end{equation}
        i.e., the arithmetic mean of the KL divergence between the original sample $\boldsymbol{x}$ and the synonymous sample $\boldsymbol{x}_i$, which is a non-negative function $f\left(\boldsymbol{x}, \boldsymbol{\mathcal{X}}\right)$ of the original sample $\boldsymbol{x}$ and the ideal synset $\boldsymbol{\mathcal{X}}$. If these two factors at the source are determined, the result of the function will be constant.
        For a special case, when $\boldsymbol{\mathcal{X}}$ contains only one sample, i.e., the original image $\boldsymbol{x}$, this constant will be equal to 0 since the two distributions reduce to only one distribution $p_{\boldsymbol{x}}$.

        Despite the foregoing facts, if it is treated as a constant, the existence of the ideal synset on the source will lose its meaning during the minimization process, and no samples with perceptual similarity to the source image will be available to provide a reference for the reconstructed samples. Therefore, we need to consider the second and third terms separately to determine the meaning of the constant value in the optimization process:
        \begin{itemize}
            \item For the second term $\mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[ \log \dfrac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} \right]$, it can be further derived as
            \begin{equation}
            \begin{aligned}
                \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[ \log \frac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} \right]
                & = \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[\mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \log \frac{p_{\boldsymbol{x}} \left(\boldsymbol{x}\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)}\right] \\
                & = \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\tilde{\boldsymbol{x}}_j}\right],
            \end{aligned}
            \end{equation}
            i.e., an Expected KL Divergence (E-KLD) between the distribution of the original image $p_{\boldsymbol{x}}$ and the distribution of the reconstructed sample $p_{\tilde{\boldsymbol{x}}_j}$ that averaged on the reconstructed synset $\tilde{\boldsymbol{\mathcal{X}}}$.

            \item As for the third term, i.e., $\mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[ - \dfrac{1}{\left|\boldsymbol{\mathcal{X}}\right|} \displaystyle\int_{\boldsymbol{x}_i\in \boldsymbol{\mathcal{X}}} \log \dfrac{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} d \boldsymbol{x}_i\right]$, although it has a similar form to KL divergence, it cannot be called KL divergence because it uses the arithmetic mean instead of the mathematical expectation, thus lacking the non-negative properties of KL divergence. It should be noted that the outer mathematic expectations $\mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s}$ is actually calculated the expectation value according to the conditional probability $p_{\tilde{\boldsymbol{x}}_j|\boldsymbol{x}} \left(\tilde{\boldsymbol{x}}_j|\boldsymbol{x}\right)$ instead of $p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)$, thus the result cannot be regarded as KL divergence from this perspective neither. In spite of this, we can intuitively find the conditions under which this term equals 0, which can be expressed as
            \begin{equation}\label{equalProbabiltiyConditions}
                \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[ - \dfrac{1}{\left|\boldsymbol{\mathcal{X}}\right|} \int_{\boldsymbol{x}_i\in \boldsymbol{\mathcal{X}}} \log \dfrac{p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right)}{p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right)} d \boldsymbol{x}_i\right] = 0 \quad \Longleftrightarrow \quad
                p_{\boldsymbol{x}_i} \left(\boldsymbol{x}_i\right) = p_{\tilde{\boldsymbol{x}}_j} \left(\tilde{\boldsymbol{x}}_j\right) \quad \forall{i, j}
            \end{equation}
            i.e., for arbitrary sample pair $\left(\boldsymbol{x}_i, \tilde{\boldsymbol{x}}_j\right)$, the probabilities of both samples are equal. To facilitate subsequent analysis, we label this term as $-\delta_p$.
        \end{itemize}

        Based on the above analysis, we obtain the following equation relationship:
        \begin{equation}
            \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}
            \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\tilde{\boldsymbol{x}}_j}\right] - \delta_p = \frac{1}{\left|\boldsymbol{\mathcal{X}}\right|} \int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}}
            D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\boldsymbol{x}_i}\right]
            d \boldsymbol{x}_i = f\left(\boldsymbol{x}, \boldsymbol{\mathcal{X}}\right).
        \end{equation}

        From this formula, we can see that although $f\left(\boldsymbol{x}, \boldsymbol{\mathcal{X}}\right)$ is a constant when $\boldsymbol{x}$ and $\boldsymbol{\mathcal{X}}$ are determined, we can approximate it by minimizing the E-KLD term $\mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\tilde{\boldsymbol{x}}_j}\right]$. For a special case, by forcing $\delta_p = 0$ with equal probability sampling for $\tilde{\boldsymbol{x}}_j$, the E-KLD term $\mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\tilde{\boldsymbol{x}}_j}\right]$ is equal to the arithmetic mean term $\frac{1}{\left|\boldsymbol{\mathcal{X}}\right|} \int_{\boldsymbol{x}_i \in \boldsymbol{\mathcal{X}}} D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\boldsymbol{x}_i}\right] d \boldsymbol{x}_i$.

        Similar to the first term, considering the effect of scaling in $\eqref{ENLSL}$(d), we summarize the analysis results as
        \begin{equation}
            \lambda_p \cdot \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\tilde{\boldsymbol{x}}_j}\right],
        \end{equation}
        in which $\lambda_p = 1_{\left|\boldsymbol{\mathcal{X}}\right| \ne 1} \left(\big|\boldsymbol{\mathcal{X}}\big|\right) \cdot \alpha_p\left(  \left|\tilde{\boldsymbol{\mathcal{X}}}\right|\right)$ is also a scaling factor influenced by the size of the ideal synset $\boldsymbol{\mathcal{X}}$ and the reconstructed synset $\tilde{\boldsymbol{\mathcal{X}}}$, and $1_{\left|\boldsymbol{\mathcal{X}}\right| \ne 1}$ is a indicated function of the size of the ideal synset $\left|\boldsymbol{\mathcal{X}}\right|$. Similar to the first term, we discuss the following two special cases:
        \begin{itemize}
            \item When the equality condition of Jensen inequality \eqref{ENLSL_step3}(e) is satisfied, or the ideal synset is considered with multiple samples while the reconstructed synset contains only one, the multiplier $1_{\left|\boldsymbol{\mathcal{X}}\right| \ne 1} \left(\big|\boldsymbol{\mathcal{X}}\big|\right) = 1$ and  $\alpha_p\left(\big|\tilde{\boldsymbol{\mathcal{X}}}\big|\right) = 1$, and the analysis result will be degraded into $\mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}  D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\tilde{\boldsymbol{x}}}\right]$.
            \item When the ideal synset contains only one sample, i.e., the original image $\boldsymbol{x}$, the multiplier $1_{\left|\boldsymbol{\mathcal{X}}\right| \ne 1} \left(\left|\boldsymbol{\mathcal{X}}\right|\right) = 0$, which makes the analysis result equal to 0.
        \end{itemize}

        \item \textbf{The Derivation of the Fourth Term.} With the determination of the ideal synset $\boldsymbol{\mathcal{X}}$ for the original image $\boldsymbol{x}$, the term $- \log \left|\boldsymbol{\mathcal{X}}\right|$ is a constant that cannot be optimized.
    \end{enumerate}

    To summarize, by consolidating the above analysis results, we complete the proof of \cref{ENLSL}, that is,
    \begin{equation}
    \begin{aligned}
        & \min \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left[-\log p_{\boldsymbol{\mathcal{X}}|\tilde{\boldsymbol{y}}_s}\left(\boldsymbol{\mathcal{X}}|\tilde{\boldsymbol{y}}_s \right)\right] \\
        & \, \quad = \, \min \left\{\lambda_d \cdot \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}
        \mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[d\left(\boldsymbol{x}, \tilde{\boldsymbol{x}}_i\right)\right] + \text{const}\right\}
        + \left\{\lambda_p \cdot \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}\mathbb{E}_{\tilde{\boldsymbol{x}}_j \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\tilde{\boldsymbol{x}}_j}\right]\right\} + \text{const} \\
        & \quad \Leftrightarrow \, \min \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_i \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s}
        \left\{\lambda_d \cdot \mathbb{E}_{\boldsymbol{x} \sim p\left(\boldsymbol{x}\right)}\left[d\left(\boldsymbol{x}, \tilde{\boldsymbol{x}}_i\right)\right] + \lambda_p \cdot  D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\tilde{\boldsymbol{x}}_i}\right] \right\}.
    \end{aligned}
    \end{equation}
\end{proof}



\subsection{The Proof of \cref{SICtheorem}}
\label{section_A_2}

\renewcommand{\thetheorem}{3.3}
\begin{theorem}
    For an image source  $\boldsymbol{x} \sim p\left(\boldsymbol{x}\right)$ together with its bounded expected distortion $\mathbb{E}_{\boldsymbol{x} \sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\hat{\boldsymbol{x}}_i \in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} \left[d\left(\boldsymbol{x}, \hat{\boldsymbol{x}}_i\right)\right]$ and expected KL divergence $\mathbb{E}_{\hat{\boldsymbol{x}}_i\in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} D_{\text{KL}} \left[p_{\boldsymbol{x}} || p_{\hat{\boldsymbol{x}}_i}\right]$, the minimum achievable rate of perceptual image compression is
    \begin{equation}\label{SVIgoal_inAppendix}
    \begin{aligned}
        R\left(\boldsymbol{\mathcal{X}}\right) = & \min_{p(\hat{\boldsymbol{\mathcal{X}}}|\boldsymbol{x})} I\left(\boldsymbol{X}; \hat{\mathring{\boldsymbol{X}}}\right) \\
        & \mathrm{s}.\mathrm{t}. \quad \mathbb{E}_{\boldsymbol{x} \sim p\left(\boldsymbol{x}\right)}  \mathbb{E}_{\hat{\boldsymbol{x}}_i \in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} \left[d\left(\boldsymbol{x}, \hat{\boldsymbol{x}}_i\right)\right] \leq D, \\
        & \quad\quad\,\, \mathbb{E}_{\hat{\boldsymbol{x}}_i \in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} D_{\text{KL}} \left[p_{\boldsymbol{x}} || p_{\hat{\boldsymbol{x}}_i}\right] \leq P,
    \end{aligned}
    \end{equation}
    where $ I\left(\boldsymbol{X}; \hat{\mathring{\boldsymbol{X}}}\right) = H_s\left(\hat{\mathring{\boldsymbol{X}}}\right) - H_s\left(\hat{\mathring{\boldsymbol{X}}}|\boldsymbol{X}\right)$ with semantic variable $\hat{\mathring{\boldsymbol{X}}}$ corresponds to the reconstructed synset $\hat{\boldsymbol{\mathcal{X}}}$.
\end{theorem}

\begin{proof}
    The key point to prove this problem is to consider an ideal scenario, in which there are multiple image samples $\boldsymbol{x}_i$ at the source with similar perceptual similarities to the original image $\boldsymbol{x}$. In this scenario, each sample can be assumed to be potentially generated by the ideal perceptual image decoder. To this end, it is necessary to assume the existence of an ideal synset $\boldsymbol{\mathcal{X}}$ at the source which can encompass these samples (including the original image $\boldsymbol{x}$). These samples must share the same synonymous representations which can be represented as $\tilde{\boldsymbol{y}}_s$ in the latent space, while the unique detailed features of each sample should be represented as $\tilde{\boldsymbol{y}}_{\epsilon}$ in the latent space.

    Based on this assumption, there should be an ideal image codec, in which the encoder ensures that any sample within the ideal synset $\boldsymbol{\mathcal{X}}$ obtains the same synonymous representation $\tilde{\boldsymbol{y}}_s$ after encoding, while the decoder, upon receiving only the synonymous representation $\tilde{\boldsymbol{y}}_s$, can generate different samples $\boldsymbol{x}_i$ within the ideal synset $\boldsymbol{\mathcal{X}}$ through sampling $\hat{\boldsymbol{y}}_{\epsilon, j}$. The optimization process leading to this ideal encoder-decoder pair can be modeled as a variational auto-encoder model, which can be achieved by minimizing the partial semantic KL divergence based on the idea of the proposed synonymous variational inference (SVI), that is,
    \begin{equation}\label{SVIderivation}
    \begin{aligned}
        \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)}  D_{\text{KL},s}\left[q||p_{\tilde{\boldsymbol{y}}_s | \boldsymbol{\mathcal{X}}}\right] 
        & = \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}|\boldsymbol{x} \sim q} 
        \left[
            \log \frac{q\left(\tilde{\boldsymbol{y}}|\boldsymbol{x}\right)}{p_{\tilde{\boldsymbol{y}}_s | \boldsymbol{\mathcal{X}}} \left(
                \tilde{\boldsymbol{y}}_s | \boldsymbol{\mathcal{X}}
            \right)}
        \right] \\
        & = \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}|\boldsymbol{x} \sim q} 
        \left[
            \log \frac{q\left(\tilde{\boldsymbol{y}}|\boldsymbol{x}\right)}{p_{\boldsymbol{\mathcal{X}}, \tilde{\boldsymbol{y}}_s} \left(
                \boldsymbol{\mathcal{X}},\tilde{\boldsymbol{y}}_s  
            \right) / p_{\boldsymbol{\mathcal{X}}}\left(\boldsymbol{\mathcal{X}}\right)}
        \right] \\
        & = \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}|\boldsymbol{x} \sim q} 
        \left[
            \log \frac{q\left(\tilde{\boldsymbol{y}}|\boldsymbol{x}\right)}{p_{\boldsymbol{\mathcal{X}} | \tilde{\boldsymbol{y}}_s} \left(
                \boldsymbol{\mathcal{X}} | \tilde{\boldsymbol{y}}_s  
            \right) \cdot p_{\tilde{\boldsymbol{y}}_s}\left(\tilde{\boldsymbol{y}}_s\right) / p_{\boldsymbol{\mathcal{X}}}\left(\boldsymbol{\mathcal{X}}\right)}
        \right] \\
        & = \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}|\boldsymbol{x} \sim q} 
        \left[
            \log q\left(\tilde{\boldsymbol{y}}|\boldsymbol{x}\right)
            - \log p_{\boldsymbol{\mathcal{X}} | \tilde{\boldsymbol{y}}_s} \left(\boldsymbol{\mathcal{X}} | \tilde{\boldsymbol{y}}_s\right)
            - \log p_{\tilde{\boldsymbol{y}}_s}\left(\tilde{\boldsymbol{y}}_s\right)
            + \log p_{\boldsymbol{\mathcal{X}}}\left(\boldsymbol{\mathcal{X}}\right)
        \right]
    \end{aligned}
    \end{equation}

    Next, We examine the result of \eqref{SVIderivation} term by term.

    \begin{enumerate}
        \item For the first term $\log q\left(\tilde{\boldsymbol{y}}|\boldsymbol{x}\right)$, since the noisy latent representation $\tilde{\boldsymbol{y}}$ can be separated into two parts, i.e., a synonymous representation $\tilde{\boldsymbol{y}}_s$ and a detailed representation $\tilde{\boldsymbol{y}}_{\epsilon}$, it can be expanded to
        \begin{equation}
            \log q\left(\tilde{\boldsymbol{y}}|\boldsymbol{x}; \boldsymbol{\phi}_g\right) 
            = \log q\left(\tilde{\boldsymbol{y}}_s, \tilde{\boldsymbol{y}}_{\epsilon}|\boldsymbol{x}; \boldsymbol{\phi}_g\right)
            = \log q\left(\tilde{\boldsymbol{y}}_s|\boldsymbol{x}; \boldsymbol{\phi}_g\right) + \log q\left(\tilde{\boldsymbol{y}}_{\epsilon}|\boldsymbol{x}, \tilde{\boldsymbol{y}}_s; \boldsymbol{\phi}_g\right).
        \end{equation}
        Since both $\tilde{\boldsymbol{y}}_s$ and $\tilde{\boldsymbol{y}}_{\epsilon}$ are determined based on a parametric inference model $g_a\left(\boldsymbol{x}; \boldsymbol{\phi}_g\right)$ and uniform density on the unit interval centered on $\boldsymbol{y}_s$ and $\boldsymbol{y}_{\epsilon}$, this term equals a constant $0$.

        \item For the second term $- \log p_{\boldsymbol{\mathcal{X}} | \tilde{\boldsymbol{y}}_s} \left(\boldsymbol{\mathcal{X}} | \tilde{\boldsymbol{y}}_s\right)$, with the outside expectations $\mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}|\boldsymbol{x} \sim q}$, the minimization of this term can be equivalent to minimizing an weighted expected distortion $\mathbb{E}_{\boldsymbol{x} \sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_i\in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[d\left(\boldsymbol{x}, \tilde{\boldsymbol{x}}_i\right)\right]$ plus an weighted E-KLD term $\mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_i\in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} D_{\text{KL}} \left[p_{\boldsymbol{x}} || p_{\tilde{\boldsymbol{x}}_i}\right]$, 
        by \cref{ENLSL}.

        \item For the third term $- \log p_{\tilde{\boldsymbol{y}}_s}\left(\tilde{\boldsymbol{y}}_s\right)$, it is the coding rate of the synonymous representations. With the outside expectations, it is also equivalent to the semantic entropy of semantic variable $\tilde{\mathring{Y}}$ corresponding to a latent synset $\tilde{\boldsymbol{\mathcal{Y}}}$. This can be derived by
        \begin{equation}\label{latentSemanticEntropy}
        \begin{aligned}
            \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}|\boldsymbol{x} \sim q} \left[
                - \log p_{\tilde{\boldsymbol{y}}_s}\left(\tilde{\boldsymbol{y}}_s\right)
            \right] 
            & = \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}|\boldsymbol{x} \sim q} \left[
                - \log \int_{\tilde{\boldsymbol{y}}_{\epsilon}} p_{\tilde{\boldsymbol{y}}_s}\left(\tilde{\boldsymbol{y}}_s, \tilde{\boldsymbol{y}}_{\epsilon}\right) d \tilde{\boldsymbol{y}}_{\epsilon}
            \right] \\
            & = \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}|\boldsymbol{x} \sim q} \left[
                - \log \int_{\tilde{\boldsymbol{y}} \in \tilde{\boldsymbol{\mathcal{Y}}}} p_{\tilde{\boldsymbol{y}}}\left(\tilde{\boldsymbol{y}}\right) d \tilde{\boldsymbol{y}} 
            \right] \\
            & \overset{(\mathrm{a})}{=} H_s\left(\tilde{\mathring{\boldsymbol{Y}}}\right),
        \end{aligned}
        \end{equation}
        in which $(\mathrm{a})$ is achieved based on the definition of semantic entropy in Niu and Zhang's paper \yrcite{niu2024mathematical}, with the help of the weak law of large numbers. Additionally, considering the determined codec, the semantic entropy $H_s\left(\tilde{\mathring{\boldsymbol{Y}}}\right)$ is equivalent to single-side semantic mutual information, i.e.,
        \begin{equation}\label{mutualInformationEquations}
            H_s\left(\tilde{\mathring{\boldsymbol{Y}}}\right) \overset{(\mathrm{a})}{=} H_s\left(\tilde{\mathring{\boldsymbol{X}}}\right) \overset{(\mathrm{b})}{=} H_s\left(\tilde{\mathring{\boldsymbol{X}}}\right) - H_s\left(\tilde{\mathring{\boldsymbol{X}}}|\boldsymbol{X}\right)
            \overset{(\mathrm{c})}{=} I\left(\boldsymbol{X};\tilde{\mathring{\boldsymbol{X}}}\right),
        \end{equation}
        where $(\mathrm{a})$ is by giving a determined decoder to map the latent synset $\tilde{\boldsymbol{\mathcal{Y}}}$ to the reconstructed synset $\tilde{\boldsymbol{\mathcal{X}}}$; $(\mathrm{b})$ is achieved by a determined encoder, which makes $\log q\left(\tilde{\boldsymbol{\mathcal{X}}}|\boldsymbol{x}\right) = \log q\left(\tilde{\boldsymbol{y}}_s|\boldsymbol{x}\right) = 0$ with a uniform density on the unit interval centered on $\boldsymbol{y}_s$; $(\mathrm{c})$ is by the definition of this single-side semantic mutual information.

        \item For the fourth term $- \log p_{\boldsymbol{\mathcal{X}}}\left(\boldsymbol{\mathcal{X}}\right)$, with the determination of the ideal synset $\boldsymbol{\mathcal{X}}$ for the original image $\boldsymbol{x}$, it is a constant that cannot be optimized.
    \end{enumerate}

    To summarize, the minimization of \eqref{SVIderivation} is equivalent to the following optimization directions
    \begin{equation}
    \begin{aligned}
        \mathcal{L}_{{\boldsymbol{\mathcal{X}}}} &= \lambda_d \cdot \mathbb{E}_{x\sim p\left(x\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_i \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} \left[d\left(\boldsymbol{x}, \tilde{\boldsymbol{x}}_i\right)\right] + \lambda_p \cdot \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \mathbb{E}_{\tilde{\boldsymbol{x}}_i \in \tilde{\boldsymbol{\mathcal{X}}} |\tilde{\boldsymbol{y}}_s} D_{\text{KL}}\left[p_{\boldsymbol{x}} || p_{\tilde{\boldsymbol{x}}_i}\right] \\
        & \quad\quad + \mathbb{E}_{x\sim p\left(x\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}\left[- \log p_{\tilde{\boldsymbol{y}}_s}\left(\tilde{\boldsymbol{y}}_s\right)\right].
    \end{aligned}
    \end{equation}
    At the convergence point, when the minimum value of the loss function is achieved, the model effectively minimizes the single-side semantic mutual information with the quantized form of $\hat{\mathring{\boldsymbol{X}}}$ under the constraints of bounded quantized expected distortion and E-KLD, as follows in \eqref{SVIgoal_inAppendix}. The weights $\lambda_d$ and $\lambda_p$ can be considered as Lagrange multipliers to the rate term. So we conclude this theorem.
\end{proof}

From the proof of \cref{ENLSL} and \cref{SICtheorem} above, we can see that the differences between the proposed SVI and conventional variational inference in guiding image compression tasks mainly include:
\begin{itemize}
    \item \emph{\textbf{The Analysis Method for the Likelihood Term:}} Conventional variational inference treats the likelihood term $-\log \left(\boldsymbol{x}|\tilde{\boldsymbol{y}}\right)$ in usual LIC methods as a weighted distortion \cite{balle2016end, blau2018perception}, primarily because the synonymous relationship emphasized in this paper is not incorporated in these works. 

    In our proposed SVI, since the synonymous relationship is considered, the likelihood term primarily focuses on the mapping relationship between the latent synset and the ideal synset, which is formed by $-\log p_{\boldsymbol{\mathcal{X}|\tilde{\boldsymbol{y}}_s}}\left(\boldsymbol{\mathcal{X}|\tilde{\boldsymbol{y}}_s}\right)$. \cref{ENLSL} states that the minimization of the expected synonymous likelihood term is equivalent to the minimization of a tradeoff function with weighted expected distortion and weighted E-KLD term. 

    Additionally, the analytical process of \cref{ENLSL} emphasizes that \textbf{the fundamental reason for the expected KL divergence term's existence is due to the consideration of the ideal synset $\boldsymbol{\mathcal{X}}$ centered by the original image $\boldsymbol{x}$}. Once the ideal synset is unconsidered (equal to the ideal synset only contains the original image, i.e., $\boldsymbol{\mathcal{X}} = \left\{\boldsymbol{x}\right\}$), the expected KL divergence term will disappear in the analysis result, which means the degradation to solely the weighted distortion term. Therefore, we can give the following statement: 

    \textbf{To the best knowledge of our authors, our method is the first work that can theoretically explain the fundamental reason for the divergence measure's existence in perceptual image compression, which stems from considering the ideal synset as the reconstruction reference.}

    \item \emph{\textbf{The Considerations on Coding Rates:}} Conventional variational inference considers performing entropy coding for all latent representations, whose coding rate can be represented as $- \log p\left(\tilde{\boldsymbol{y}}\right)$.

    In our proposed SVI, only a partial of the latent representation is required to be encoded, whose coding rate is expressed as $- \log p\left(\tilde{\boldsymbol{y}}_s\right)$. We emphasize that the other partial, i.e., the detailed representation, is not required to be coded: it can also be sampled from the latent synset $\tilde{\boldsymbol{\mathcal{Y}}}$ by the decoder, which is not necessary to keep consistency with it at the encoder end. This stems from the change in optimization direction from the original sample-oriented to the ideal synset-oriented, which allows the decoder to generate any samples that can exist in the ideal synset. 

    Since the detailed representation can be obtained by sampling at the receiving end and is allowed to contribute effective information for image reconstruction, encoding only the synonymous representation part theoretically improves coding efficiency compared to traditional methods. From the perspective of mutual information, this can be expressed as $I\Big(\boldsymbol{X};\hat{\mathring{\boldsymbol{X}}}\Big) \leq I\Big(\boldsymbol{X};\hat{\boldsymbol{X}}\Big)$, in which the condition for the inequality to hold as equality is that the reconstruction of the synonym set is restricted to producing only one sample, meaning the decoder is not allowed to sample $\hat{\boldsymbol{y}}_{\epsilon, j}$, nor is it permitted to use $\hat{\boldsymbol{y}}_{\epsilon, j}$ as input to the generator.

\end{itemize}


\subsection{Discussions on the Relationships with Existing Image Compression Theories}
\label{section_A_3}

From \cref{ENLSL}, \cref{SICtheorem}, and their respective proof processes, it is evident that the optimization objective derived in this paper through synonymous variational inference is compatible with the optimization objectives of existing image compression theories:

\begin{itemize}
    \item \emph{\textbf{Compatibility with Existing Rate-Distortion-Perception Tradeoff:}} According to the triple tradeoff shown as \eqref{SVIgoal_inAppendix}, when the reconstructed synset is not considered (equal to the reconstructed synset contains only one sample, represented as $\hat{\boldsymbol{\mathcal{X}}} = \left\{\hat{\boldsymbol{x}}\right\}$), the optimization objective will be degraded into the existing rate-distortion-perception tradeoff. This relationship can be expressed by
    \begin{equation}
        \begin{matrix}
	    \begin{aligned}
	       R\left(\boldsymbol{\mathcal{X}}\right) = & \min_{p(\hat{\boldsymbol{\mathcal{X}}}|\boldsymbol{x})} I\left(\boldsymbol{X}; \hat{\mathring{\boldsymbol{X}}}\right) \\
            & \mathrm{s}.\mathrm{t}. \quad \mathbb{E}_{\boldsymbol{x} \sim p\left(\boldsymbol{x}\right)}  \mathbb{E}_{\hat{\boldsymbol{x}}_i \in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} \left[d\left(\boldsymbol{x}, \hat{\boldsymbol{x}}_i\right)\right] \leq D, \\
            & \quad\quad\,\, \mathbb{E}_{\hat{\boldsymbol{x}}_i \in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} D_{\text{KL}} \left[p_{\boldsymbol{x}} || p_{\hat{\boldsymbol{x}}_i}\right] \leq P,
        \end{aligned}&		
        \xRightarrow{\hat{\boldsymbol{\mathcal{X}}}=\left\{ \hat{\boldsymbol{x}} \right\}}&		
        \begin{aligned}
	       R\left( D,P \right) &=\min_{p(\hat{\boldsymbol{x}}|\boldsymbol{x})} I\left( \boldsymbol{X};\hat{\boldsymbol{X}} \right)\\
	       &\mathrm{s}.\mathrm{t}.\quad \mathbb{E} _{\boldsymbol{x}\sim p\left( \boldsymbol{x} \right)} \left[ d\left( \boldsymbol{x},\hat{\boldsymbol{x}} \right) \right] \le D,\\
	       &\quad \quad \,\, D_{\mathrm{KL}}\left[ p_{\boldsymbol{x}}||p_{\hat{\boldsymbol{x}}} \right] \le P,
        \end{aligned}
        \end{matrix}
    \end{equation}
    in which the KL divergence $D_{\mathrm{KL}}\left[ p_{\boldsymbol{x}}||p_{\hat{\boldsymbol{x}}} \right]$ is a typical measure of the divergence between distributions, i.e., $d_p\left(p_{\boldsymbol{x}},p_{\hat{\boldsymbol{x}}}\right)$ in \eqref{RDPbound}, as stated in \cite{blau2019rethinking}. In view of this, the existing rate-distortion-perception tradeoff \eqref{RDPcost} is a special case of \eqref{SICcost} when there is only one sample $\hat{\boldsymbol{x}}$ in the reconstructed synset $\hat{\boldsymbol{\mathcal{X}}}$.

    \item \emph{\textbf{Compatibility with Traditional Rate-Distortion Tradeoff:}} Based on the analytical process of \cref{ENLSL}, when the ideal synset is not considered (equal to the ideal synset contains only the original image, represented as $\boldsymbol{\mathcal{X}} = \left\{\boldsymbol{x}\right\}$), the expected synonymous likelihood term will be degraded into the usual likelihood term, i.e.,
    \begin{equation}
        \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} 
        \left[-\log p_{\boldsymbol{\mathcal{X}|\tilde{\boldsymbol{y}}_s}}\left(\boldsymbol{\mathcal{X}|\tilde{\boldsymbol{y}}_s}\right)\right]
        \xRightarrow{\boldsymbol{\mathcal{X}}=\left\{\boldsymbol{x} \right\}} 
        \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)}
        \left[- \log p_{\boldsymbol{x}|\tilde{\boldsymbol{y}}}\left(\boldsymbol{x}|\tilde{\boldsymbol{y}}\right)\right],
    \end{equation}
    in which the minimization of the usual likelihood term $\mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)}
    \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q}
    \left[- \log p_{\boldsymbol{x}|\tilde{\boldsymbol{y}}}\left(\boldsymbol{x}|\tilde{\boldsymbol{y}}\right)\right]$ is equivalent to the minimization of a weighted distortion $\lambda \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)}
    \mathbb{E}_{\tilde{\boldsymbol{y}}\sim q} \left[d\left(\boldsymbol{x}, \tilde{\boldsymbol{x}}\right)\right]$, makes the existence of the KL divergence term unnecessary. Additionally, $\boldsymbol{\mathcal{X}} = \left\{\boldsymbol{x}\right\}$ will also implicitly makes the existence of $\hat{\boldsymbol{y}}_{\epsilon, j}$ unnecessary, which results in $\hat{\boldsymbol{\mathcal{X}}} = \left\{\hat{\boldsymbol{x}}\right\}$. Therefore, the relationship with the traditional rate-distortion tradeoff can be represented by
    \begin{equation}
        \begin{matrix}
	    \begin{aligned}
	       R\left(\boldsymbol{\mathcal{X}}\right) = & \min_{p(\hat{\boldsymbol{\mathcal{X}}}|\boldsymbol{x})} I\left(\boldsymbol{X}; \hat{\mathring{\boldsymbol{X}}}\right) \\
            & \mathrm{s}.\mathrm{t}. \quad \mathbb{E}_{\boldsymbol{x} \sim p\left(\boldsymbol{x}\right)}  \mathbb{E}_{\hat{\boldsymbol{x}}_i \in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} \left[d\left(\boldsymbol{x}, \hat{\boldsymbol{x}}_i\right)\right] \leq D, \\
            & \quad\quad\,\, \mathbb{E}_{\hat{\boldsymbol{x}}_i \in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} D_{\text{KL}} \left[p_{\boldsymbol{x}} || p_{\hat{\boldsymbol{x}}_i}\right] \leq P,
        \end{aligned}&		
        \xRightarrow[\left(\hat{\boldsymbol{\mathcal{X}}} = \left\{\hat{\boldsymbol{x}}\right\}\right)]{{\boldsymbol{\mathcal{X}}}=\left\{{\boldsymbol{x}} \right\}}&		
        \begin{aligned}
	       R\left( D\right) &=\min_{p(\hat{\boldsymbol{x}}|\boldsymbol{x})} I\left( \boldsymbol{X};\hat{\boldsymbol{X}} \right)\\
	       &\mathrm{s}.\mathrm{t}.\quad \mathbb{E} _{\boldsymbol{x}\sim p\left( \boldsymbol{x} \right)} \left[ d\left( \boldsymbol{x},\hat{\boldsymbol{x}} \right) \right] \le D.
        \end{aligned}
        \end{matrix}
    \end{equation}
    In view of this, we state that the traditional rate-distortion tradeoff is also a special case of \eqref{SICcost}, where the condition is that the ideal synset $\boldsymbol{\mathcal{X}}$ always contains only a single sample, i.e., the original $\boldsymbol{x}$.

\end{itemize}

Therefore, we demonstrate that the foundational theories underlying existing image compression methods can be viewed as special cases of our analysis viewpoint. In other words, our theoretical analysis provides consistent and universal guidance for designing image compression approaches, regardless of whether compression is considered for perceptual quality. 

It should be noted that, although the E-KLD term in the above analysis represents the optimal distribution distance selection based on minimizing the partial semantic KL divergence, accurately calculating the E-KLD between two image sets may be unrealistic due to the complexity of the image source. Therefore, we can refer to existing empirical practices in perceptual image compression, such as using metrics that tend to be subjective, like LPIPS or DISTS, instead of the KL divergence calculation, or using adversarial losses in the GAN training process, such as Wasserstein loss, as a substitute for KL divergence.


\section{Relevant Thoughts on Semantic Information Theory}
\label{section_B}

In this appendix section, we will briefly provide relevant thoughts on semantic information theory based on our analytical results. We emphasize that the semantic information theory referenced here specifically pertains to the synonymity-based semantic information theory, primarily derived from Niu and Zhang's paper \cite{niu2024mathematical}.

\subsection{Relationships with Existing Conclusions in Semantic Information Theory}
\label{section_B_1}

\begin{itemize}
    \item \emph{\textbf{Semantic Entropy:}} Given a semantic variable $\mathring{U}$, whose possible values are the synset $\mathcal{U}_{i_s}=\left\{u_i|i\in \mathcal{N}_{i_s}\right\}$, $, i_s = 1, 2, ..., N$, and $\mathcal{N}_{i_s}$ is the set of ordinal numbers of all syntactic symbols $u_i \in \mathcal{U}_{i_s}$, the semantic entropy of the semantic variable is expressed as:
    \begin{equation}
        H_s\left(\mathring{U}\right) 
        = - \sum_{i_s = 1}^{N} p\left(\mathcal{U}_{i_s}\right) \log p\left(\mathcal{U}_{i_s}\right) 
        = - \sum_{i_s = 1}^{N} \sum_{i \in \mathcal{N}_{i_s}} p\left(u_i\right) \log \left(\sum_{i \in \mathcal{N}_{i_s}} p\left(u_i\right)\right),
    \end{equation}
    in which the probability a single semantic symbol corresponds to the synset $\mathcal{U}_{i_s}$ is the sum of the probability of each syntactic value $u_i, i\in\mathcal{N}_{i_s}$, i.e., $p\left(\mathcal{U}_{i_s}\right) = \sum_{i \in \mathcal{N}_{i_s}} p\left(u_i\right)$.

    Additionally, the semantic source coding theorem in \cite{niu2024mathematical} states that, for a semantic source $\mathring{U}$ with its corresponding syntactic source $U$ and its determined synonymous mapping between these two types of sources (which results in the determined synsets $\mathcal{U}_{i_s}=\left\{u_i|i\in \mathcal{N}_{i_s}\right\}$, $i_s = 1, 2, ..., N$), the achievable coding rate for semantic lossless rate is $R \ge H_s\left(\mathring{U}\right)$ without the necessity to focus on symbol-level accuracy.

    In our work, we point out that the ultimate goal of synonymous variational inference is to construct an ideal synset $\boldsymbol{\mathcal{X}}$ corresponding to the original image $\boldsymbol{x}$ by finding a synonymous mapping rule and encoding the shared latent features of the ideal synset $\hat{\boldsymbol{y}}_s$ as the coding sequences. In the ideal scenario where model training has converged, the reconstructed synset $\hat{\boldsymbol{\mathcal{X}}}$ at the SIC decoder can perfectly overlap with the ideal synset $\boldsymbol{\mathcal{X}}$. Under such conditions, the average coding rate of the synonymous representation $\hat{\boldsymbol{y}}_s$ in the latent space can approach the semantic entropy of the semantic variable corresponding to the ideal synset, i.e.,
    \begin{equation}
        \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \left[- \log p\left(\boldsymbol{\hat{y}}_s\right)\right]
        \overset{(\mathrm{a})}{=} H_s\left(\hat{\mathring{\boldsymbol{Y}}}\right)
        \overset{(\mathrm{b})}{=}
        H_s\left(\hat{\mathring{\boldsymbol{X}}}\right)
        \overset{(\mathrm{c})}{=}
        I\left(\boldsymbol{X}; \hat{\mathring{\boldsymbol{X}}}\right)
        \overset{(\mathrm{d})}{=}
        H_s\left(\mathring{\boldsymbol{X}}\right),
    \end{equation}
    in which the established conditions of $(\mathrm{a}) \sim (\mathrm{c})$ is the same as the conditions in \eqref{latentSemanticEntropy} and \eqref{mutualInformationEquations}, and $(\mathrm{d})$ is achieved by the ideal SIC codec. At this point, the found synonymous mapping rule is determined by the bounded expected distortion and the bounded E-KLD, i.e., $\mathbb{E}_{\boldsymbol{x} \sim p\left(\boldsymbol{x}\right)}  \mathbb{E}_{\hat{\boldsymbol{x}}_i \in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} \left[d\left(\boldsymbol{x}, \hat{\boldsymbol{x}}_i\right)\right] \leq D, \mathbb{E}_{\hat{\boldsymbol{x}}_i\in \hat{\boldsymbol{\mathcal{X}}} |\boldsymbol{\hat{y}}_s} D_{\text{KL}} \left[p_{\boldsymbol{x}} || p_{\hat{\boldsymbol{x}}_i}\right] \leq P$.

    \item \emph{\textbf{Down Semantic Mutual Information:}} The down semantic mutual information is a measure defined as
    \begin{equation}
        I_s\left(\mathring{U};\mathring{V}\right) = H_s\left(\mathring{U}\right) + H_s\left(\mathring{V}\right) - H\Big(U, V\Big),
    \end{equation}
    which is proved to be the minimum coding rate in semantic lossy source coding when the ``semantic distortion'' (denoted as $d_s\left(\mathring{X}, \hat{\mathring{X}}\right)$ in concept) satisfying $d_s\left(\mathring{X}, \hat{\mathring{X}}\right) \le D_s$, using an extended joint asymptotic equipartition property (AEP) analysis called \emph{Semantically Joint AEP}.

    In our work, since the ideal synset is not explicitly constructed in practice, directly determining the overlap degree between the reconstructed synset and the ideal synset is challenging. Consequently, the model obtained after training convergence may still function as a semantic lossy coding model. We propose that the coding rate of the SIC model should also serve as an upper bound for the lower semantic mutual information, expressed as:
    \begin{equation}
    \begin{aligned}
        \mathbb{E}_{\boldsymbol{x}\sim p\left(\boldsymbol{x}\right)} \left[- \log p\left(\boldsymbol{\hat{y}}_s\right)\right]
        & \overset{(\mathrm{a})}{=} H_s\left(\hat{\mathring{\boldsymbol{Y}}}\right)
        \overset{(\mathrm{b})}{=}
        H_s\left(\hat{\mathring{\boldsymbol{X}}}\right)
        \overset{(\mathrm{c})}{=}
        H_s\left(\hat{\mathring{\boldsymbol{X}}}\right) - H_s\left(\hat{\mathring{\boldsymbol{X}}} | \boldsymbol{X}\right) \\
        & \overset{(\mathrm{d})}{=}
        H\Big(\boldsymbol{X}\Big) + H_s\left(\hat{\mathring{\boldsymbol{X}}}\right) - H_s\left(\boldsymbol{X}, \hat{\mathring{\boldsymbol{X}}}\right) \\
        & \overset{(\mathrm{e})}{\ge}
        H_s\left(\mathring{\boldsymbol{X}}\right) + H_s\left(\hat{\mathring{\boldsymbol{X}}}\right) - H\left(\boldsymbol{X}, \hat{\boldsymbol{X}}\right) \\
        & = I_s\left(\mathring{\boldsymbol{X}}; \hat{\mathring{\boldsymbol{X}}}\right),
    \end{aligned}
    \end{equation}
    in which the established conditions of $(\mathrm{a}) \sim (\mathrm{c})$ is the same as the conditions in \eqref{latentSemanticEntropy} and \eqref{mutualInformationEquations}, $(\mathrm{d})$ is achieved by the equation $H_s\left(\hat{\mathring{\boldsymbol{X}}} | \boldsymbol{X}\right) = H_s\left(\boldsymbol{X}, \hat{\mathring{\boldsymbol{X}}}\right) - H\Big(\boldsymbol{X}\Big)$, and $(\mathrm{e})$ can be proved by a scaling process according to $H\Big(\boldsymbol{X}\Big) \ge H_s\left(\mathring{\boldsymbol{X}}\right)$ and $H_s\left(\boldsymbol{X}, \hat{\mathring{\boldsymbol{X}}}\right) \le H\left(\boldsymbol{X}, \hat{\boldsymbol{{X}}}\right)$, which follows the fundamental properties of semantic variables stated in \cite{niu2024mathematical}.
\end{itemize}


