\section{Full Proofs of \texorpdfstring{\cref{sec:convex-free}}{Section 2}}

\facecomplexity*
\label{obs:face_complexity*}
\begin{proof}
    Let $\Gamma$ be a (not necessarily saturated) precolored convex $\Theta^k$-drawing and let~$\Gamma'$ be the outerplane embedding induced by one color class (which we call \emph{\blue}) and the outer cycle. 
    Suppose there exists a face~$f$ of~$\Gamma'$ of size at least~$2k$.
    We need to show that~$\Gamma$ is not saturated.
    Note that there is a set of $k$~diagonals of $f$ which all pairwise intersect.
    Since no two such diagonals lie in the same color class and in particular no such diagonal is \blue, at most $k-1$~of the diagonals are part of the drawing~$\Gamma$.
    As we can add the missing diagonal in \blue to~$\Gamma$, the drawing~$\Gamma$ is not saturated.
\end{proof}


\section{Omitted Proofs of \texorpdfstring{\cref{sec:non-convex-free}}{Section 3}}

Because every cell $c \in C(\Lambda)$ is convex, the vertices on its boundary are in convex position and we can create a red inner triangulation in $c$ and, by \cref{obs:edges_in_inner_triang_inner_quadrang}, we obtain
$\max\{0, \norm{c} - 3\}$ \red inner edges between vertices on the boundary of $c$.
Therefore, our goal is to show that the sum of these values over all cells of~$\Lambda$ plus the initial number of \red inner edges in $\Gamma$ adds up to at least $n' - 3$.

Let $\Gamma_r$ be the subdrawing of $\Gamma$ induced by the \red edges.
In particular, note that $\Gamma_r$ thus only contains vertices that are incident to \red edges.
With the following two propositions, we show that 
the number of inner cells in $\Lambda$ that contain a vertex $v\in V(\Gamma_r)$ on their boundary as well as the total number of cells of $\Lambda$ can be directly obtained from~$\Gamma_r$.

\begin{lemma}
\label{prop:numIncidences}
    Every vertex $v \in V(\Gamma_r)$ lies on the boundary of $\deg_{\Gamma_r}(v) + 1$ inner cells of~$\Lambda$.
\end{lemma}
\begin{proof}
    Recall that we assume the vertices of $\Gamma$ are in general position and therefore $v$ only lies on edge extensions of edges incident to $v$.
    Also note that the outer edges are not contained in $\Gamma_r$.

    If $v$ lies on the convex hull of $\Gamma$, it is not contained in the interior of any segments and~$v$ is the endpoint of exactly $\deg_{\Gamma_r}(v)$ edge extensions.
    Since $v$ is also incident to two edges of the outer cycle, $v$ therefore lies on the boundary of exactly $\deg_{\Gamma_r}(v) + 1$ internal cells of $\Lambda$.

    If $v$ does not lie on the convex hull of $\Gamma$, recall that $v$ lies in the interior of exactly one edge extension, since our construction ensures that no two such extensions cross.
    Since every edge incident to $v$ induces an edge extension that has $v$ as its endpoint, $v$ lies on the boundary of $\deg_{\Gamma_r}(v) + 1$ cells, which concludes the proof.
\end{proof}


\begin{figure}
\centering
\subcaptionbox{\label{fig:planarization-1}}{\includegraphics[page=1]{figures/Planarization_Sketch.pdf}}
\hfil
\subcaptionbox{\label{fig:planarization-2}}{\includegraphics[page=1]{figures/Planarization_Sketch.pdf}}
\caption{Left: A drawing $\Lambda$ obtained after extending all inner \red edges. Right: its corresponding planarization $H$. Note that the cells of $\Lambda$ correspond bijectively to the faces of the planarization.}
\label{fig:planarization}
\end{figure}


\begin{lemma}
\label{prop:numFaces}
    $\abs{C(\Lambda)} = \abs{E(\Gamma_r)} + 1$.
\end{lemma}
\begin{proof}
    Let $x \coloneqq \abs{E(\Gamma_r)}$, i.e., $x$ denotes the number of edge extensions in $\Lambda$.
    Starting from~$\Lambda$, we first construct a planar graph $H$ and a corresponding planar drawing $\mathcal E$ by erasing all vertices of $\Lambda$ from the drawing and placing a vertex on every point where two edge extensions touch or an extension touches the outer cycle; see \Cref{fig:planarization} for an example.
    Note that vertices on the outer cycle that are not incident to red edges are not part of~$H$.
    In the context of this proof, let $n$, $m$, and $f$ denote the number of vertices, edges, and faces of $\mathcal E$, respectively.
    Observe that $f = \abs{C(\Lambda)} + 1$, since $f$ also accounts for the outer face of $\mathcal E$.

    We first show that $m = n + x$.
    Observe that every touching point (and thus the corresponding vertex of $H$) either lies on the convex hull or in the interior of exactly one edge extension (otherwise the segments would cross, a contradiction).
    Let $n_1$ and $n_2$ be the number of vertices satisfying the former and the latter property, respectively.
    Because the convex hull results in a cycle with $n_1$ vertices, 
    it contains $m_1 \coloneqq n_1$ edges.
    Note that the $x$ edge extensions of $\Lambda$ result in $x$ edge-disjoint paths in $\mathcal E$ that make up exactly the remaining $m_2 \coloneqq m - m_1$ edges of $\mathcal E$.
    Also note that each of the $n_2$ inner vertices of $\Lambda$ is an internal (i.e., non-endpoint) vertex of exactly one such path and that the number of edges of a path is the number of its internal vertices plus one.
    Thus, the paths contain $m_2 \coloneqq n_2 + x$ edges overall.
    Because $n = n_1 + n_2$, we obtain $m = m_1 + m_2 = n + x$.

    Note that $H$ is connected, since every vertex is incident to an edge of the convex hull or an edge extension of $\Lambda$.
    By Euler's Formula, we therefore obtain
    \[ \abs{C(\Lambda)} = f - 1 = (2 - n + m) - 1 = 1 - n + m = 1 - n + (n + x) = 1 + x = \abs{E(\Gamma_r)} + 1.\qedhere\]
\end{proof}

We can now show the required statement relating the number of red edges to $n'$.

\begin{lemma}
    $\displaystyle\abs{E(\Gamma_r)} + \sum_{c \in C(\Lambda)} (\norm{c} - 3) \geq n' - 3$.
\end{lemma}
\begin{proof}
    Let $V_c(\Gamma)$ denote the vertices of $\Gamma$ that lie on the outer cycle of $\Gamma$ but are not contained in $\Gamma_r$, i.e., that are not incident to \red edges.
    Moreover, we let $V_0(\Gamma) \coloneqq V(\Gamma) \setminus (V(\Gamma_r) \cup V_c(\Gamma))$ denote all remaining vertices, i.e., the vertices that lie on the inside of $\Gamma$ and are not incident to a \red edge.

    Note that it suffices to show the following:
    \[ \displaystyle\abs{E(\Gamma_r)} + \sum_{c \in C(\Lambda)} (\norm{c} - 3) = \abs{V(\Gamma)} - \abs{V_0(\Gamma)} - 3 \] 
    Since $n' \leq \abs{V(\Gamma)} - \abs{V_0(\Gamma)}$, the statement of the lemma then follows.

    Note that we can compute the combined size of all cells by summing up the number of vertex-cell incidences over all vertices. 
    Since the vertices of $V_c(\Gamma)$ are incident to exactly one cell in $\Lambda$ and vertices of $V_0(\Gamma)$ lie on the boundary of no cells, we obtain the following equation using \cref{prop:numIncidences}.
    \begin{equation}
        \label{eq:faces}
        \sum_{c \in C(\Lambda)} \norm{c} = \sum_{v \in V(\Gamma_r)} (\deg_{\Gamma_r}(v) + 1)+ \abs{V_c(\Gamma)}
    \end{equation}
    Moreover, the degree sum formula yields the following equation.
    \begin{equation}
        \label{eq:degSum}
        \sum_{v \in V(\Gamma_r)} \deg_{\Gamma_r}(v) = 2\abs{E(\Gamma_r)}
    \end{equation}
    Combining these equations with \Cref{prop:numFaces}, we obtain the desired statement as follows.

    \newcommand\oversetto[3][]{\overset{\text{\makebox*{#1}{#2}}}{#3}}
    \begin{align*}
        & \abs{E(\Gamma_r)} + \sum_{c \in C(\Lambda)} (\norm{c} - 3) \\
        &= \abs{E(\Gamma_r)} + \sum_{c \in C(\Lambda)} \norm{c} - 3|C(\Lambda)| & (\ref{eq:faces})\\
        &= \abs{E(\Gamma_r)} + \sum_{v \in V(\Gamma_r)} (\deg_{\Gamma_r}(v) + 1)+ \abs{V_c(\Gamma)} - 3|C(\Lambda)| & (\ref{eq:degSum})\\
        &= 3\abs{E(\Gamma_r)} + \abs{V(\Gamma_r)} + \abs{V_c(\Gamma)} - 3|C(\Lambda)|\\
        &= 3\abs{E(\Gamma_r)} + \abs{V(\Gamma)} - \abs{V_0(\Gamma)} - 3|C(\Lambda)|& \text{\cref{prop:numFaces}} \\
        &= \abs{V(\Gamma)} - \abs{V_0(\Gamma)}  - 3 & &\qedhere
    \end{align*}
\end{proof}

Since we now have $3n-6-(n'-3)$ \blue edges and at least $n'-3$ \red edges, we obtain the following result.

\nonConvex*
\label{thm:non-convex-2-lower-bound*}


