\section{Appendix for Section \ref{sec:improving-mtl}}\label{sec:append-mtl}

We give the details of the construction of $\Aa'_{\varphi}$ for some given MTL formula $\varphi$ below, which is a modification of the construction in \cite{ouaknine2007decidability}. For a formula $\varphi$, we define the set of formulas $cl(\varphi)$ as the smallest set such that $\varphi \in cl(\varphi)$, a special element $\varphi_{init} \in cl(\varphi)$, every $\varphi_{1} \U_{I} \varphi_{2}$ that is a subformula of $\varphi$ is in $cl(\varphi)$, and for each $\X_{I} \varphi_{1}$ that is a subformula of $\varphi$, $(\X_{I}\varphi_{1})^r \in cl(\varphi)$.

\begin{definition}
  For an MTL formula $\varphi$, we define $\Aa'_{\varphi} = (\Sigma,Q,q_{0},F,\delta)$ to be a 1-ATA where $Q = cl(\varphi)$, $q_{0} = \varphi_{init}$ and $F = \emptyset$. 
  To define $\delta$ for $\Aa_{\varphi}$, we define the values of $\delta$ for all subformulas of $\varphi$, not just the elements of $cl(\varphi)$, for convenience. For $a,b \in \Sigma$:
  \begin{itemize}
    \item $\delta(\varphi_{init},a) = \inact{x}.\delta(\varphi,a)$ if $\varphi$ is a pure LTL formula, else $= x.\delta(\varphi,a)$
    \item $\delta(\varphi_{1} \land \varphi_{2},a) = 
    \begin{cases}
    \inact{x}.\delta(\varphi_{1},a) \land \inact{x}.\delta(\varphi_{2},a) & \text{if $\varphi_{1},\varphi_{2}$ are pure LTL formulas} \\
    \inact{x}.\delta(\varphi_{1},a) \land \delta(\varphi_{2},a) & \text{if only $\varphi_{1}$ is a pure LTL formula} \\
    \delta(\varphi_{1},a) \land \inact{x}.\delta(\varphi_{2},a) & \text{if only $\varphi_{2}$ is a pure LTL formula} \\
    \delta(\varphi_{1},a) \land \delta(\varphi_{2},a) & \text{otherwise}
    \end{cases}$ 
    \item $\delta(\varphi_{1} \lor \varphi_{2},a) = 
    \begin{cases}
    \inact{x}.\delta(\varphi_{1},a) \lor \inact{x}.\delta(\varphi_{2},a) & \text{if $\varphi_{1},\varphi_{2}$ are pure LTL formulas} \\
    \inact{x}.\delta(\varphi_{1},a) \lor \delta(\varphi_{2},a) & \text{if only $\varphi_{1}$ is a pure LTL formula} \\
    \delta(\varphi_{1},a) \lor \inact{x}.\delta(\varphi_{2},a) & \text{if only $\varphi_{2}$ is a pure LTL formula} \\
    \delta(\varphi_{1},a) \lor \delta(\varphi_{2},a) & \text{otherwise}
    \end{cases}$ 
    \item $\delta(\X_{I} \varphi_{1},a) = x.(\X_{I}\varphi_{1})^r$
    \item $\delta((\X_{I}\varphi_{1})^r,a) = I \land \inact{x}.\delta(\varphi_{1},a)$ if $\varphi_{1}$ is a pure LTL formula, else $= I \land x.\delta(\varphi_{1},a)$
    \item $\delta(\varphi_{1} \U_{I} \varphi_{2},a) = \begin{cases}
    (\inact{x}.\delta(\varphi_{2},a) \land (I)) \lor (\inact{x}.\delta(\varphi_{1},a) \land (\varphi_{1} \U_{I} \varphi_{2})) & \text{ if $\varphi_{1},\varphi_{2}$ are pure LTL formulas}\\
    (x.\delta(\varphi_{2},a) \land (I)) \lor (\inact{x}.\delta(\varphi_{1},a) \land (\varphi_{1} \U_{I} \varphi_{2})) & \text{ if $\varphi_{1}$ is a pure LTL formula}\\
    (\inact{x}.\delta(\varphi_{2},a) \land (I)) \lor (x.\delta(\varphi_{1},a) \land (\varphi_{1} \U_{I} \varphi_{2})) & \text{ if $\varphi_{2}$ is a pure LTL formula}\\
    (x.\delta(\varphi_{2},a) \land (I)) \lor (x.\delta(\varphi_{1},a) \land (\varphi_{1} \U_{I} \varphi_{2})) & \text{ otherwise}
    \end{cases}$
    \item $\delta(b,a) = \begin{cases}
      \true & \text{ if }b = a \\
      \false & \text{ if }b \neq a
    \end{cases}$
    \item $\delta(\lnot b,a) = \begin{cases}
      \false & \text{ if }b = a \\
      \true & \text{ if }b \neq a
    \end{cases}$
  \end{itemize}
\end{definition}

\constcorr*
\begin{proof}
We first take a word $w = (d_{1},a_{1})\dots(d_{n},a_{n})$ and make a claim that for every subformula $\psi$ of $\varphi$, if $\psi$ is a purely LTL formula, $(w,i) \sat \psi$ iff there is an accepting run from $\{(\psi,\bot)\}$, and otherwise $(w,i) \sat \psi$ iff there is an accepting run from $\{(\psi,0)\}$ on the word $(d_{i},a_{i})\dots(d_{n},a_{n})$. We prove this claim by induction on the structure of $\psi$:
\begin{itemize}
  \item For $\psi = a$, $(w,i) \sat \psi$ iff $a_{i} = a$. From $\{(\psi,\bot)\}$, the transition $\delta(\psi,a)= \true$ iff $a=a_{i}$, so the word $(d_{i},a_{i})\dots(d_{n},a_{n})$ will have an accepting run iff $a_{i}=a$. The proof follows similarly for $\psi=\lnot a$.

  \item For $\psi = \psi_{1} \land \psi_{2}$, we first look at the case when $\psi_{1}$ and $\psi_{2}$ are both not purely LTL formulas. We see that $(w,i) \sat \psi$ iff $(w,i) \sat \psi_{1}$ and $(w,i) \sat \psi_{2}$. Also, there is an accepting run from $\{(\psi,0)\}$ on $(d_{i},a_{i})\dots(d_{n},a_{n})$ iff there is an accepting run from $\{(\psi_{1},0)\}$ and $\{(\psi_{2},0)\}$. This is because of the transition $\delta(\psi,a_{i}) = \delta(\psi_{1},a_{i}) \land \delta(\psi_{2},a_{i})$. Now, by our induction hypothesis, the word $(d_{i},a_{i})\dots(d_{n},a_{n})$ has an accepting run from $\{(\psi_{1},0)\}$ and $\{(\psi_{2},0)\}$ iff $(w,i) \sat \psi_{1}$ and $(w,i) \sat \psi_{2}$ respectively. Thus, $(w,i) \sat \psi$ iff there is an accepting run from $\{(\psi,0)\}$ on $(d_{i},a_{i})\dots(d_{n},a_{n})$. We can similarly prove the claim for the cases where either $\psi_{1}$ or $\psi_{2}$ is a purely LTL formula, and when both are purely LTL formulas. The proof follows similarly for $\psi=\psi_{1} \lor \psi_{2}$.

  \item For $\psi = \X_{I} \psi'$, we see that $(w,i) \sat \psi$ iff $(w,i+1) \sat \psi'$ and $d_{i+1} \in I$. If $\psi'$ is a pure LTL formula, then $\{(\psi,0)\}$ has an accepting run on $(d_{i},a_{i})\dots(d_{n},a_{n})$, say $\{(\psi,0)\} \xra{d_{i},a_{i},C_{i}}\gamma_{1} \dots \gamma_{n-i}$, iff $((\X_{I}\psi')^r,0) \in \gamma_{1}$, because of the transition $\delta(\psi,a_{i}) = x.(\X_{I} \psi')^r$. Now, because of tranistion $\delta((\X_{I} \psi')^r,a_{i+1}) = I \land \inact{x}.\delta(\psi',a_{i+1})$, $\{(\psi,0)\} \xra{d_{i},a_{i},C_{i}}\gamma_{1} \dots \gamma_{n-i}$ is an accepting run iff $\gamma_{2}$ is a minimal model of $\delta(\psi',a_{i+1})$ on $\bot$ and $a_{i+1} \in I$. This means we can say there is an accepting run from $\{(\psi',\bot)\}$ on $(d_{i+1},a_{i+1})\dots(d_{n},a_{n})$ and $a_{i+1} \in I$ iff $\{(\psi,0)\} \xra{d_{i},a_{i}}\gamma_{1} \dots \gamma_{n-i}$ is an accepting run. By our induction hypothesis, we have that $(w,i+1) \sat \psi'$ iff there is an accepting run from $\{(\psi',\bot)\}$ on $(d_{i+1},a_{i+1})\dots(d_{n},a_{n})$. This means $(w,i) \sat \psi$ iff there is an accepting run from $\{(\psi,0)\}$ on $(d_{i},a_{i})\dots(d_{n},a_{n})$. We can similarly prove the claim for the case where $\psi'$ is not a purely LTL formula. 

  \item For $\psi = \psi_{1} \U_{I} \psi_{2}$, we see that $(w,i) \sat \psi$ iff there is some $1 \leq k \leq n$ such that $(w,k) \sat \psi_{2}$, $\sum_{c=i+1}^k d_{c} \in I$, and for all $1 \leq j < k$, $(w,j) \sat \psi_{1}$. If both $\psi_{1}$ and $\psi_{2}$ are purely LTL formulas, then $\{(\psi,0)\}$ has an accepting run on $(d_{i},a_{i})\dots(d_{n},a_{n})$, say $\rho$, iff $0 \in I$ and there is an accepting run from $\{(\psi_{2},\bot)\}$ on $(d_{i},a_{i})\dots(d_{n},a_{n})$, or if there is an accepting run from $\{(\psi_{1},\bot)\}$ on $(d_{i},a_{i})\dots(d_{n},a_{n})$ and one from $\{(\psi,0)\}$ on $(d_{i+1},a_{i+1})\dots(d_{n},a_{n})$. This is because of the transition $\delta(\psi,a_{i}) = (\inact{x}.\delta(\psi_{2},a) \land I) \lor (\inact{x}.\delta(\psi_{1},a) \land (\varphi_{1} \U_{I} \varphi_{2}))$. Now, because 
  $\rho$ is a finite run, we can rewrite the above condition to say there is an accepting run from $\{(\psi,0)\}$ iff there is some $1 \leq k \leq n$ such that there is an accepting run from $\{(\psi_{1},\bot)\}$ on $(d_{j},a_{j})\dots(d_{n},a_{n})$ for each $i \leq j< k$, $\sum_{c=i+1}^k d_{c} \in I$, and there is an accepting run from $\{(\psi_{2},\bot)\}$ on $(d_{k},a_{k})\dots(d_{n},a_{n})$. By our induction hypothesis, the word $(d_{i},a_{i})\dots(d_{n},a_{n})$ has an accepting run from $\{(\psi_{1},\bot)\}$ and $\{(\psi_{2},\bot)\}$ iff $(w,i) \sat \psi_{1}$ and $(w,i) \sat \psi_{2}$ respectively. This means $\rho$ 
  is an accepting run iff there is some $1 \leq k \leq n$ such that for all $1 \leq j < k$, $(w,j) \sat \psi_{1}$, $\sum_{c=i+1}^k d_{c} \in I$, and $(w,k) \sat \psi_{2}$. We can similarly prove the claim for the case when one of $\psi_{1}$ and $\psi_{2}$ is a purely LTL formula and when both are not purely LTL formulas. 
\end{itemize}
Now, looking at $w$ and $i=1$, we know that $w \in L(\varphi)$ iff $(w,1) \sat \varphi$. By our claim, this happens iff there is an accepting run from either $\{(\varphi,\bot)\}$ or $\{(\varphi,0)\}$ on $w$ depending on whether $\varphi$ is a purely LTL formula or not. Looking at the initial state $\varphi_{init}$ in $\Aa'_{\varphi}$, we see that when $\varphi$ is a purely LTL formula, there is an accepting run from $\gamma_{0} = \{(\varphi_{init},0)\}$ on $w$ iff there is an accepting run from $\{(\varphi,\bot)\}$ on $w$ due to the transition $\delta(\varphi_{init},a) = \inact{x}.\delta(\varphi,a)$. Similarly, if $\varphi$ is not a purely LTL formula, there is an accepting run from $\gamma_{0} = \{(\varphi_{init},0)\}$ on $w$ iff there is an accepting run from $\{(\varphi,0)\}$ on $w$ due to the transition $\delta(\varphi_{init},a) = x.\delta(\varphi,a)$. This means $w \in L(\varphi)$ iff $w \in L(\Aa'_{\varphi})$, hence $L(\varphi) = L(\Aa'_{\varphi})$.
\end{proof}

\mtlbdd*
\begin{proof}
Let $\varphi$ be the one-sided MTL formula and let $\Aa'_{\varphi}$ be the 1-ATA constructed for it. To prove there is a bound on the number of active states in the reachable configurations, we claim that for every subformula $\psi$ of $\varphi$, every configuration reachable from $\{(\psi,0)\}$ in $\Aa'_{\varphi}$ has at most $k_{\psi}$ active states, where we define $k_{\psi}$ as follows:
\begin{itemize}
    \item[-] If $\psi$ is a pure LTL formula, then $k_{\psi} = 1$.
    \item[-] If $\psi = \psi_{1} \lor \psi_{2}$, then $k_{\psi} = \max(k_{\psi_{1}},k_{\psi_{2}})$.
    \item[-] If $\psi = \psi_{1} \land \psi_{2}$, then $k_{\psi} = k_{\psi_{1}} + k_{\psi_{2}}$.
    \item[-] If $\psi = X_{I} \psi'$, then $k_{\psi} = k_{\psi'}$.
    \item[-] If $\psi = \psi_{1} \U_{I} \psi_{2}$, then $k_{\psi} = k_{\psi_{2}}$.
\end{itemize}
We prove this claim by induction on structure of $\psi$. 
\begin{itemize}
    \item For $\psi = a$ or $\lnot a$, starting from configuration $\{(a,v)\}$ or $\{(\lnot a,v)\}$, $\delta(\psi,a)$ for some $a$ will be either $\true$ or $\false$, and so either the minimal model for it will be $\emptyset$, or there will be no possible model. Hence all reachable configurations from $\psi$ will have at most 1 active state.

    \item For $\psi = \psi_{1} \lor \psi_{2}$, starting from configuration $\{(\psi_{1} \lor \psi_{2},0)\}$, when both $\psi_{1}$ and $\psi_{2}$ are not pure LTL formulas, $\delta(\psi,a)$ for some $a$ will be $\delta(\psi_{1},a) \lor \delta(\psi_{2},a)$. So any minimal model for $\delta(\psi,a)$ on 0 will also be a minimal model for either $\delta(\psi_{1},a)$ or $\delta(\psi_{2},a)$ on 0, and so all configurations reachable from $\{(\psi_{1} \lor \psi_{2},0)\}$ will be reachable configurations from either $\{(\psi_{1},0)\}$ or $\{(\psi_{2},0)\}$. By the induction hypothesis on $\psi_{1},\psi_{2}$, we know that all reachable configurations from $\{(\psi_{1},0)\}$ and $\{(\psi_{2},0)\}$ will have at most $k_{\psi_{1}}$ and $k_{\psi_{2}}$ active states respectively. Hence all reachable configurations from $\{(\psi,0)\}$ will have at most $\max(k_{\psi_{1}},k_{\psi_{2}})$ active states. In the cases where either $\psi_{1}$ or $\psi_{2}$ are pure LTL formulas, $k_{\psi_{1}}$ or $k_{\psi_{2}}$ will respectively be 1 by the induction hypothesis, and the claim will still hold. In the case where both $\psi_{1},\psi_{2}$ are pure LTL formulas, it means $\psi$ is a pure LTL formula, and the bound here will be $\max(1,1) = 1$, and so the claim will hold. 

    \item For $\psi = \psi_{1} \land \psi_{2}$, starting from configuration $\{(\psi_{1} \land \psi_{2},0)\}$, when both $\psi_{1}$ and $\psi_{2}$ are not pure LTL formulas, $\delta(\psi,a)$ for some $a$ will be $\delta(\psi_{1},a) \land \delta(\psi_{2},a)$. This means any minimal model for it on 0 will need to be models of $\delta(\psi_{1},a)$ and $\delta(\psi_{2},a)$ on 0. This means for any reachbale configuration $\gamma$ from $\{(\psi,0)\}$, $\gamma = \gamma_{1} \cup \gamma_{2}$ where $\gamma_{1}$ and $\gamma_{2}$ are reachable configurations from $\{(\psi_{1},0)\}$ and $\{(\psi_{2},0)\}$ respectively. By induction hypothesis on $\psi_{1},\psi_{2}$, we know that all reachable configurations from $\{(\psi_{1},0)\}$ and $\{(\psi_{2},0)\}$ will have at most $k_{\psi_{1}}$ and $k_{\psi_{2}}$ active states respectively. Hence all reachable configurations from $\{(\psi,0)\}$ will have at most $k_{\psi_{1}} + k_{\psi_{2}}$ active states. We can similarly prove the claim for cases where either $\psi_{1}$ or $\psi_{2}$ is a pure LTL formula. Now, if both $\psi_{1},\psi_{2}$ are pure LTL formulas, $\psi$ is itself a pure LTL formula. Here, $\delta(\psi,a) = \inact{x}.\delta(\psi_{1},a) \land \inact{x}.\delta(\psi_{2},a)$. Because any minimal model of $\delta(\psi_{1},a),\delta(\psi_{2},a)$ on $0$ will have at most 1 active variable by induction hypothesis, any minimal model of $\delta(\psi,a)$ will have no active variable, meaning any configuration $\gamma$ that is a successor of the configuration $\{(\psi_{1} \land \psi_{2},0)\}$ will have no active variables, and so the reachable configurations have at most 1 active variable, and the claim holds. 

    \item For $\psi = \X_{I} \psi'$, starting from configuration $\{(\X_{I} \psi',0)\}$, $\delta(\psi,a)$ for some $a$ will be $\inact{x}.(\X_{I}\psi')^r$ or $x.(\X_{I}\psi')^r$. Thus the successor configuration will be $\{((X_{I}\psi')^r,\bot)\}$ or $\{((\X_{I}\psi')^r,0)\}$. From there, as $\delta((\X_{I}\psi')^r,a)$ for some $a$ will be either $I \land \inact{x}.\delta(\psi',a)$ or $I \land x.\delta(\psi',a)$, the next configuration will either be a minimal model of $\delta(\psi',a)$ for either $0$ or $\bot$, or will be $\emptyset$, and so the configurations that follow will be reachbale from $\{(\psi',0)\}$ too. Now, by induction hypothesis on $\psi'$, we know that all reachable configurations from $\{(\psi',0)\}$ will have at most $k_{\psi'}$ active states. Hence all reachable configurations from $\{(\psi,0)\}$ will have at most $k_{\psi'}$ active states. In the case where $\psi$ is a pure LTL formula, $\psi'$ will also be a pure LTL formula, and so all reachable configurations from $\{(\psi,0)\}$ will have at most 1 active state.

    \item For $\psi = \psi_{1} \U_{I} \psi_{2}$, starting from configuration $\{((\psi_{1} \U_{I} \psi_{2}),0)\}$, when $\psi_{2}$ is not a pure LTL formula, $\delta(\psi,a)$ for some $a$ will be $(x.\delta(\psi_{2},a) \land I) \lor (\inact{x}.\delta(\psi_{1},a) \land (\psi_{1} \U_{I} \psi_{2}))$, and so any minimal model for $\delta(\psi,a)$ on $0$ will be either a minimal model of $\delta(\psi_{2},a)$ on 0 or some $\gamma = ((\psi_{1} \U_{I} \psi_{2}),v) \cup \gamma_{1}$ where $\gamma_{1}$ is a minimal model of $\delta(\psi_{1},a)$ on $\bot$. By induction hypothesis on $\psi_{1},\psi_{2}$, we know that all reachable configurations from $\{(\psi_{1},0)\}$ and $\{(\psi_{2},0)\}$ will have at most $1$ and $k_{\psi_{2}}$ active states respectively. This means if the successor cofiguration is the former, the successors from that configuration will have at most $k_{\psi_{2}}$ active states. If the successor configuration is the latter, i.e. of the form $\gamma$, we see that because minimal models of $\delta(\psi_{1},a)$ will have at most 1 active state, $\gamma_{1}$ will have no active state, and so the successors of $\gamma$ will have at most 1 active state. Hence all reachable configurations of $\{(\psi,0)\}$ will have at most $k_{\psi_{2}}$ active variables. In the case when $\psi_{2}$ is a pure LTL formula, $\delta(\psi,a)$ will be $(\inact{x}.\delta(\psi_{2},a) \land I) \lor (\inact{x}.\delta(\psi_{1},a) \land (\psi_{1} \U_{I} \psi_{2}))$, and so the successor configurations will have either no active variables, or at most 1 active variable, and so all reachable configurations will have at most 1 active variable.

\end{itemize}
Now, For $\Aa'_{\varphi}$, we see that from the initial configuration $\{(\varphi_{init},0)\}$, $\delta(\varphi_{init},a)$ for some $a$ will be either $\inact{x}.\delta(\varphi,a)$ if $\varphi$ is a pure LTL formula, or $x.\delta(\varphi,a)$ otherwise. In the former case, because any minimal model of $\delta(\varphi,a)$ on 0 will have at most 1 active state by our claim, we see that any successor configuration from $\{(\varphi_{init},0)\}$ will have no active states, and so all reachable configurations of $\Aa'_{\varphi}$ will have at most 1 active state. In the case where $\varphi$ is not a pure LTL formula, any minimal model of $\delta(\varphi,a)$ on 0 will have at most $k_{\varphi}$ active states, so any reachable configuration in $\Aa'_{\varphi}$ will have at most $k_{\varphi}$ active states.  
\end{proof}
