\end{center}
\caption{
 Illustration to Lemma~\ref{lem:mCVD-subdivisions}
 for unbounded faces of $\mCVD_k(S)$
 with the same set~$S=\{s_1,\ldots, s_9\}$ of colored points as in
 \figurename s~\ref{fig:cvd} and~\ref{fig:mcvd} under the Euclidean metric.
 The shaded regions in (a)--(c) depict a face~$f\subseteq \VR_1(H; S)$ of~$\mCVD_1(S)$ 
 where $H$ consists of a single color (for the red points).
 In this case, $S_f = \{s_3, s_4, s_6, s_7\}$,
 while an additional site~$s_8$ defines an unbounded face in~$\mCVD^*_2(S) \cap f$.
 So, $\Sfplus \setminus S_f = \{s_8\}$ and 
 $\mCVD^*_2(S) \cap f = \FVD(S_f \cup \Sfplus) \cap f$.
 }
