\begin{lemma}
  \label{lem:mCVD-subdivisions} 
  Let $f\subseteq \mVR_k(H;S)$ be a face of $\mCVD_k(S)$ for $1\leq
  k\leq m-1$.
  Let $\Sfplus\subseteq S\setminus S_H$ be the set of sites
  that define unbounded faces in  $\mCVD_{k+1}(S)\cap f$\changed{; if
    $f$ is bounded, $\Sfplus=\emptyset$.}
  The following hold:

  \begin{enumerate}[(i)] 
  \item
    $\mCVD_1(S_f\cup \Sfplus) \cap f =  \mCVD_{k+1}(S) \cap f$
    and $\FVD(S_f \cup \Sfplus) \cap f =  \mCVD^*_{k+1}(S) \cap f$.
  \item $\HVD(S_H) \cap f = \mCVD_{k-1}(S) \cap f$ and
    $\HVD^*(S_H) \cap f = \mCVD^*_{k}(S) \cap f$.
  \end{enumerate}
\end{lemma}
\begin{proof}
  Analogously to Lemma~\ref{lem:CVD-subdivisions}, $S_f\subseteq S\setminus S_H$ and 
  $\mCVD^*_{k+1}(S) \cap f= \FVD(S\setminus S_H)\cap f$, where
  $f\subseteq \mVR_k(H;S)$ is a face of $\mCVD_k(S)$.
  \changed{
  Further, $\FVD(S\setminus S_H)$ has only unbounded regions, 
  thus a face of $\FVD(S\setminus S_H)$ may be
  enclosed in $f$ only if it is unbounded in the same
  directions as~$f$.}
  In addition, only sites in~$S_f$ can have a region \added{in $\FVD(S\setminus S_H)$} that
  intersects the boundary of~$f$.
  The unbounded
  edges of $\mCVD^*_{k+1}(S) \cap f$ are clearly all new, by the
  definition of an unbounded face~$f$.
  Thus, $\FVD(S\setminus S_H)\cap f=\FVD(S_f \cup \Sfplus) \cap f$, 
  where $\Sfplus=\emptyset$ if $f$ is
  bounded; hence claim~(i) follows.
  See \figurename~\ref{fig:Sfplus}.

  Claim~(ii) is analogous to Lemma~\ref{lem:CVD-subdivisions}(ii).
  Since $f\subseteq \mVR_k(H; S)$, 
  it holds that $\mCVD_{k-1}(S)\cap f=\mCVD_{k-1}(S_H)\cap f$ 
  and $\mCVD_{k}^*(S)\cap f=\mCVD_{k}^*(S_H)\cap f$.
  Since $\HVD(S_H) = \mCVD_{k-1}(S_H)$ 
  and $\HVD^*(S_H) = \mCVD_{k}^*(S_H)$, 
  the claim follows.
\end{proof}

To iteratively compute $\mCVD_{k+1}(S)$, \changed{given  $\mCVD_{k}(S)$,} we first need
to identify \changed{the}
sites that define the new unbounded edges of
$\mCVD_{k+1}(S)$.
This information, however,  is not encoded in $\mCVD_{k}(S)$, unlike \added{the
  minimal diagrams}.
We give a condition, related to condition~\textbf{V3}, 
under which we can use $\CVD^*_{k+1}(S)$ to derive the information missing
from  $\mCVD^*_{k+1}(S)$.
This condition is satisfied
if, for example, $S$ is a set of points and $\delta_s$ for $s\in S$
is \changed{a}
convex distance based on a smooth body.

\begin{itemize}
\item[\textbf{V3$^\prime$}]
The unbounded faces of $\VD(S')$ and $\FVD(S')$ are defined by the
same sequence  of sites, for any~$S'\subseteq S$.
\end{itemize}

\begin{lemma}
	\label{lem:V3-prime} 
	Condition \textbf{V3$^\prime$} implies that the unbounded faces of
	$\CVD^*_{k}(S)$ and of $\mCVD^*_{k}(S)$ are defined by the same
	sequence of sites for any $1\leq k\leq m$. (See \figurename~\ref{fig:condition_V3prime}.)
\end{lemma}

\begin{proof}
  We perform induction on the order~$k$.
  The base case for~$k=1$ holds by condition~\textbf{V3$^\prime$}.
 Suppose that the claim holds for a given~$k$ with~$1\leq k< m$. 
 Then for any two consecutive unbounded edges of $\CVD_{k}(S)$ 
 that delimit a face $f\subseteq \VR_k(H;S)$, $|H|=k$, 
 there is a corresponding face $f'\subseteq \mVR_k(H';S)$, $|H'|=k$, 
 in $\mCVD_{k}(S)$, delimited by unbounded
 edges defined by the same pairs of sites.
 To prove the lemma,
 we strengthen the induction hypothesis by further assuming that $H=H'$. 
 The extended hypothesis clearly holds for~$k=1$.


\begin{figure}[h]
\begin{center}
\includegraphics[width=\textwidth]{figs/fig_condition_V3prime}
\end{center}
\caption{
  Illustration \changed{of}
  condition~\textbf{V3$^\prime$} and Lemma~\ref{lem:V3-prime}
 with the same set~$S=\{s_1,\ldots, s_9\}$ as in~\figurename s~\ref{fig:cvd}--\ref{fig:mcvd} 
 under the Euclidean metric.
 In (a)(b), $\VD(S')$ and $\FVD(S')$
 have the same sequence of sites that define unbounded faces for any~$S'\subseteq S$,
 so condition~\textbf{V3$^\prime$} holds.
 The shaded region in~(a) is a face~$f$ of $\CVD_1(S)$
 corresponding to face~$f'$ of $\mCVD_1(S)$ shaded in~(b).
 In (c)(d), shaded regions show how the portions of $f$ and $f'$ at infinity
 are subdivided in $\CVD^*_2(S)$ and $\mCVD^*_2(S)$.
 }
\label{fig:condition_V3prime}
\end{figure}

By Lemma~\ref{lem:CVD-subdivisions}(i), we have
 $\CVD^*_{k+1}(S) \cap f=\VD(S\setminus S_H) \cap f=\VD(S_f) \cap f$.
 Analogously, by Lemma~\ref{lem:mCVD-subdivisions}(i),
 $\mCVD^*_{k+1}(S) \cap f'=\FVD(S\setminus S_H) \cap f'=\FVD(S_{f'}\cup\Sfplusm)\cap f'$.
 Since the unbounded edges delimiting $f$ and $f'$ are corresponding,
 the inductive hypothesis and condition~\textbf{V3$^\prime$} imply that 
 the sequence of sites  that define the
 unbounded faces of $\VD(S\setminus S_H)\cap f$ and 
 of $\FVD(S\setminus S_H) \cap f'$ coincide.
 Thus the claim follows for $\CVD^*_{k+1}(S) \cap f$ and
 $\mCVD^*_{k+1}(S) \cap f'$.
 Since our choice of~$f$ is arbitrary, 
 the claim holds for $\CVD^*_{k+1}(S)$ and $\mCVD^*_{k+1}(S)$.
 See \figurename~\ref{fig:condition_V3prime}.

 It remains to show that the extended hypothesis continues to hold. 
 Consider an unbounded face~$f_1$ of $\VD(S\setminus S_H)\cap f$ 
 that is incident to a new unbounded edge~$e$ of $\CVD^*_{k+1}(S) \cap f$. 
 Then $f_1\subseteq \VR_{k+1}(H_1;S)$, 
 where $H_1$ consists of those colors in~$H$ and 
 the color of the site that defines~$e$ from the side of~$f_1$.
 Face~$f_1$ corresponds to a face~$f_1'$
 of $\FVD(S\setminus S_H)\cap f'$, 
 which is incident to the unbounded edge~$e'$ corresponding to~$e$.
 Thus, $f_2\subseteq \mVR_{k+1}(H_2;S)$, 
 where $H_2$ consists of those colors in~$H$
 and the color of the site that defines~$e'$ on the side of~$f_2$,
 which is the same as the site that defines~$e$. 
 Thus, we have $H_2=H_1$ and
 the extended hypothesis holds for order~$k+1$ as well.
\end{proof}

Now, we assume that \changed{the sites~$S$ and their distance functions~$\delta_s$}
fall under the model
of \emph{abstract Voronoi diagrams}~\cite{k-cavd-89}.
Specifically, together with the general position assumption described
in Section~\ref{sec:cvda},
we also assume the following, for every subset $S' \subseteq S$:
\begin{itemize}
\item The regions of~$\VD(S')$ are nonempty and connected.
\item The bisector of any two sites is an unbounded simple curve homeomorphic to a
  line.
\end{itemize}
Furthermore, we assume that \changed{any distance or bisector}
can be computed in $O(1)$ time.
We then conclude the following.



\begin{theorem} \label{thm:alg} 
 Let $S$ and $\{\delta_s\}_{s\in S}$ 
 be a
 set of $n$~colored sites with $m$~colors and distance functions
 that satisfy the conditions of abstract Voronoi diagrams.
 Then, for~$1\leq k \leq m$,
 in $O(k^2n + n\log n)$ expected time or in $O(k^2n \log n)$ worst-case time,
 we can compute
 $\CVD^*_1(S), \ldots, \CVD^*_k(S)$.
 If in addition condition~\textbf{V3$^\prime$} holds, then 
 we can also compute
 $\mCVD^*_1(S), \ldots, \mCVD^*_k(S)$
 in the same time bound.
 If $S$ consists of points and $\delta_s(x)$ is the Euclidean distance to~$s\in S$, 
 the time bound is reduced to $O(k^2n + n\log n)$ in the worst case.
\end{theorem}
\begin{proof}
  Let $i$ be an integer with $1\leq i\leq k-1$.
  Consider a face~$f$ of $\CVD_i(S)$ that belongs to an order-$i$
  Voronoi region $\VR_i(H; S)$, for a set~$H$ of $i$~colors.
  Recall the sets~$S_H$ and~$S_f$ as defined above, where $S_f\cap S_H = \emptyset$
  \added{by Lemma~\ref{obs:no-color-in-H}.}

  By Lemma~\ref{lem:CVD-subdivisions}, the Voronoi diagram $\VD(S_f)$,
  truncated within $f$, reveals exactly the order-$(i+1)$ subdivision
  within the face~$f$, $\CVD^*_{i+1}(S)\cap f$.
  Since $\VD(S_f)$ is an instance of abstract Voronoi diagrams, we can
  compute  $\CVD^*_{i+1}(S)\cap f$ in expected $O(|S_f|)$~time by
  the randomized incremental technique of~\cite{P23},
  or in worst-case $O(|S_f|\log |S_f|)$ time by standard means, see e.g., \cite{alk-vddt-13}. 
  If $S$ consists of points in~$\Plane$ and $\delta_s(x) = \|x-s\|_2$ 
  is the Euclidean distance to each $s\in S$,
  then
  $\CVD^*_{i+1}(S)\cap f$ can be computed in $O(|S_f|)$ worst-case time~\cite{agss-ltacvdcp-89}.

  Then $\CVD_{i+1}(S)\cap f$ can be derived in two steps.
  First delete any $1$-chromatic edges of $\VD(S_f)$ and 
  unify the faces incident to the deleted edges. 
  This yields the overlay of $\CVD_{i}(S)$ and $\CVD_{i+1}(S)\cap f$, 
  which is  $\CVD^*_{i+1}(S)\cap f$ with its $1$-chromatic edges removed.
  Then, remove the edges along the  boundary of~$f$, 
  while unifying their incident faces, 
  which belong to the same set of $i+1$~colors.
  Note that for each edge~$e$ removed, the two incident faces get unified 
  into a new face~$f'(e)$ of $\CVD_{i+1}(S)$, 
  which belongs to a set~$H'$ of $i+1$~colors;
  the removed edge~$e$ belongs to $\FCVD(S_{H'})\cap f'(e)$.

  To obtain the entire $\CVD^*_{i+1}(S)$, we repeat the
  process for every face~$f$ of~$\CVD_{i}(S)$.
  \changed{
  As discussed in Corollary~\ref{coro:kcvd_AVD},
  conditions~\textbf{V1} and~\textbf{V2} hold, thus,  $\sum_{f} |S_f|
  = O(in)$.
  Hence, for computing~$\CVD^*_{i+1}(S)$ given $\CVD^*_i(S)$,
  we spend $O(in)$ expected or $O(in \log n)$ worst-case time,
}
 plus time proportional to the combinatorial complexity of $\CVD^*_{i+1}(S)$,
  which is $O((i+1)n)$ by Theorem~\ref{thm:kcvd_general} and Corollary~\ref{coro:kcvd_AVD}.
  Therefore, the total time complexity of our algorithm is bounded as claimed.



  Assuming condition~\textbf{V3}$^\prime$, 
  we can compute $\mCVD^*_{i+1}(S)$ and $\mCVD_{i+1}(S)$ analogously,
  however, given both $\mCVD_{i}(S)$ and $\CVD_{i}(S)$.
  We first compute $\CVD^*_{i+1}(S)$ from $\CVD_{i}(S)$ 
  in order to extract the sequence of sites 
  that define the unbounded faces of $\CVD^*_{i+1}(S)$, 
  which by Lemma~\ref{lem:V3-prime} coincides with 
  the sequence of sites that define the unbounded faces of  $\mCVD^*_{i+1}(S)$.
  In particular, for each pair of unbounded edges 
  that delimit an unbounded face~$f$ in $\mCVD_{i}(S)$,
  we identify the corresponding pair of unbounded edges in $\CVD_{i}(S)$; 
  then we traverse the unbounded edges of $\CVD^*_{i+1}(S)$ 
  that lie between them, and transform them to the sequence $\Jfplus$ of sites 
  that define the unbounded edges of $\mCVD_{i}(S)\cap f$.
  Once $\Jfplus$ and $\Sfplus$ are identified, 
  for every unbounded face of $\mCVD_{i}(S)$, 
  the computation of $\mCVD^*_{i+1}(S)$ and $\mCVD_{i+1}(S)$ is analogous: 
  for each face~$f$, we compute the farthest-site Voronoi diagram 
  $\FVD(S_f\cup S_{f}^+)\cap f$, 
  where $S_{f}^+ =\emptyset$ if $f$ is bounded.
  Given the boundary of~$f$ and the ordering of~$\Jfplus$, 
  this can be done in expected linear time by applying
  the randomized incremental construction of~\cite{JP23,P23}.
  (Note that we can easily compute $\FVD(S_f\cup \Sfplus)\cap \partial f$,  
  from $\Jfplus$, in linear time, 
  where  $\partial f$ denotes the boundary of~$f$, 
  as obtained by superimposing~$f$ and a large-enough bounding circle; 
  we can then apply~\cite{JP23,P23}).
  For points in the Euclidean metric,  
  $\FVD(S_f\cup S_{f}^+)\cap f$ can be computed in deterministic
  linear time~\cite{agss-ltacvdcp-89}, 
  given the sequence of sites that appear along the boundary of~$f$.
  Alternatively, we can also compute $\FVD(S_f\cup S_{f}^+)$ 
  in $O(|S_f \cup S_{f}^+| \log |S_f \cup S_{f}^+|)$ time 
  by standard techniques~\cite{alk-vddt-13}.  
  Since condition~\textbf{V3}$^\prime$ implies condition~\textbf{V3},
  the complexity of~$\mCVD^*_i(S)$ is also bounded by $O(i(n-i))$
  by Theorem~\ref{thm:kcvd_general_2n-4} and Lemma~\ref{lem:CVD_v}.
  The claimed time bounds are thus derived.
\end{proof}



The convex distance functions satisfy the conditions of Theorem~\ref{thm:alg},
hence we have:
\begin{corollary} \label{cor:alg} 
Let $B$ be a convex and compact body in~$\Plane$ of a constant complexity
that contains the origin in its interior.
Given a set~$S$ of $n$~colored points in~$\Plane$ with $m$~colors and
an integer $1\leq k\leq m$,
we can compute
$\CVD^*_1(S), \ldots, \CVD^*_k(S)$
in $O(k^2n + n\log n)$ expected time or in $O(k^2n \log n)$ worst-case time.
If $B$ is smooth, then we can also compute 
$\mCVD^*_1(S), \ldots, \mCVD^*_k(S)$ in the same time bound.
\end{corollary}
\begin{proof}
As discussed in Section~\ref{sec:kcvd_general} this case
falls under the \changed{umbrella} of abstract Voronoi diagrams; 
furthermore, if $B$ is smooth,
condition~\textbf{V3$^\prime$} holds, 
as shown in Lemma~\ref{lem:V3-convex_distance} and its proof.
Therefore, Theorem~\ref{thm:alg} applies and the corollary follows.
\end{proof}




\begin{corollary}\label{coro:kcvd_not_smooth}
Let $B$ be a convex $2b$-gon, centrally symmetric around the origin,
where $b\geq 2$ is a constant.
Given a set~$S$ of $n$~colored points with $m$~colors
in~$\Plane$,  and an integer $1\leq k\leq m$, we can
compute $\CVD^*_1(S), \ldots, \CVD^*_k(S)$ in 
$O(k^2 (n-k) + n\log n)$
expected or 
$O(k^2 (n-k) \log n + n \log n)$
worst-case time.
We can then compute $\mCVD^*_1(S), \ldots, \mCVD^*_k(S)$ in additional
$O(k^3 + n)$ worst-case time.
\end{corollary}


\begin{proof}
  By Corollary~\ref{coro:kcvd_convex_polygonal}, the complexity of
  $\CVD_i$ under this metric is $ O(\min\{i(n-i),
  (n-i)^2\})$, where $1\leq i\leq k$. Following the proof of
  Theorem~\ref{thm:alg} and summing up over $ 1\leq i \leq k$, the 
  the claimed bounds regarding the minimal diagrams can be derived.
  However, some care is required with respect to the general position
  assumption and the specifics of the $2b$-gon metric.

  Let $\mathcal{N}(B)$ be the set of directions normal
  to the sides of $B$ pointing outwards; and let $\mathcal{D}(B)$ be the
  set of directions along the diagonals of $B$, see
  Figure~\ref{fig:directions}.
  The $2b$-gon ($b=2$) bisector of two points in general position is illustrated in
  Figure~\ref{fig:subdivision}.
  If the points are collinear along  a line normal to a direction in $\mathcal{N}(B)$, then their bisector contains 
  2-dimensional regions, which are not allowed by the general position
  assumption, see 
  Figure~\ref{fig:subdivision}(b).
  Following standard conventions, we can transform any such bisector 
  to a simple curve, by assigning an equidistant area to only one of
  the sites and keeping only the boundary curve as the bisector, see
  Figure~\ref{fig:subdivision}(c).
  Following this convention consistently, e.g., always choosing the
  ``clockwise most'' boundary of the equidistant area to be part of the bisector,
  the bisector system
  complies with the assumptions and the algorithms in the proof
  of Theorem~\ref{thm:alg} can be used.
  We adopt this convention in the rest of this proof.


  \begin{figure}[ht]
    \centering
    \includegraphics[height=3cm]{figs/L_inf_N_B__D_B}
    \caption{The directions in $\mathcal{N}(B)$ and $\mathcal{D}(B)$ for the $L_\infty$ metric ($b = 2$).}
    \label{fig:directions}
  \end{figure}


  Consider the diagrams $\VD(S)$ and  $\FVD(S)$ under the $2b$-gon
  metric; they both have unbounded faces in each
  of the directions of 
  $\mathcal{N}(B)$ defined by the minimum enclosing $2b$-gon of $S$.
  Furthermore, assuming that we consistently follow the same
  tie-breaking convention,
  the point
  that defines the face of $\VD(S)$ unbounded in direction $\vec{v}\in
  \mathcal{N}(B)$, and the point that defines the face of $\FVD(S)$ unbounded in direction
   $-\vec{v}$, coincide.
  The $\VD(S)$ can have multiple faces unbounded in the directions of
  $\mathcal{D}(B)$, whereas the complexity of $\FVD(S)$ is constant $O(b)$.
  We can use the directions of $\mathcal{N}(B)$ to further refine the faces of $\VD(S)$ and
  $\FVD(S)$,  see Figure~\ref{fig:subdivision}, and therefore also the faces of  $\CVD^*_k(S)$ and
  $\mCVD^*_k(S)$.
  The following property holds.

\begin{figure}[ht]
  \centering
  \includegraphics[height=3.5cm]{figs/L_inf_subdivision}
  \caption{The $L_\infty$ Voronoi diagram of two points; their bisector
    is indicated in  solid lines;  (a) points in general position;
    (b) vertically collinear points, the shaded areas are equidistant from both points;
    (c) vertically collinear points under the adopted convention.
    }
  \label{fig:subdivision}
\end{figure}

\begin{lemma} \label{lem:extremal-points-Linf}
  The face of $\CVD^*_k(S)$ unbounded in direction
  $\vec{v}\in \mathcal{N}(B)$ and the face of $\mCVD^*_k (S)$
  unbounded in  direction $-\vec{v}$
  are associated with the same site $p\in S$ assuming the same tie-breaking conventions in both diagrams.
\end{lemma}

\begin{proof}
  Let $f\subseteq\VR_k(H;S)$ be the face of $\CVD^*_k(S)$ unbounded in 
  direction $\vec{v} \in \mathcal{N}(B)$ and let $p\in S_c$, where
  $c\in H$, be the
  point associated with $f$.
  That is, color $c \in H$ is the $k$-th
  nearest color from all points in  $f$,
  and $p$ is the nearest point of $S_c$ to all points in $f$,
  since $\CVD^*_{k}(S) \cap f=\FCVD^*(S_H) \cap f$, by Lemma~\ref{lem:CVD-subdivisions}(ii),
  and $f$ is already a fine face of $\CVD^*_{k}(S)$.
  The line $\ell$ through $p$ orthogonal to $\vec{v}$
  defines two open half-planes $h^+$ and $h^-$, unbounded in directions
  $\vec{v}$ and $-\vec{v}$, respectively, such that $h^+$
  contains at least one point of
  each color in $H\setminus\{c\}$  and no point of any other color,
  and the closure of $h^-$ entirely contains
  $S_c$ and $S\setminus S_H$.
  In case multiple points in $(S\setminus S_H)\cup S_c$ are collinear along
  $\ell$, the adopted tie-breaking convention indicates that $p$
  is the bottommost such point along $\ell$, where $\ell$ is oriented so
  that $h^+$ lies to its left.

  Consider the face $f'$ of  $\mCVD^*_k(S)$,  $f'\subseteq\mVR_k(H';S)$, unbounded in 
  direction $-\vec{v}$, and let $q$ be the point associated with $f'$.
  The line through $q$ orthogonal to $-\vec{v}$ defines two 
  half-planes that have exactly the same properties as $h^-$ and
  $h^+$.
  Thus, $H'=H$, and $p,q$  both lie on  $\ell$. 
  By the adopted tie breaking convention, $q$ must be extreme
  along $\ell$,  similarly to $p$, therefore $p$ and $q$ must coincide. 


  \begin{figure}[ht]
    \centering
    \includegraphics[height=4cm]{figs/extremal_points}
    \caption{Illustration to Lemma~\ref{lem:extremal-points-Linf} for
      the $L_\infty$ metric. The faces $f\subseteq\VR_k(H;S)$ and 
      $f'\subseteq\mVR_k(H';S)$ are shown in red, region
      boundaries in solid black. In this case $k = 2$, the colors in $H$ are red and blue, the $k$-th color $c$ is red, and $p = q$.}
    \label{fig:extremal-points}
  \end{figure}  
\end{proof}


Let $f$ be a face of $\mCVD^*_{i}(S)$ unbounded in direction
$\vec{v}$.  By Lemma~\ref{lem:extremal-points-Linf}, we can compute
$\Sfplus$ by locating  in $\CVD^*_{i+1}(S)$ the face  $f'$ that is
unbounded in direction $-\vec{v}$, and assigning its associated
point as $\Sfplus$. Then $\FVD(S_f \cup \Sfplus) \cap f$ 
can be computed in $O(|S_f|)$ time, as the complexity of $\FVD(S_f\cup \Sfplus)$ is  constant.
Thus, we can derive $\mCVD_{i+1}(S)$, given $\mCVD_{i}(S)$ and $\CVD^*_{i+1}(S)$,  in time proportional to the
complexity of $\mCVD_{i}(S)$, which is $O(\min\{i(n-i), i^2\})$ by
Corollary~\ref{coro:kcvd_convex_polygonal}.
Summing up for $i=1$ to $k$,  we derive $O\left( \sum_{i=1}^k \min\{i(n-i),
i^2\} \right)= O(k^3)$
plus $O(n)$ time to compute $\mCVD^*_1(S)$.
This is in addition to the  time required  to compute
$\CVD^*_{i+1}(S)$, which has already been stated above.
\end{proof}



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{More Applications of the Colorful Clarkson--Shor Framework} \label{sec:appl_CS}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The colorful Clarkson--Shor framework, as described in Section~\ref{sec:framework},
provides a general scheme to transform any set system that fits in
the original framework to its colored variant.
Once one has an upper bound on the number of (uncolored) configurations,
Theorems~\ref{thm:CS_general} and~\ref{thm:CS_general_uniform}
automatically imply general upper bounds on
the number of colored configurations of weight at most $k$.
In this section,
we demonstrate selected applications of the colorful Clarkson--Shor framework,
which result in new or, sometimes, known bounds 
on levels of arrangements of various objects of non-constant complexity.


\subsection{Envelopes of hyperplanes} \label{subsec:envelopes_hyperplanes}
We start with the arrangement of envelopes of hyperplanes in~$\Real^d$
for a constant $d\geq 2$.
Specifically,
let $S$ be a set of $n$~non-vertical hyperplanes in~$\Real^d$
and $\kappa \colon S \to K =\{1,\ldots, m\}$ be any color assignment.
For $i\in K$,
let $E_i$ be the lower envelope of \changed{the hyperplanes in~$S_i$}
and $\overline{E}_i$ \changed{be} their upper envelope.
We consider the arrangement $\arr = \arr(\{E_1, \ldots, E_m\})$ 
of $m$ lower envelopes
and the arrangement~$\overline{\arr} = \arr(\{\overline{E}_1, \ldots, \overline{E}_m\})$
of $m$ upper envelopes.
Our question is:
how many vertices are there in the arrangements~$\arr$ and $\overline{\arr}$ or 
in their levels?

We interpret this as an instance of the colorful Clarkson--Shor framework.
Let $\conf(S)$ be
the set of vertices of the arrangement $\arr(S)$ of \changed{the} $n$ hyperplanes in~$S$.
Let $\chi \subseteq S \times \conf(S)$
be a conflict relation such that $(s, v) \in \chi$ if and only if
$v\in \conf(S)$ lies \emph{above}~$s\in S$.
We also consider another relation $\bar{\chi} \subseteq S \times \conf(S)$
such that $(s, v) \in \chi$ if and only if
$v\in \conf(S)$ lies \emph{below}~$s\in S$.
This describes two symmetric (uncolored) CS-structures
$(S, \conf(S), \chi)$ and $(S, \conf(S), \bar{\chi})$.
Now, consider the colored configurations with respect to~$\kappa$
induced from $(S, \conf(S), \chi)$ and $(S, \conf(S), \bar{\chi})$,
denoted by $\conf(S,\kappa)$ and $\overline{\conf}(S,\kappa)$, respectively.
It then turns out that $\conf(S,\kappa)$
consists of the vertices of the arrangement~$\arr$ of $m$ lower envelopes,
while $\overline{\conf}(S,\kappa)$ consists of
the vertices of the arrangement~$\overline{\arr}$ of $m$ upper envelopes.
More precisely, for $1\leq c\leq d$ and $0\leq j\leq m-1$,
the set~$\conf_{c,j}(S,\kappa)$
consists of $c$-chromatic vertices of~$\arr$
below which there are exactly $j$~surfaces from~$\{E_i\}_{i\in K}$,
while $\overline{\conf}_{c,j}(S,\kappa)$ consists of
$c$-chromatic vertices of~$\overline{\arr}$
above which there are exactly $j$~surfaces from~$\{\overline{E}_i\}_{i\in K}$.

We then consider the standard point-to-hyperplane duality transformation~\cite{e-acg-87}
such that each point~$p = (a_1, a_2, \ldots, a_d) \in \Real^d$
is mapped to a non-vertical \changed{hyperplane~$\dual{p} \colon \{x_d = a_1 x_1 + \cdots + a_{d-1} x_{d-1} - a_d\}$},
and vice versa.
Letting $\dual{S}$ be the set of $n$~points in~$\Real^d$
that are dual to hyperplanes in~$S$,
a $c$-chromatic vertex of weight~$j$ of $\arr$ or of $\overline{\arr}$
(which belongs to $\conf_{c,j}(S)$ or $\overline{\conf}_{c,j}(S)$, respectively)
corresponds to a $c$-chromatic $j$-facet in~$\dual{S}$.
More precisely,
by the duality transformation,
there is a one-to-one correspondence between
$\conf_{c,j}(S)$ and the set of $c$-chromatic $j$-facets in~$\dual{S}$ that are \emph{upward},
(that is, those $j$-facets whose corresponding half-spaces are unbounded 
in the positive $x_d$-direction);
analogously,
there is a one-to-one correspondence between
$\overline{\conf}_{c,j}(S)$ and the of $c$-chromatic $j$-facets in~$\dual{S}$ that are \emph{downward}.
Hence, we have:
\begin{lemma} \label{lem:v-e_2}
For each $1\leq c\leq d$ and $0\leq j\leq m-c$, it holds that
\[ |\conf_{c,j}(S,\kappa)| + |\overline{\conf}_{c,j}(S)| = e_{c,j}(\dual{S}).\]
\end{lemma}

By Lemma~\ref{lem:v-e_2}, Corollary~\ref{coro:j-facets_general} implies:
\begin{corollary} \label{coro:levels_hyperplanes}
 The number of vertices in the $(\leq k)$-level of the arrangement of
 $m$ convex polyhedral hypersurfaces in~$\Real^d$ with a total of $n$ facets,
 each of which is the lower envelope of non-vertical hyperplanes, is
 $O(m^{\lfloor d/2 \rfloor -1} k^{\lceil d/2 \rceil} n^{\lfloor d/2 \rfloor})$
 in general
 and
 $O(k^{\lceil d/2 \rceil} n^{\lfloor d/2 \rfloor})$
 if the numbers of facets in
 each of the $m$ convex hypersurface is at most $\rho\cdot \frac{n}{m}$
 for a constant~$\rho\geq 1$.
\end{corollary}
Corollary~\ref{coro:levels_hyperplanes} is in fact
the dual version of Corollary~\ref{coro:j-facets_general}.
Note that for large $k$ with $k \geq \lfloor \frac{m}{d} \rfloor$,
the bounds in both corollaries becomes asymptotically the same as
the total number of $(\leq c)$-chromatic configurations,
$O(m^{d-1} n^{\lfloor d/2 \rfloor})$ and $O(n^{\lfloor d/2 \rfloor})$, respectively.
(see Theorems~\ref{thm:CS_general} and~\ref{thm:CS_general_uniform}).
Remark that the bounds in both corollaries for $d\leq 3$
match the original Clarkson--Shor bound
$O(k^{\lceil d/2 \rceil} n^{\lfloor d/2 \rfloor})$~\cite{cs-arscgII-89},
while the extra factor~$m^{\lfloor d/2 \rfloor -1}$ in higher dimensions~$d\geq 4$
is a bit disappointing.
Indeed, Aronov, Bern, and Eppstein have proved
that the total complexity of~$\arr$ is bounded by
$O(m^{\lceil d/2 \rceil} n^{\lfloor d/2 \rfloor})$,
but their unpublished manuscript~\cite{abe-apa-95} currently seems to be lost~\cite{a-pc-24}.
Katoh and Tokuyama~\cite{kt-klcs-02} have proved the bound of $O(k^{2/3}n^2)$ 
on the single $k$-level in~$\Real^3$.

The set~$S$ of hyperplanes in~$\Real^d$ is called in \emph{convex position}
if the set~$\dual{S}$ of dual points is in convex position.
By the duality and Lemma~\ref{lem:v-e_2},
when $S$ consists of planes in~$\Real^3$ in convex and general position,
Theorem~\ref{thm:j-facets_convex_3d} implies an exact upper bound
on the total number of vertices of the $k$-level of~$\arr$ from below
and of the $k$-level of~$\overline{\arr}$ from above.

\begin{corollary} \label{coro:levels_hyperplanes_convex}
 With the notations declared above for~$d=3$,
 suppose $S\subset \Real^3$ is in convex and general position.
 Then, for each~$1\leq k \leq m$,
 the total number of vertices in the $k$-level of~$\arr$ from below and
 in the $k$-level of~$\overline{\arr}$ from above is at most
 \[ \begin{cases}
      2n-4 			& k=1 \\
      6(k-1)(n-k)-4	& 2\leq k \leq m-1 \\
      4(m-1)(n-m+1)-2n	& k=m
    \end{cases}.
  \]
The exact numbers are achieved when $m=n$, that is, 
each $S_i$ consists of a single hyperplane.
\end{corollary}
\begin{proof}
By Lemma~\ref{lem:v-e_2}, the total number of vertices we are interested in is exactly
\[ e_{3,k-1}(\dual{S}) + e_{3,k-2}(\dual{S}) + e_{3,k-3}(\dual{S})
  + e_{2,k-1}(\dual{S}) + e_{2,k-2}(\dual{S}) + e_{1,k-1}(\dual{S})\]
from which Theorem~\ref{thm:j-facets_convex_3d} directly implies
the claimed exact bounds.
\end{proof}

Notice that the $k$-level of the two arrangements~$\arr$ and~$\overline{\arr}$
described in Corollary~\ref{coro:levels_hyperplanes_convex}
corresponds to the refined color Voronoi diagram~$\CVD^*_k(S')$ or $\mCVD^*_k(S')$
under the Euclidean metric of any set $S'$ of colored points
in~$\Plane$ \changed{such that  $\dual{S} = \lift{(S')}$ is 
the set of points in~$\Real^3$ lifted onto the unit parabola.}
(Recall the discussions above and in Section~\ref{sec:framework}.2.)
Thus, the total number of vertices in $\CVD^*_k(S')$ and $\mCVD^*_k(S')$
is bounded by
the exact numbers \changed{given}
in Corollary~\ref{coro:levels_hyperplanes_convex}.


\subsection{Triangles, simplices, and piecewise linear functions}

Let $T = \{\triangle_1, \ldots, \triangle_n\}$ be a given set of $n$~triangles in~$\Real^3$.
For $1\leq k\leq n$,
the \emph{$k$-level} of the arrangement~$\arr(T)$ of triangles in~$T$
is defined to be the closure of the set of all points~$p$ on triangles in~$T$
such that the downward vertical ray from~$p$ meets exactly $k-1$ triangles.
Agarwal et al.~\cite{aacm-lalspt-98} proved that
the complexity of the $k$-level of~$\arr(T)$ is $O(k^{7/9}n^2\alpha(n/k))$
and Katoh and Tokuyama~\cite{kt-klcs-02} improved it to $O(k^{2/3} n^2)$.

To make this fit in our framework, for each $1\leq i\leq n$,
let $S_i$ be the set of four planes in~$\Real^3$
consisting of the plane containing~$\triangle_i\in T$
and three more planes through each side of~$\triangle_i$
that are almost vertical and go below~$\triangle_i$.
Regard each $1\leq i \leq n$ as a color from $K:=\{1,\ldots, n\}$,
and let $S:=\bigcup_{i\in K} S_i$ and $\kappa \colon S \to K$
such that $\kappa(s) = i$ if $s\in S_i$.
As above, let $\overline{E}_i$ be the upper envelope of planes in~$S_i$.
Observe then that the $k$-th level from \emph{below} of the arrangement 
$\overline{\arr} = \arr(\{\overline{E}_1, \ldots, \overline{E}_n\})$
coincides with the $k$-level of $\arr(T)$.
From the definition of~$\overline{\conf}(S, \kappa)$ as declared above,
notice that
the weight of each $c$-chromatic vertex~$v$ of~$\overline{\arr}$ is 
indeed $n-c-k$
if the downward vertical ray from~$v$ intersects exactly $k-1$ triangles in~$T$.
So, the weights and the levels are somehow in the reversed order in this case.

Hence, applying Corollary~\ref{coro:levels_hyperplanes},
we obtain the $O(k^2 n)$ bound for the $(\leq k)$-level from \emph{above} 
or, equivalently, for the $(\geq n-k)$-level from \emph{below} of~$\overline{\arr}$.
On the other hand, we can also obtain an upper bound on the $(\leq k)$-level of
the arrangement~$\arr(T)$ of triangles
by considering those vertices of~$\overline{\arr}$ in~$\overline{\conf}(S,\kappa)$ 
whose weights are at least $n-k$.
Furthermore, the same arguments are applied to
$(d-1)$-simplices in~$\Real^d$ for any constant $d\geq 2$ as follows.
\begin{theorem} \label{thm:levels_triangles}
 Let $T$ be a set of $n$ $(d-1)$-simplices in~$\Real^d$ for constant~$d\geq 2$,
 and $\arr(T)$ be their arrangement.
 For $1\leq k\leq n$,
 the number of vertices in the $(\leq k)$-level of~$\arr(T)$
 is $O(k n^{d-1} \alpha(n/k))$;
 the number of vertices in the $(\geq k)$-level of~$\arr(T)$
 is $O((n-k)^{\lceil d/2 \rceil} n^{\lfloor d/2 \rfloor})$.
\end{theorem}
\begin{proof}
Let us call a vertex of $\arr(T)$ \emph{$c$-chromatic}
if it appears as a $c$-chromatic vertex in~$\overline{\arr}$,
that is, the intersection of three planes from $c$ different sets~$S_i$.
Recall that $\overline{\conf}_{c,j}(S, \kappa)$ be
the set of $c$-chromatic weight-$j$ vertices of $\overline{\arr}$;
we have $v \in \overline{\conf}_{c,j}(S, \kappa)$
if and only if $v$ is a $c$-chromatic vertex of $\arr(T)$ such that
the downward vertical ray emanating from~$v$ intersects exactly $n-c-j$ triangles in~$T$.
Hence, for each $1\leq k\leq n$,
the $c$-chromatic vertices in the $(\leq k)$-level of $\arr(T)$
correspond to the $c$-chromatic colored configurations of weight at least $n-c-k+1$
in this setting.

Now, let $r$ be an integer parameter with $1\leq r\leq n$
and $R\subseteq K=\{1,\ldots, n\}$ be a random subset of $r$~colors.
For each $c \in \{1,2,3\}$,
we have 
 \[ \E[|\overline{\conf}_{c,r-c}(S_R, \kappa_R)|] 
     \geq \sum_{j=0}^{n-c}|\overline{\conf}_{c,j}(S,\kappa)| \binom{j}{r-c} \Big/ \binom{n}{r} \]
by Lemma~\ref{lem:CS_general_lb} (with $a=r-c$), on one hand.
On the other hand,
observe that $\bigcup_{c} \overline{\conf}_{c,r-c}(S_R, \kappa_R)$
consists of all vertices on the \emph{lower envelope} of $r$ upper envelopes
$\{\overline{E}_i\}_{i\in R}$ or, equivalently,
all vertices on the lower envelope of $r$~triangles in~$\{\triangle_i\}_{i\in R}$.
Since the complexity of the lower envelope of $r$~triangles in~$\Real^3$
is known as $O(r^2 \alpha(r))$~\cite{ps-ueplf-89,t-ntasapls-96},
we have 
\[ \E[|\overline{\conf}_{c,r-c}(S_R, \kappa_R)|] \leq 
    \sum_{b=1}^3 \E[|\overline{\conf}_{b,r-b}(S_R, \kappa_R)|] 
     = O(r^2 \alpha(r)),
\]
as $|S_i| = 4$ for every $i\in K$.

Fix $c\in \{2,3\}$ and set $r = \lfloor \frac{n}{k} \rfloor$.
From the above lower bound, 
we then obtain
\begin{align*}
 \E[|\overline{\conf}_{c,r-c}(S_R, \kappa_R)|]
  & \geq \sum_{j=n-c-k+1}^{n-c}|\overline{\conf}_{c,j}(S,\kappa)|\cdot\binom{j}{r-c} \Big/ \binom{n}{r}\\
  & = \sum_{i=0}^{k-1}|\overline{\conf}_{c,n-c-i}(S,\kappa)|\cdot \binom{n-c-i}{r-c} \Big/ \binom{n}{r}\\
  & \geq \left( \sum_{i=0}^{k-1}|\overline{\conf}_{c,n-c-i}(S,\kappa)|\right)
     \cdot \frac{r(r-1)\cdots(r-c+1)}{n(n-1)\cdots(n-c+1)}
     \cdot \left(\frac{c-1}{c}\right)^c
\end{align*}
if $k \leq \lfloor \frac{n}{c} \rfloor$
by the same derivation as in the proof of Theorem~\ref{thm:CS_general}.
Combining this with the above upper bound,
we get
\[ 
 \sum_{j=n-c-k+1}^{n-c}|\overline{\conf}_{c,j}(S,\kappa)| 
   = O\left(k^{c-2}\cdot n^2\cdot \alpha\left(\frac{n}{k}\right)\right)
\]
for $1\leq k \leq \lfloor \frac{m}{c} \rfloor$.
Note that the number of $1$-chromatic vertices in~$\overline{\arr}$ is $O(n)$ in total.
Therefore, the number of vertices in the $(\leq k)$-level of~$\arr(T)$ is bounded by
$O(k n^2 \alpha(n/k))$.
Finally, if $k > \lfloor \frac{n}{c} \rfloor$,
then we verify that $O(k n^2 \alpha(n/k)) = O(n^3)$,
which is asymptotically the same as the maximum possible number of 
vertices in $\overline{\arr}$ and in $\arr(T)$.
Hence, the claimed bound holds for any $1\leq k\leq n$.

The same approach can also be applied to the arrangement of
$(d-1)$-simplices in~$\Real^d$ for any constant $d\geq 2$.
It is known that the complexity of the upper envelope of $r$~simplices in~$\Real^d$
is bounded by $O(r^{d-1}\alpha(r))$~\cite{sa-dsstga-95,e-ueplf:tbnf-89,t-ntasapls-96}.
Hence, the first bound follows.

The second bound is implied by Corollary~\ref{coro:levels_hyperplanes}
since,
as discussed above,
the $(\geq k)$-level of~$\arr(T)$
corresponds to $(\leq n-k)$-level of $\overline{\arr}$ from above.
\end{proof}
Remark that, for $d=2$,
Theorem~\ref{thm:levels_triangles} implies the $O(kn\alpha(n/k))$ bound,
which is asymptotically the same as the known bound by Sharir~\cite[Theorem 1.2]{s-ksacs-91}
for line segments in~$\Plane$.

An analogous argument can also be applied to piecewise linear functions.
Let $F = \{f_1, \ldots, f_m\}$ be a collection of $(d-1)$-variate piecewise linear functions
that are fully or partially defined on a subset $D_i\subseteq \Real^{d-1}$,
consisting of one or more connected components bounded by linear faces.
Suppose that the domains $D_i$ are triangulated into $(d-1)$-simplices
and let $n$ denote the total number of those simplices.
Consider the arrangement $\arr(F)$ of the graphs of $m$ functions in~$F$,
and its $k$-level is defined analogously as above for the arrangement of triangles.
Observe that the vertices of $\arr(F)$ are colored configurations
by an analogous construction as done above.
Theorems~\ref{thm:CS_general} and~\ref{thm:CS_general_uniform} imply the following.
\begin{corollary}\label{coro:piecewise_linear}
 Given a set $F$ of $m$ $(d-1)$-variate piecewise linear functions 
 with a total of $n$ linear pieces as above,
 for $1\leq k \leq m$,
 the number of vertices in the $(\leq k)$-level of the arrangement of
 the graphs of those functions in~$F$ is
 $O(k m^{d-2} n^{d-1}\alpha(n/k))$; or 
 $O(k n^{d-1}\alpha(n/k))$ if the number of pieces of 
 each function in~$F$ is bounded by $\rho\cdot \frac{n}{m}$ for a constant~$\rho$.
 If $d=2$, then the bound is reduced to $O(k n \alpha(m/k))$.
\end{corollary}
\begin{proof}
Using the known upper bound on the lower envelope of 
simplices~\cite{sa-dsstga-95,e-ueplf:tbnf-89,t-ntasapls-96},
we apply Theorems~\ref{thm:CS_general} and~\ref{thm:CS_general_uniform}
with $T_0(n) = O(n^{d-1}\alpha(n))$.
The number of vertices in the $(\leq k)$-level for $1\leq k\leq m$ is thus 
bounded by
\[ 
 O\left(\frac{k^d}{m}\cdot \left(\frac{mn}{k}\right)^{d-1}\cdot \alpha\left(\frac{mn}{k}\right)\right)
 = O\left(k m^{d-2} n^{d-1} \alpha\left(\frac{n}{k}\right)\right).
\]
in general.
If the number of pieces of any two functions in~$F$ differ by a constant,
then the corresponding color assignment is almost uniform,
so we have the bound $O(k n^{d-1}\alpha(n/k))$. 

In case of $d=2$,
we have a better bound $O(n \alpha(r))$
on the complexity of the lower envelope of
any subset of $r$~functions in~$F$
by Har-Peled~\cite{h-mcl-99}.
So, the claimed bound follows from Theorem~\ref{thm:CS_general}.
\end{proof}


\subsection{Piecewise algebraic functions}

The results of Corollary~\ref{coro:piecewise_linear} 
are again extended to piecewise Jordan arcs 
and to piecewise algebraic functions.
In particular in~$\Real^2$,
Har-Peled~\cite{h-mcl-99} considered
the \changed{overlay}
of arrangements of Jordan arcs
and proved a general upper bound on
a single cell and many cells.
Theorem~\ref{thm:CS_general}, 
together with the results of~\cite{h-mcl-99}, 
we obtain the following,
extending the uncolored analog by Sharir~\cite[Theorem 1.3]{s-ksacs-91}
(see also Sharir and Agarwal~\cite[Corollary 5.18]{sa-dsstga-95}).

\begin{corollary} \label{coro:levels_Jordan}
 Let $S$ be a collection of $n$ $x$-monotone Jordan arcs,
 possibly being unbounded curves,
 such that any two of them intersect at most $t$ times,
 and $(S_1, S_2, \ldots, S_m)$ be a partition of~$S$ 
 into $m$~nonempty subsets.
 Let $E_i$ be the lower envelope of those in~$S_i$
 for $1\leq i\leq m$, and $\arr = \arr(\{E_1, \ldots, E_m\})$ be their arrangement.
 For $1\leq k\leq m$, let $C_{\leq k}$ be the number of vertices in the $(\leq k)$-level of $\arr$.
 \begin{itemize}
  \item In general, $C_{\leq k} = O(kn \cdot \beta_{t+2}(\frac{n}{k}))$,
  where $\beta_{t'}(n') := \lambda_{t'}(n') / n'$ and $\lambda_{t'}(n')$ denotes
  the maximum length of Davenport--Schinzel sequences of order~${t'}$ with $n'$ symbols.
  \item If $S$ consists of unbounded Jordan curves,
  then $C_{\leq k} = O(kn \cdot \beta_t(\frac{n}{k}))$.
  \item If Jordan arcs in~$S_i$ are disjoint for every~$i$, 
  so $E_i = \bigcup_{s\in S_i} s$,
  then $C_{\leq k} = O(kn \cdot \beta_{t+2}(\frac{m}{k}))$.
  \item If Jordan arcs in~$S_i$ are disjoint 
  and every vertical line intersects $E_i$ for every~$i$,
  that is, $E_i$ is the graph of a fully-defined function over~$\Real$,
 then  
 $C_{\leq k} = O(kn \cdot \beta_{t}(\frac{m}{k}))$.
 \end{itemize}  
\end{corollary}
\begin{proof}
The first two claims follow from Theorem~\ref{thm:CS_general}
with the upper bound on the lower envelope of $x$-monotone Jordan arcs 
or unbounded Jordan curves~\cite{sa-dsstga-95}.

We exploit the multicolor combination lemma by Har-Peled~\cite[Theorem 2.1]{h-mcl-99}.
Since each~$S_i$ is chosen such that $E_i$ is $x$-monotone,
each face of the arrangement~$\arr(S_i)$ of those Jordan arcs in~$S_i$
is linear to $|S_i|$.
Also, the arrangement $\arr = \arr(\{E_1, \ldots, E_m\})$ is
the overlay of $\arr(S_1), \ldots, \arr(S_m)$.
Hence, Theorem~2.1 of~\cite{h-mcl-99} implies
that the complexity of any single cell in the overlay arrangement~$\arr$
is $O(n\cdot \frac{\lambda_{t+2}(m)}{m}) = O(n \cdot \beta_{t+2}(m))$.
With this bound, Theorem~\ref{thm:CS_general} implies the third bound.

When $S$ consists of $x$-monotone unbounded Jordan curves
and $E_i$ is taken as the lower envelope of those in~$S_i$,
the complexity of a single cell in~$\arr$ is reduced 
to $O(n\cdot \frac{\lambda_{t}(m)}{m}) = O(n \cdot \beta_{t}(m))$~\cite[Lemma~2.3]{h-mcl-99},
so the fourth claim follows.
\end{proof}

Next, we consider
a collection of colored surface patches in~$\Real^d$ for constant $d\geq 2$.
Specifically,
let $S$ be a collection of $n$ algebraic surface patches in~$\Real^d$
that are graphs of a partially-defined $(d-1)$-variate algebraic functions.
It is known that the complexity of the lower envelope of $F$
is $O(n^{d-1+\epsilon})$ for any positive real~$\epsilon>0$
under some assumptions~\cite{hs-nblwtd-94,s-atublehd-94}.
(See also the book by Sharir and Agarwal~\cite[Chapter 7]{sa-dsstga-95}.)
Suppose $S$ is partitioned into $S_1, \ldots, S_m$
by any color assignment~$\kappa$ to $m$~colors.
Let $E_i$ for $1\leq i \leq m$ be the lower envelope of surface patches in~$S_i$,
and $\arr = \arr(\{E_1,\ldots, E_m\})$ be their arrangement.
For $1\leq k\leq m$, 
the $k$-level of $\arr$ is defined as above to be 
the closure of the set of points~$x$ on the surfaces~$E_i$
such that the downward vertical ray from~$x$ crosses exactly $k-1$ those surfaces.
Then, Theorems~\ref{thm:CS_general}--\ref{thm:CS_general_uniform}
and a derivation analogous to the proof of Theorem~\ref{thm:levels_triangles}
imply upper bounds on the $(\leq k)$-level of~$\arr$.
Hence, we conclude:
\begin{corollary} \label{coro:levels_patches}
 Let $F$ be a set of $m$ $(d-1)$-variate piecewise algebraic functions
 of maximum constant degrees with a total of $n$ algebraic pieces.
 Then, the number of vertices in the $(\leq k)$-level of the 
 arrangement $\arr(F)$ of the graphs of the functions in~$F$
 is bounded by $O(k^{1-\epsilon} m^{d-2} n^{d-1+\epsilon})$
 for any $\epsilon>0$.
 If the number of algebraic pieces in each function in~$F$ 
 is bounded by $\rho\cdot \frac{n}{m}$ for a constant~$\rho$,
 then the bound is reduced to $O(k^{1-\epsilon} n^{d-1+\epsilon})$.
\end{corollary}
This extends the known bounds for uncolored cases;
see Corollaries~7.8 and~7.18 in~\cite{sa-dsstga-95}.


\subsection{Convex polyhedra}

Another interesting structure that fits in the colorful Clarkson--Shor framework
is the arrangement of convex polyhedra.
Let $P_1, \ldots, P_m$ be $m$ given convex polyhedra, bounded or unbounded, in~$\Real^d$
with a total of $n$~facets, and $\arr = \arr(\{P_1,\ldots,P_m\})$ be their arrangement.
In this case, the \emph{depth} of any point \changed{$x\in\Real^d$} is often defined to be
the number of polyhedra~$P_i$ that contain $x$ in its interior.
We are interested in the number of vertices in~$\mathcal{A}$
whose depth is at most $k$.

We interpret this in our framework as follows.
For each facet $f$ of $P_i$, consider the open half-space, bounded by
the hyperplane spanning $f$, that \emph{avoids}~$P_i$.
Let $S$ be the set of all those $n$ open half-spaces
and $\conf(S)$ be the set of all vertices in the arrangement of these
bounding hyperplanes.
We say that a half-space $s \in S$ is in conflict with a vertex $v\in \conf(S)$ 
if $v$ is contained in~$s$.
Now, we consider the color assignment $\kappa \colon S \to K =\{1,\ldots, m\}$,
according to its original polyhedron~$P_i$ for~$i\in K$.
Observe that
the set $\conf(S,\kappa)$ of colored configurations, induced by~$\conf(S)$ with respect to~$\kappa$,
consists of all vertices in $\mathcal{A}$,
and $\conf_{c,j}(S,\kappa)$ is the set of all $c$-chromatic vertices of depth~$m-c-j$.
That is, in this case, the depths are ordered in the reversed way to the weights.

For $d=2$, Aronov and Sharir~\cite{as-cecpp-97} proved that the complexity
of the common exterior of polygons $P_1, \ldots, P_m$
or, equivalently, 
the number of vertices of depth~$0$ in~$\mathcal{A}$ is bounded by $O(n\alpha(m) + m^2)$
in general, and $O(n \alpha(m))$ if the common exterior is connected.
With these upper bounds, Lemma~\ref{lem:CS_general_lb} yields the following
through a similar derivation as done in the proofs of
Theorems~\ref{thm:CS_general} and~\ref{thm:levels_triangles}.


\begin{theorem} \label{thm:polygons_depth}
 Given $m$ convex polygons of a total of $n$ sides in~$\Plane$,
 let $\arr$ be their arrangement.
 For~$0\leq k\leq m-1$,
 the number of vertices of depth at most~$k$ in~$\arr$
 is $O((k+1)n\cdot \alpha(\frac{m}{k+1})+m^2)$.
 If the common exterior of any subset of the $m$ polygons is connected,
 then the bound is reduced to $O((k+1)n\cdot \alpha(\frac{m}{k+1}))$.
\end{theorem}
\begin{proof}
Recall that $c$-chromatic vertices in~$\mathcal{A}$ of depth~$j$
are those configurations of weight $m-c-j$ in~$\conf_{c,m-c-j}(S,\kappa)$.
Hence, the claimed bounds can be shown by a similar derivation
as in the proof of Theorems~\ref{thm:CS_general} and~\ref{thm:levels_triangles}.

Let $1\leq r\leq m$ be an integer parameter and $R\subseteq K$ be a random set of $r$~colors.
In general,  we have
\begin{align*}
 \E[|\conf_{c,r-c}(S_R, \kappa_R)|] &= O(\E[|S_R|]\cdot \alpha(r) + r^2)\\
   & = O\left(\left(\sum_{R'\subseteq K, |R'|=r} |S_{R'}| \Big/ \binom{m}{r} \right) 
     \cdot \alpha(r) + r^2\right) \\
   & = O\left(\left(\binom{m-1}{r-1} n \Big/ \binom{m}{r}\right) \cdot \alpha(r) + r^2 \right)\\
   & = O\left( \frac{r}{m} n \cdot \alpha(r) + r^2 \right)
\end{align*}
by Aronov and Sharir~\cite{as-cecpp-97} 
and Lemma~\ref{lem:sums},
on one hand.
On the other hand, setting $r = \lfloor \frac{m}{k+1} \rfloor$,
Lemma~\ref{lem:CS_general_lb} (with $c=2$ and $a=r-2$) implies
\begin{align*}
 \E[|\conf_{2,r-2}(S_R, \kappa_R)|] & \geq \sum_{j=0}^{m-2} |\conf_{2,j}(S,\kappa)|
       \binom{j}{r-2} \Big/ \binom{m}{r}\\
    & \geq \sum_{j=m-2-k}^{m-2} |\conf_{2,j}(S,\kappa)|
       \binom{j}{r-2} \Big/ \binom{m}{r}\\
    & = \sum_{i=0}^{k} |\conf_{2,m-2-i}(S,\kappa)|
       \binom{m-2-i}{r-2} \Big/ \binom{m}{r}\\
    & \geq \left(\sum_{i=0}^{k} |\conf_{2,m-2-i}(S,\kappa)|\right)
        \cdot \frac{r(r-1)}{m(m-1)} \cdot \left(\frac{1}{2}\right)^2
\end{align*}
if $k \leq \lfloor \frac{m}{2} \rfloor - 1$.

Combining the two inequalities results in the first bound
 \[
  \sum_{j=m-2-k}^{m-2} |\conf_{2,j}(S,\kappa)|
 = O\left( (k+1)n\alpha\left(\frac{m}{k+1}\right) + m^2 \right),
 \]
for $0\leq k\leq \lfloor \frac{m}{2} \rfloor - 1$,
and the number of $1$-chromatic vertices is subsumed by this bound.
One can easily check the same bound holds for $\lfloor \frac{m}{2} \rfloor \leq k \leq m-1$,
since the total number of vertices of the arrangement~$\arr$ is bounded by $O(mn + m^2)$.

The second one can also be derived in a similar way
with the upper bound
 \[ \sum_{c=1}^2 \E[|\conf_{c,r-c}(S_R, \kappa_R)|] = O(\E[|S_R|]\cdot \alpha(r))
   = O\left(\frac{r}{m} n \cdot \alpha(r)\right) \]
if the common exterior of any subset of the $m$ polygons is connected,
as shown by Aronov and Sharir~\cite{as-cecpp-97}.
\end{proof}
Remark that the second bound of Theorem~\ref{thm:polygons_depth} holds
even for simple polygons.
Har-Peled~\cite[Lemma 2.8]{h-mcl-99} proved an upper bound $O(n \alpha(m))$
on the complexity of a single cell in the arrangement of $m$ simple polygons
with $n$ total sides.
Thus, if the common exterior of any subset of the $m$ simple polygons is connected,
the number of vertices of depth~$0$ in their arrangement is $O(n \alpha(m))$,
hence the same upper bound $O((k+1)n\alpha(m/(k+1)))$ is derived for
the number of vertices of depth at most~$k$.

Similarly, for $d=3$, we conclude the following
based on the results of Aronov et al.~\cite{ast-ucptd-97} and Ezra and Sharir~\cite{es-scacp-07}.
\begin{corollary}
 Given $m$ convex polyhedra, bounded or unbounded, of a total of $n$ faces in~$\Real^3$
 and an integer $0\leq k \leq m-1$,
 the number of vertices in their arrangement of depth at most~$k$
 is $O((k+1)mn\log(\frac{m}{k+1})+m^3)$.
 If the common exterior of any subset of the $m$ polyhedra is connected,
 then the bound becomes $O((k+1)^{1-\epsilon}m^{1+\epsilon}n)$ for any $\epsilon>0$.
\end{corollary}
Note that the first bound has been mentioned by Aronov et al.~\cite[Theorem~1.7]{ast-ucptd-97}.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Concluding Remarks} \label{sec:conclusion}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We finish the paper with some remarks and further questions.

The colorful Clarkson--Shor framework provides
a systematic scheme to handle families of configurations or geometric ranges
defined by objects
of
non-constant complexity.
We showed its \changed{application}
to color Voronoi diagrams,
colored $j$-facets, and arrangements of various curves and surfaces
of non-constant complexity.
Our general upper bounds, shown in \changed{Theorems~\ref{thm:CS_general}} and~\ref{thm:CS_general_uniform},
can be applied once
we have obtained any
function~$T_0$ that upper bounds
the number of weight-$0$ uncolored configurations.
While almost the same bounds as in
the uncolored case hold
when $T_0$ is near-linear,
it seems hard to avoid the extra term in the number~$m$ of colors
in general for any color assignment.
Is it possible to obtain the original Clarkson--Shor bound $O((k+1)^c \cdot T_0(n/(k+1)))$,
or similar bound,
on the number of $c$-chromatic weight-$(\leq k)$ colored configurations
under a reasonable requirement on~$T_0$?

In this paper,
we introduced the higher-order color Voronoi diagrams~$\CVD_k(S)$ and $\mCVD_k(S)$
with distance-to-site functions~$\delta_s$ for $s\in S$.
Our combinatorial results
rely on the general position \changed{of the}
functions~$\delta_s$
and conditions~\textbf{V1}--\textbf{V3} on numbers of vertices and unbounded edges
in ordinary nearest and farthest-site Voronoi diagrams.
Can we drop condition~\textbf{V3} to obtain
the same
upper bound~$4k(n-k)-2n$ on the total number of vertices
in $\CVD_k(S)$ and $\mCVD_k(S)$?
In Section~\ref{sec:kcvd_general},
we showed that this can be done for any convex distance function
by a limit argument.


We
presented an iterative approach to compute \changed{order-$k$} color Voronoi
diagrams \changed{under general distance functions that satisfy the
  conditions of 
  abstract Voronoi diagrams;
  and an additional
  condition~\textbf{V3$^\prime$} for the  maximal order-$k$ color counterpart.}
Can one achieve a faster algorithm that computes a \changed{specific}
order-$k$ color Voronoi diagram 
under the Euclidean metric?
Or, can the approach using nondeterminism by Chan et al.~\cite{ccz-oahovdp:usn-24}
be extended to color Voronoi diagrams?




