\section{Omitted proof and pseudocode in \Cref{sec:cograph}}\label{app:cograph}

\subsection{Proof of \Cref{lem:cograph_CSone}}
\begin{proof}
    We use induction on $|X|\ (= |Y|)$.
    As base cases, we consider when $|X| = |Y| = 1$.
    If $X = Y$, then $\dist{\CSone}{X}{Y} = 0 = \size{X \setminus Y}$.
    Otherwise, let $X = \set{x}$ and $Y = \set{y}$.
    If $X$ touches $Y$, $\dist{\CSone}{X}{Y} = 1 = \size{X \setminus Y}$ because $x$ and $y$ are adjacent.
    If $X$ does not touch $Y$, the shortest distance between $x$ and $y$ in $G$ is 2 because $G$ is $P_4$-free.
    Therefore, $\dist{\CSone}{X}{Y} = 2 = \size{X \setminus Y} + 1$.

    For induction steps, we consider several cases.
    In the following, we assume that $|X| = |Y| \ge 2$.
    \emph{Case~A}: $X$ or $Y$ intersects with multiple co-components.
    Without loss of generality, we assume that $X$ intersects with multiple co-components.
    Then, $X$ touches $Y$, and thus there exists $x \in X$ such that $x$ touches $Y$.
    We move $x' \in X \setminus \set{x}$ to any $y \in Y \setminus X$.
    Now the instance $(X, Y)$ is reduced to $(X' = X \setminus \set{x'}, Y' = Y \setminus \set{y})$.
    The reduced case is in Case~A, and thus $\dist{\CSone}{X}{Y} \le 1 + \size{X' \setminus Y'} = |X \setminus Y|$.
    Since $\dist{\CSone}{X}{Y} \ge |X \setminus Y|$, we obtain $\dist{\CSone}{X}{Y} = |X \setminus Y|$.

    In the following cases, we assume that $X$ and $Y$ are contained in co-components $C_X$ and $C_Y$, respectively.
    \emph{Case~B}: $C_X \neq C_Y$.
    In this case, $X \cap Y = \emptyset$ and $X$ touches $Y$.
    Take arbitrarily $x \in X$ and $y \in Y$.
    Then, $(X \setminus \set{x}) \cup \set{y}$ is connected because every $x' \in X$ and $y' \in Y$ are adjacent.
    By moving $x$ to $y$, the instance $(X, Y)$ is reduced to $(X' = X \setminus \set{x}, Y' = Y \setminus \set{y})$.
    The reduced case is in Case~B because $X'$ and $Y'$ are contained in different co-components.
    Therefore, $\dist{\CSone}{X}{Y} \le 1 + \size{X' \setminus Y'} = |X \setminus Y|$.
    By $\dist{\CSone}{X}{Y} \ge |X \setminus Y|$, we obtain $\dist{\CSone}{X}{Y} = |X \setminus Y|$.

    \emph{Case~C-1}: $C_X = C_Y$ and $X$ touches $Y$.
    Since $X$ touches $Y$, we obtain $\dist{\CSone}{X}{Y} = |X \setminus Y|$ in the same way as Case~A.

    \emph{Case~C-2}: $C_X = C_Y$ and $X$ does not touch $Y$.
    In this case, there exists another co-component $C_Z$ because $|V(G)| \ge 2$.
    We move any $x \in X$ to any vertex $z \in C_Z$.
    Then, the problem is reduced to $(X'' = (X \setminus \set{x}) \cup \set{z}, Y)$.
    The reduced case is in Case~A because $X''$ intersects with multiple co-components.
    Thus, $\dist{\CSone}{X}{Y} \le 1 + \size{X'' \setminus Y} = |X \setminus Y| + 1$.
    Since $X$ does not touch $Y$, $\dist{\CSone}{X}{Y} > |X \setminus Y|$ holds.
    Therefore, we obtain $\dist{\CSone}{X}{Y} = |X \setminus Y| + 1$.
    \qed
\end{proof}

\subsection{Pseudocode}
We show pseudocode in \Cref{alg:cograph} and its subroutine in \Cref{alg:one_cc}.\footnote{We intentionally aligned the representation of \Cref{alg:cograph} with Kami{\'n}ski et al.~\cite[Algorithm~1]{kaminski2012complexity}. The readers are encouraged to compare ours with theirs.}
In \Cref{alg:cograph}, a \CS-path refers to a reconfiguration sequence under \CS.
\Cref{alg:one_cc} shows a subroutine for computing a shortest reconfiguration sequence under \CSone.
The subroutine for \CS\ can be similarly implemented.

\begin{algorithm}[hbt!]
\DontPrintSemicolon
\caption{\CCR-\CS\ in cographs}\label{alg:cograph}
\KwIn{A cograph $G$ and two vertex subsets $A, B$.}
\KwOut{A shortest sequence from $A$ to $B$ if they are reconfigurable, $\NO$ otherwise.}
\If{$m(A) \neq m(B)$}{\label{line:first}
    \Return{$\NO$}\;
}
\uElseIf{$\size{V(G)} = 1$}{
    \Return{the trivial \CS-path}\;
}
\uElseIf{$G$ is disconnected}{
    let $C_1, \dots, C_k$ be the connected components of $G$\;
    solve the problem recursively for the connected components $C_1, \dots, C_k$ with respective vertex subsets $(A \cap C_1, B \cap C_1), \dots, (A \cap C_k, B \cap C_k)$\;
    \uIf{one of the outputs is \NO}{
        \Return{\NO}\;
    }
    \Else{
        merge corresponding $(A \cap C_i, B \cap C_i)$ paths into an $(A, B)$ \CS-path $P$\;
        \Return{$P$}\;
    }
}
\uElseIf{$\size{\C{A}} = \size{\C{B}} = 1$}{\label{line:one_cc_start}
    \Return{$\textsc{CSOneComponent}(G, A, B)$}\;\label{line:subroutine}
}\label{line:one_cc_end}
\uElseIf{$A$ and $B$ are in the same co-component of $G$}{\label{line:same_cocomp_start}
    solve the problem for $A$ and $B$ recursively on that co-component and\;
    \Return{the output}\;
}\label{line:same_cocomp_end}
\Else{
    \Return{\NO}\;
}
\end{algorithm}

\begin{algorithm}[hbt!]
\DontPrintSemicolon
\caption{$\textsc{CSOneComponent}(G, A, B)$}\label{alg:one_cc}
\KwIn{A connected cograph $G\ (\size{V(G)} \ge 2)$ and two connected vertex subsets $A, B$ with $|A| = |B|$.}
\KwOut{A shortest sequence from $A$ to $B$ if they are reconfigurable, $\NO$ otherwise.}
let $\C{A} = \set{X}$ and $\C{B} = \set{Y}$\;
let $P$ be an empty sequence\;
\If{$X$ does not touch $Y$}{
    let $C_{XY}$ be the co-component containing $X$ and $Y$\;
    let $C_Z$ be another co-component\;
    Take arbitrarily $x \in C_{XY}$ and $z \in C_Z$\;
    Add ``$\mbox{move } x \mbox{ to } z$'' to $P$\;
    $X \gets (X \setminus \set{x}) \cup \set{z}$\;
}
let $C_X$ and $C_Y$ be the co-components containing $X$ and $Y$, respectively\;
let $x \in X$ be a vertex touching $Y$\;
Move vertices in $X \setminus (\set{x} \cup Y)$ to $Y \setminus X$, and finally move $x$ to $Y \setminus X$ (if $x \notin Y$)\;
\Return{$P$}\;
\end{algorithm}


\section{Omitted proof in \Cref{sec:chordal}}
We show the proof of \Cref{lem:chordal}.
\begin{proof}
    Let $G$ be a chordal graph, $A, B \subseteq V$ be two vertex subsets with the same CC-multiset.
    Assume that $\ccpiran{A}{B}$ contains an induced $C_{2k}$ for some $k \ge 2$.
    Let the components on $C_{2k}$ in $\ccpiran{A}{B}$ be $C_A^1, C_B^1, C_A^2, C_B^2, \dots, C_A^k, C_B^k$.
    For $i \in \set{1, \dots, k}$, $C_A^i$ touches $C_B^{i-1}$ and $C_B^i$, and does not touch the other components. (Here, we consider integers in 1 + mod $k$).
    Thus, for every $i \in \set{1, \dots, k}$, there is a vertex of $G$ that is contained in $C_A^i$ and not contained in the other components.
    The same holds for $C_B^i$'s.
    Let the vertices $v_A^1, v_B^1, v_A^2, v_B^2, \dots, v_A^k, v_B^k$, and $C^*$ be a shortest cycle passing through the vertices in this order.
    Since $C^*$ is shortest, it's an induced cycle in $G$.
    In addition, from $k \ge 2$, the length of $C^*$ is at least four.
    Therefore, $G$ contains an induced $C_{\ell}$ for some $\ell \ge 4$, which contradicts that $G$ is chordal.
    \qed
\end{proof}

