% More or less in p.626 of main nb.
\begin{restatable}[]{claim}{multiplicityProperty} \label{claim.3}
For any two $C_1, C_2 \in L^*$ and $e \in E(C_1) \cup E(C_2)$, it holds that $\max(\mu_e(C_1 \vee C_2), \mu_e(C_1 \wedge C_2)) \leq \max(\mu_e(C_1), \mu_e(C_2))$.
\end{restatable}
\begin{proof}
    We prove this by case distinction on the containment of $e$ in $E(C_1) \cup E(C_2)$. Without loss of generality, assume that $e$ belongs to the $\ell$-th chain in the chain decomposition of $E$ dictated by property \ref{property.1} of Theorem \ref{theorem.1}; i.e., $e \in E_\ell$. There are three cases to consider: $e \in E(C_1) \setminus E(C_2)$, $e \in E(C_2) \setminus E(C_1)$, and $e \in E(C_1) \cap E(C_2)$. 
\begin{description}
   \item[Case 1: $e \in E(C_1) \setminus E(C_2)$.] 
    By Claim \ref{claim.1}, we know that $\mu_e(C_1 \vee C_2) + \mu_e(C_1 \wedge C_2) = \mu_e(C_1)$. Since $\mu_e(C_1 \vee C_2)$ and $\mu_e(C_1 \wedge C_2)$ are nonnegative, neither term can be greater than $\mu_e(C_1)$ and thus, the claim holds. 
   \item[Case 2: $e \in E(C_2) \setminus E(C_1)$.] 
   This case is symmetrical to Case 1. 
   \item[Case 3: $e \in E(C_1) \cap E(C_2)$.]
   Consider the interval representation of edge $e$ in $E(C_1)$ and $E(C_2)$. Let $I_e(C_1) = (\alpha, \beta)$ and $I_e(C_2) = (\sigma, \tau)$ be such intervals. There are two subcases to consider: $I_e(C_1) \cap I_e(C_2) = \emptyset$, and $I_e(C_1) \cap I_e(C_2) \neq \emptyset$. 
   \begin{description}
       \item[Subcase 3.1: $I_e(C_1) \cap I_e(C_2) = \emptyset$.] We claim that $\max({\mu_e(C_1 \vee C_2), \mu_e(C_1 \wedge C_2)})$ is equal to $\max(\mu_e(C_1), \mu_e(C_2))$ in this subcase. To see this, w.l.o.g., suppose that $\beta < \sigma$. Then, because $C_2$ is in left-right order, the solutions of $C_2$ in the interval $(\alpha, \beta)$ each contain a chain-predecessor of $e$. Then, by definition of the join operation in $L^*$, we have $I_e(C_1 \vee C_2) = (\alpha, \beta)$. Similarly, the solutions of $C_1$ in the interval $(\sigma, \tau)$ each contain a chain-successor of $e$. Hence, by the meet operation in $L^*$, we have $I_e(C_1 \wedge C_2) = (\sigma, \tau)$. Comparing the length of the intervals, we obtain that $\mu_e(C_1 \vee C_2) = \mu_e(C_1)$ and $\mu_e(C_1 \wedge C_2) = \mu_e(C_2)$, from which the claim follows. 
       \item[Subcase 3.2: $I_e(C_1) \cap I_e(C_2) \neq \emptyset$.] We have two further subcases to consider: $I_e(C_1) \not\subseteq I_e(C_2)$ (or $I_e(C_2) \not\subseteq I_e(C_1)$), and $I_e(C_2) \subseteq I_e(C_1)$ (or vice versa). 
       \begin{description}
           \item[Subcase 3.2.1: $I_e(C_1) \not\subseteq I_e(C_2)$.]
           The proof of this subcase is analogous to the proof of subcase (3.1), where we also obtain that $\max({\mu_e(C_1 \vee C_2), \mu_e(C_1 \wedge C_2)})$ equals $\max(\mu_e(C_1), \mu_e(C_2))$. It suffices to notice that the intersection of intervals contributes equally to the multiplicities $\mu_e(C_1)$ and $\mu_e(C_2)$, as well as to $\mu_e(C_1\vee C_2)$ and $\mu_e(C_1 \wedge C_2)$. Hence we can treat the complement in the same way as Subcase (3.1).
           \item[Subcase 3.2.2: $I_e(C_2) \subseteq I_e(C_1)$.] Recall that $I_e(C_1) = (\alpha, \beta)$, and $I_e(C_2) = (\sigma, \tau)$. Then, in this subcase: $\alpha \leq \sigma \leq \tau \leq \beta$. Again, by definition of join and meet, we have that $I_e(C_1 \vee C_2) = (\alpha, \tau)$ and $I_e(C_1 \wedge C_2) = (\sigma, \beta)$. Now, since $\tau - \alpha \leq \beta - \alpha$ and $\beta - \sigma \leq \beta - \alpha$, we obtain $\max(\mu_e(C_1 \vee C_2), \mu_e(C_1 \wedge C_2)) \leq \max(\mu_e(C_1), \mu_e(C_2))$, which is what we wanted.
       \end{description}
   \end{description}
\end{description}

Since the claim is true for all cases covered and all cases have been considered, the result is proved.
\end{proof}

With these three claims at our disposal, we are just one step away from proving the submodularity of $\hat{d}_\mathrm{sum}$. Let $B_e: U_{\mathrm{lr}}^k \rightarrow \mathbb{N}$ be the function defined by $B_e(C) = \binom{\mu_e(C)}{2}$. We can rewrite Eq. \eqref{eq:dsumMultiplicityMin} as $\hat{d}_\mathrm{sum}(C) = \sum_{e \in E(C)} B_e(C)$. The following proposition is a consequence of Claims \ref{claim.1} and \ref{claim.3}. 

\begin{proposition} \label{prop.1}
For any two $C_1, C_2 \in L^*$ and $e \in E$, we have $B_e(C_1 \vee C_2) + B_e(C_1 \wedge C_2) \leq B_e(C_1) + B_e(C_2)$.
\end{proposition}
\begin{proof}

We show that $\binom{a}{2} + \binom{b}{2} \leq \binom{c}{2} + \binom{d}{2}$ for $a, b, c, d \in \mathbb{N}$, given the following conditions: (i) $a + b = c + d$, and (ii) $\max(a, b) \leq \max(c, d)$. By setting $a = \mu_e(C_1 \vee C_2)$, $b = \mu_e(C_1 \wedge C_2)$, $c = \mu_e(C_1)$, and $d = \mu_e(C_2)$, the proposition follows, as conditions (i) and (ii) correspond to the properties of the multiplicity function stated in Claims \ref{claim.1} and \ref{claim.2}, respectively.


Without loss of generality, assume that $a \leq b$ and $c \leq d$. Condition (ii) ensures that $b \leq d$, and together with (i) implies that $a \geq c$, and $b \geq c$. Therefore, $(b - a) \leq (d - c)$. It is folklore that for $a, b > 0$ with fixed sum, the product $a \cdot b$ becomes larger as $|a - b|$ becomes smaller. Hence, we have $a \cdot b \geq c \cdot d$. Next, from condition (i), we know that $(a+b)^2 = (c+d)^2$. Combining this with the inequality just established, and subtracting $(a+b)$ and $(c+d)$ from each side, respectively, we get $a(a-1) + b(b-1) \leq c(c-1) + d(d-1)$. By definition of the binomial coefficient, the proposition immediately follows. 
\end{proof}

With Proposition \ref{prop.1}, we are ready to prove that $\hat{d}_\mathrm{sum}(C)$ is submodular in the lattice $L^*$. 

\begin{lemma}[Submodularity Lemma] \label{lemma.3}
    The function $\hat{d}_{\mathrm{sum}}: \Gamma_{\mathrm{lr}}^k \rightarrow \mathbb{N}$ is submodular in $L^*$.
\end{lemma}
\begin{proof}
    Proposition \ref{prop.1} states that the function $B_e(C)$ is submodular in the lattice $L^*$. Now, recall that the sum of submodular functions is also submodular. Then, taking the sum of $B_e(C)$ over all elements $e \in E$ results in a submodular function. From here, notice that $B_e(C) = 0$ when $\mu_e(C) < 2$. This means that such elements do not contribute to the sum. It follows that, for any two $C_1, C_2 \in L^*$, we have
\begin{equation*}
    \sum_{e \in E}B_e(C_1 \vee C_2) + \sum_{e \in E}B_e(C_1 \wedge C_2) \leq \sum_{e \in E}B_e(C_1) + \sum_{e \in E}B_e(C_2). 
\end{equation*}
Each sum in this inequality corresponds to the definition of $\hat{d}_{sum}$ applied to the arguments $C_1 \vee C_2$, $C_1 \wedge C_2$, $C_1$ and $C_2$, respectively. Hence, by definition of submodularity, we obtain our desired result.
\end{proof}

\paragraph{Part 4: Compactness.} 
While Lemmas \ref{lemma.1}-\ref{lemma.3} already demonstrate the reduction of \textsc{Max-Sum $k$-Diverse Solutions} to SFM, this reduction alone does not guarantee an efficient algorithm. To complete the proof of Theorem \ref{theorem.1}, it remains to show that a compact representation of the left-right ordered lattice $L^*$ exists and can be constructed efficiently. This is done in the following lemma, assuming that property \ref{property.3} holds. 

\begin{lemma}[Compactness Lemma] \label{lemma.4}
    A compact representation of $L^*$ can be constructed in polynomial time in $n$ and $k$. 
\end{lemma}
\begin{proof}
    By Birkhoff's representation theorem, we need only specify the set of join-irreducibles of $L^*$ for us to obtain a compact representation in $O(|J(L^*)|^2)$ time.    
    Next, we prove that the set of join-irreducibles of $L^*$ is of size $O(kn)$ and is given by
    \begin{center}  
        $J(L^*) = \bigcup_{i = 1}^k J_i$, where $J_i := \{(\underbrace{0_L, \ldots, 0_L}_{i-1 \text{ times}}, \underbrace{p, \ldots, p}_{k-i+1 \text{ times}})\, : \, p \in J(L)\}$;
    \end{center} 
that is, the join-ireducibles of $L^*$ are determined by the irreducibles of $L$. Since, by property \ref{property.3} of Theorem \ref{theorem.1}, the join-irreducibles of $L$ can be found in polynomial time, the lemma follows.   

    First, recall that an element $x \in L^*$, where $x \neq 0_L$, is a join-irreducible if and only if $x$ has a single immediate predecessor. To prove our claim, we show that (i) the $k$-tuples $J_i$, with $1 \leq i \leq k$, are in $L^*$ and satisfy this property, and (ii) that no other tuple in $L^*$ satisfies it. 

    To prove (i), let $C(i, p)$ denote the $k$-tuple $(0_L, \ldots, 0_L, p, \ldots, p) \in J_i$, where the first $i-1$ entries contain $0_L$ and the remaining $\ell = k-i+1$ entries contain the element $p$, with $i \in [k]$ and $p \in J(L)$. It is clear that $C(i, p) \in L^*$, since each entry in $C(i, p)$ is a feasible solution from the set $\Gamma$, and $0_L \preceq X$ for any $X \in \Gamma$. Notice that any predecessor of $C(i, p)$ in $L^*$ must be of the form $(0_L, \ldots, 0_L, q_\ell, \ldots, q_k)$ with $q_j \in L$, where $q_j \preceq p$ for all $j \in [\ell, k]$ and $(q_\ell, \ldots, q_{k})$ is in left-right order. Thus, an immediate predecessor of $C(i, p)$ in $L^*$ must be a $k$-tuple of the form $Q(i, q, p) := (0_L, \ldots, 0_L, q, p, \ldots, p)$ constructed by replacing the $i$th entry of $C(i, p)$ with an element $q \in L$ such that $q \prec p$. Assume, for the sake of contradiction, that $C(i, p)$ has more than a single immediate predecessor. Then, the join of any two such tuples $Q(i, x, p)$ and $Q(i, y, p)$ would result in $C(i, p)$. By construction, this can only happen if either $x = p$ or $y = p$, but we assumed that $x \prec p$ and $y \prec p$, which is a contradiction. Hence, $C(i, p)$ must have a single immediate predecessor. Since this holds for all $i\in [k]$ and arbitrary $p$, it follows that each of the tuples in $J(L^*)$ has a single immediate predecessor. 

    It remains to show (ii); that is, that there is no tuple in $L^* \setminus \bigcup_{i = 1}^k J_i$ which is also a join-irreducible of $L^*$. For this, it suffices to show that any tuple in $L^* \setminus \bigcup_{i = 1}^k J_i$ can be written as the join of two other elements in $L^*$. Indeed, consider an arbitrary tuple $T \in L^* \setminus \bigcup_{i = 1}^k J_i$. Such a tuple has the form $T = (0_L, \ldots, 0_L, a, \ldots, b, \ldots)$, with $a \prec b$, where $a \in L$ is the first entry in $T$ that is not the bottom element $0_L$, and $b \in L$ is the first entry in $T$ that is neither $0_L$ nor $a$. Now, consider the tuple $T_1 = (0_L, \ldots, 0_L, a, \ldots, a)$ obtained by replacing every successor of $a$ in $T$ by element $a$, and the tuple $T_2 = (0_L, \ldots, 0_L, b, \ldots)$ obtained from $T$ by replacing every predecessor of $b$ by $0_L$. It is clear that $T_1, T_2 \in L^*$. Moreover, it holds that $T_1 \prec T$ and $T_2 \prec T$, while $T_1$ and $T_2$ are incomparable. Then, by definition of the join operation in the lattice $L^*$, we have that $T = T_1 \vee T_2$. Hence, $T$ can be can be written as the join of two other elements in $L^*$ and thus, is not a join-irreducible of $L^*$. 

    From (i) and (ii) above, we have thus shown that the set of join-irreducibles $J(L^*)$ is given by $\bigcup_{i = 1}^k J_i$. To conclude the proof, we look at the size of $J(L^*)$. First, observe that the index $i$ runs from $1$ to $k$. Also, by property \ref{property.3} of Theorem \ref{theorem.1} we know that $|J(L)| = O(n)$. It then follows that $|J(L^*)| = O(kn)$.
\end{proof}

% The most detailed reference of such an algorithm is \cite{garg2018applying}. 
\begin{remark}
    Consider the lattice $L$ of feasible solutions. Let $J(e) \in J(L)$ be the minimum join-irreducible element of $L$ that contains element $e \in E$. It is clear that every join-irreducible element of $L$ is of this form. Hence, we may write $J(L) = \{J(e) \; | \; e \in E\}$. Then, to construct $J(L)$, it is sufficient to give a procedure to find $J(e)$ for a given $e \in E$. We could then rewrite Property \ref{property.3} of Theorem \ref{theorem.1} by assuming the existence of such an algorithm running in polynomial time. We remark that such a procedure has been shown to exist for various combinatorial objects like stable matchings and the set of \textit{consistent cuts of a computation} \cite{garg2001slicing, mittal2001computation, garg2018applying}.    
\end{remark}

With Lemma \ref{lemma.4}, a compact representation of $L^*$ can constructed in polynomial time. It is also clear that the function $\hat{d}_\mathrm{sum}$ can be computed efficiently. Then, by Theorem \ref{theorem:sfmDistributiveLattices} and Lemmas \ref{lemma.1}-\ref{lemma.4}, the proof of Theorem \ref{theorem.1} is complete. In the next section, we apply this framework to concrete combinatorial problems, verifying that their feasible solution sets satisfy properties \ref{property.1}-\ref{property.3} of the theorem. 

\section{Applications of the Framework} \label{sec.4}

We present examples of combinatorial problems whose feasible solution sets meet each of the conditions outlined in Theorem \ref{theorem.1}, allowing for the generation of maximally diverse solutions within our framework. Specifically, we discuss minimum $s$-$t$ cuts (Section \ref{section.mincuts}) and stable matchings (Section \ref{section.stableMatchings}). %and market clearing price vectors (Section \ref{section.orientations}). 

\subsection{\texorpdfstring{Minimum $s$-$t$ cuts}{Minimum s-t Cuts}} \label{section.mincuts}
The \textsc{Minimum $s$-$t$ Cut} problem is a classic combinatorial optimization problem. Given a directed graph $G = (V, E)$ and two special vertices $s, t \in V$, the problem asks for a subset $S \subseteq E$ of minimum cardinality that separates vertices $s$ and $t$, meaning that removing these edges from $G$ ensures there is no path from $s$ to $t$. Such a set is called a \textit{minimum $s$-$t$ cut} or \textit{$s$-$t$ mincut}. Here, we consider the problem of finding diverse minimum $s$-$t$ cuts, formally defined below. 

\begin{extthm}[\textsc{Max-Sum $k$-Diverse Minimum s-t Cuts}] \label{problem:2}
Given are a directed graph $G = (V, E)$ and vertices $s,t \in V$. Let $\Gamma \subseteq 2^E$ be the set of minimum $s$-$t$ cuts in $G$, and let $\Gamma_k$ be the set of $k$-multisets over $\Gamma$. Find $C \in \Gamma_k$ such that $d_\mathrm{sum}(C) = \max_{S \in \Gamma_k} d_\mathrm{sum}(S)$.
\end{extthm}

Using our framework, we reproduce the findings of De Berg et al. \cite{de2023finding} for \textsc{Max-Sum $k$-Diverse Minimum s-t Cuts}; that is, we show that the problem can be solved in polynomial time. For this, it suffices to show that the set $\Gamma$ of minimum $s$-$t$ cuts satisfies properties \ref{property.1}-\ref{property.3} of Theorem \ref{theorem.1}. We prove these statements in order. 

\begin{lemma}[Property 1] \label{lemma.MinCuts.1}
    There is a chain decomposition of the edge set $E$ into $r$ disjoint chains, such that each minimum $s$-$t$ cut $X \subseteq E$ contains exactly one element from each chain.  
\end{lemma}
\begin{proof}
    We construct the $r$ chains as follows. Let $\mathcal{P}$ be an (arbitrary) set of edge-disjoint $s$-$t$ paths in $G$ with maximum cardinality $r$. Define $E(p_i)$ as the set of edges traversed by the path $p_i \in \mathcal{P}$. For each path $p_i \in \mathcal{P}$, consider the order relation $\preceq_i$ defined as follows: for any $x, y \in E(p_i)$, we say $x \preceq_i y$ if and only if path $p_i$ meets edge $x$ before edge $y$, or if $x$ and $y$ are the same edge. Since every pair of edges within a path $p_i$ is comparable under this relation, each poset $(E(p_i), \preceq_i)$, for $i \in [r]$, forms a chain. Moreover, these chains are disjoint by the definition of the set $\mathcal{P}$. 

    By Menger's theorem, the size of a minimum $s$-$t$ cut in $G$ equals the maximum number of edge-disjoint $s$-$t$ paths, which is $r$. Consequently, any minimum $s$-$t$ cut $X \subseteq E$ must include exactly one edge from each chain $(E(p_i), \preceq_i)$, $i \in [r]$. Otherwise, if $X$ contained fewer than $r$ edges, it would not be a valid $s$-$t$ cut, and if it contained more, it would not be of minimum size. Hence, $\Gamma \subseteq E(p_1) \times \dots \times E(p_r)$. 

    Consider now the edges in $E' = E \setminus \bigcup_{1 \leq i \leq r} E(p_i)$. We call these edges \textit{residual edges}. Observe that these edges can never be part of a minimum $s$-$t$ cut. This follows because such a cut must contain exactly one edge from each chain in $\mathcal{P}$, and cutting any additional edge from $E'$ would only increase the cut size, violating minimality. Hence, we simply distribute the residual edges arbitrarily over the $r$ chains. This does not change the fact that the chains are disjoint, or that the set of minimum $s$-$t$ cuts is a subset of the cartesian product of the augmented chains. This completes the proof. 
\end{proof}

