\subsection{Numerical Scheme for the Inhomogeneous Part}\label{sec:FCP_inhom_sol_appr}
%\vspace*{-1em}
In this part, we apply the propagator approximation method from \cref{sec:FCP_Prop_Approx} to obtain an efficient numerical algorithm for the inhomogeneous part $u_{\mathrm{ih}}(t)$ of the mild solution to~\eqref{eq:FCP_DE}, \eqref{eq:FCP_BC}, defined by \eqref{eq:FCP_hom_inhom}.
This formula combines the action of $S_{\alpha}(t)$ on a certain vector from $X$ with the subsequent action of the integral operator.
The numerical evaluation of such composition amounts to the reevaluation of  $S_{\alpha}(s)$ at each quadrature point $\left\{s_k\right\}_{k=1}^K$,  needed to approximate the outer integral.
As we have learned from the properties of the numerical method developed in \cref{sec:FCP_Prop_Approx},
this is not a problem for the first term of $u_{\mathrm{ih}}(t)$, where the argument $f(0)$ is fixed, because only $2N+1$ parallel resolvent evaluations are needed.
For the second term, however, the numerical evaluation of $S_{\alpha}(t-s) J_\alpha f'(s)$ for every new value of $t$ requires the reevaluation of resolvents for the entire set of new quadrature points on $\Gamma_I$.
This leads to the solution of up to $(2N+1)K$ additional stationary problems and may require additional storage and inter-process communication, when the parallel computing model is used for evaluation.
To reduce the number of required resolvent evaluations, we take advantage of the fact that the operator-dependent part of $S_{\alpha}(t)$ in representation \eqref{eq:FCP_SO_exp_cor_repr_par}  is itself a linear operator on $X$; hence, it can be interchanged with the integral operator acting in $t$ only
\begin{align*}
	 & \intl_0^t S_{\alpha}(t - s)   J_\alpha f'(s)\, ds
	= \intl_0^t \frac{1}{2\pi i}\intl_\Gamma  e^{z(t-s)}  z^{\alpha-1} (z^\alpha I + A)^{-1}  J_\alpha f'(s) \, dz \, ds                                                                         \\
	 & = 	\intl_0^t\frac{1}{2\pi i}   \intl_\Gamma   e^{z(t-s)}  \left( z^{\alpha-1} (z^\alpha I + A)^{-1} - \frac{1}{z}I \right) J_\alpha f'(s) \, dz +  J_\alpha f'(t)\, ds                    \\
	 & = 	\intl_0^t J_\alpha f'(s)\, ds + \frac{1}{2\pi i}   \intl_\Gamma   \left( z^{\alpha-1} (z^\alpha I + A)^{-1} - \frac{1}{z}I \right) \intl_0^t e^{z(t-s)}  J_\alpha f'(s) \, ds \, dz  .
\end{align*}
Here, we used formula \eqref{eq:FCP_SO_cor_repr} under the assumption that $J_\alpha f'(s) \in D(A^\gamma)$, $\gamma>0$ and, then, relied upon the uniform convergence of the corrected representation of $S_{\alpha}(t-s) $  with respect to $s \in [0, t]$, that had been established earlier.
As we can see from the newly obtained representation, now the evaluation of the time-dependent part is performed in the resolvent's argument.
This reduces the number of parallel resolvent evaluations per $t$ to $2N+1$ for this term.
The last representation permits us to rewrite the inhomogeneous part of solution $u_{\mathrm{ih}}(t)$ in the form
\vspace*{-6pt}
\begin{equation}\label{eq:FCP_inhom_cor_repr}
	\begin{aligned}
		u_{\mathrm{ih}}(t)  = & J_\alpha S_{\alpha}(t)f(0) + \intl_0^t J_\alpha f'(s)\, ds                                                           \\[-4pt]
		                      & +  \frac{1}{2\pi i}\intl_{-\infty}^\infty F_{\alpha,1}(\xi)\intl_0^t e^{z(\xi)(t-s)}  J_\alpha f'(s) \, ds \, d\xi .
	\end{aligned}
\end{equation}

Next, we address another ingredient essential to the numerical  evaluation of \eqref{eq:FCP_inhom_cor_repr}, which is an efficient quadrature method for the Riemann--Liouville integral  $J_\alpha v(t)$ defined by~\eqref{eq:FCP_RLInt}.
While evaluating this integral numerically, it is important to select the quadrature rule that, on the one hand, can handle the endpoint singularity appearing in the integrand when $\alpha<1$ and, on the other hand, is able to provide exponentially convergent approximation.
Among existing quadrature rules, only sinc-quadrature on a finite interval satisfies two mentioned properties simultaneously (see \cite{Stenger1993}).
We construct a version of such quadrature rule by transforming $J_\alpha$ into the integral over $(-\infty, \infty)$ and then applying the chosen sinc-quadrature formula.
Let $s = {t e^p}/\left ({1+e^p}\right )$, then
\[\begin{aligned}
		J_\alpha v(t)
		 & = \frac{1}{\Gamma(\alpha)}  \int\limits_{-\infty}^{\infty} \left( t - \frac{t e^p}{1+e^p}\right)^{\alpha -1 }v\left ( \frac{t e^p}{1+e^p} \right ) \, ds \\
		 & = \frac{t^{\alpha}}{\Gamma(\alpha)} \int\limits_{-\infty}^{\infty} \frac{e^p}{(1+e^p)^{\alpha + 1}} v\left ( \frac{t e^p}{1+e^p} \right ) \, dp.
	\end{aligned}\]
The reader may note that the singularity $(t-s)^{\alpha-1}$  from original definition \eqref{eq:FCP_RLInt} of $J_\alpha v(t)$ is no longer present in the last integral and
the new kernel of $J_\alpha v(t)$ decays exponentially as $p \rightarrow \infty$.
More precisely, there exist a constant $c>0$, such that
\begin{equation}\label{eq:RLInt_Decay}
	\frac{e^p}{(1+e^p)^{\alpha + 1}}
	= \left(e^{-\frac{p}{\alpha+1}}+e^{\frac{\alpha p}{\alpha + 1}} \right)^{-(\alpha + 1)}
	\leq c\begin{cases}
		e^{-\alpha p}, & p > 0, \\
		e^{p},         & p < 0. \\
	\end{cases}
\end{equation}

Our intent here is to approximate $J_\alpha v(t)$ by the time-dependent operator $\wt{J}_\alpha^N v(t)$, that takes into account the difference in a speed of kernel's decay as $p\rightarrow \pm \infty$, illustrated by the above bound.
To introduce the approximation $\wt{J}_\alpha^N v(t)$ properly, let us to recall the following definition \cite[Definition 3.1.5]{Stenger1993}.
The function $f$ is said to belong to the class $\mathbf{L}_{a,b}(D_d)$ if it is analytic in $D_d$ and there exist a constant $c > 0$ such that for all $z \in D_d$:
\[
	|v(z)|  \leq c\frac{|e^z|^a}{(1 + |e^z|)^{a + b}}.
\]
The constants $a, b > 0$ will be referred to as the decay orders (or the decay order if $a = b$).

\begin{proposition}\label{prop:FCP_RLInt}
	Assume that the function $v$: $[0,T] \rightarrow X$ is bounded $\|v(t)\| < \infty$, for any $t \in [0,T]$.
	If $v(z)$ admits analytic extension to the ``eye-shaped" region
	\begin{equation}\label{eq:FCP_D_d_2}
		D_d^2 = \left\{z \in \oC: \left|\arg{\left(\frac{z}{T-z}\right)}\right| < d \right\},
	\end{equation}
	for some $d \in (0, \pi/2)$, then the operator
	\begin{equation}\label{eq:FCP_RLInt_appr}
		\begin{aligned}
			\wt{J}_\alpha^N v(t)
			=  \frac{t^{\alpha}h }{\Gamma(\alpha)}\sum\limits_{k =-\lceil \varepsilon N \rceil}^{\lceil\delta N\rceil}  \frac{e^{kh}}{(1+e^{kh})^{\alpha + 1}} v\left ( \frac{t e^{kh}}{1+e^{kh}} \right ), \\
		\end{aligned}
	\end{equation}
	with $N \in \N$, $\varepsilon = \min\left \{1, \alpha\right \}$, $\delta = \min\left \{\frac{1}{\alpha}, 1\right \}$ and $h = \sqrt{\frac{2 \pi d}{\varepsilon N}}$,
	defines the convergent approximation to
	\begin{equation}\label{eq:FCP_RLInt_R}
		J_\alpha v(t)
		= \frac{t^{\alpha}}{\Gamma(\alpha)} \int\limits_{-\infty}^{\infty} \frac{e^p}{(1+e^p)^{\alpha + 1}} v\left ( \frac{t e^p}{1+e^p} \right ) \, dp.
	\end{equation}
	Moreover, for  all $t \in [0,T]$
	\begin{equation}\label{eq:FCP_RLInt_err_est}
		\left\|J_\alpha v(t) - \wt{J}_\alpha^N v(t)\right\|
		\leq \frac{C t^\alpha}{\Gamma(\alpha)} e^{- \sqrt{2 \pi d \varepsilon N} },
	\end{equation}
	where the constant $C>0$ is independent of $N$ and $t$.
\end{proposition}
\begin{proof}
	When $t = T$, the function $t{e^z}/(1+e^z)$ maps the infinite horizontal strip $D_d$ of half-height $d$ into the ``eye-shaped'' region $D_d^2$  (see \cite[Example 1.7.5]{Stenger1993}) around the interval $[0, T]$.
	For smaller values of $t$,  it maps $D_d$ into the region $tD_d^2 \equiv \left \{z \in C: z T/t \in D_d^2 \right \}$, which is a proper subset of $D_d^2$ as long as $t < T$.
	Consequently, if the assumptions regarding $v(z)$ are fulfilled, the integrand from \eqref{eq:FCP_RLInt_R} belongs to the class of functions $\mathbf{L}_{1,\alpha}(D_{d})$ for any $t \in (0, T]$.
	Then, the results regarding the convergence of \eqref{eq:FCP_RLInt_appr} to  \eqref{eq:FCP_RLInt_R}, as well as the form of~\eqref{eq:FCP_RLInt_appr} itself, and the error estimate stated in \eqref{eq:FCP_RLInt_err_est} follow from \cite[Theorem 4.2.6]{Stenger1993}.
\end{proof}

\begin{remark}\label{rem:FCP_RLInt_appr_ext}
	The results of \cref{prop:FCP_RLInt} remain valid if, instead of the boundedness of $v(z)$, we assume that the integrand from \eqref{eq:FCP_RLInt_R} belongs to the class $\mathbf{L}_{a,b}(D_d)$.
	In such case, the parameters $\epsilon, \delta$ from \eqref{eq:FCP_RLInt_appr} should be determined by $\epsilon = \min\{a,b\}/a$, $\delta = \max\{a,b\}/b$.
\end{remark}
The presence of factor $t^\alpha$ in error estimate \eqref{eq:FCP_RLInt_err_est} makes it possible to use fewer terms in~\eqref{eq:FCP_RLInt_appr} as $t$ decreases, if the end goal is to reach the prescribed accuracy uniformly in $t$.
Let us assume that the desired accuracy is achieved for some $t_0$ by setting $N=N_0$, then \mbox{for $t \in (0, t_0)$:}
\[
	t^\alpha e^{- \sqrt{2 \pi d \varepsilon N} } = t_0^\alpha e^{- \sqrt{2 \pi d \varepsilon N_0} }.
\]
After solving this equation for $N$, we obtain
\begin{equation}\label{eq:FCP_RLInt_appr_N_adj}
	N(t) = \left (\sqrt{N_0}+\frac{\alpha\ln{(t/t_0)}}{\sqrt{2 \pi d \varepsilon}} \right )^2.
\end{equation}
Formula \eqref{eq:FCP_RLInt_appr_N_adj} becomes instrumental in the situations where one needs to numerically evaluate $\wt{J}_\alpha^N v(t)$ for a range of $t$-values.
This is the case of the inhomogeneous part of solution representation given by \eqref{eq:FCP_inhom_cor_repr}, whose terms contain the integrals of $J_\alpha f'(s)$.

Before addressing the question on how to numerically evaluate \eqref{eq:FCP_inhom_cor_repr}, we would like to consider a prerequisite problem on how to quantify the contribution of the error in the argument $v(t)$ of $\wt{J}_\alpha^N v(t)$ to the overall error of approximation to $J_\alpha v(t)$.
\begin{corollary}\label{eq:FCP_RLint_NA}
	Assume that functions $v$, $\wt{v}$ satisfy the assumptions of \cref{prop:FCP_RLInt}.
	If $\|v(t) - \wt{v}(t)\| \leq \varkappa $, for all $t \in [0, T]$, then the error of approximation  $\wt{J}_\alpha^N \wt{v}(t)$, satisfies the bound
	\begin{equation}\label{eq:FCP_RLInt_biasederr}
		\left\|J_\alpha v(t) - \wt{J}_\alpha^N \wt{v}(t) \right\|
		\leq  \frac{C t^\alpha}{\Gamma(\alpha)} e^{- \sqrt{2 \pi d \varepsilon N} } + \frac{ t^{\alpha}(\alpha + 1)}{\Gamma(\alpha+1)}
		\varkappa .
	\end{equation}
\end{corollary}
\begin{proof}
	We rewrite \eqref{eq:FCP_RLInt_biasederr} as
	\[
		\left\|J_\alpha v(t) - \wt{J}_\alpha^N \wt{v}(t) \right\|
		\leq 	\left\|J_\alpha v(t) - \wt{J}_\alpha^N v(t) \right\|
		+ 	\left\| \wt{J}_\alpha^N v(t) - \wt{J}_\alpha^N \wt{v}(t) \right\|.
	\]
	The first term of this error decomposition is estimated by \eqref{eq:FCP_RLInt_err_est}, so we focus on the second~term
	\begin{equation}\label{eq:FCP_RLInt_biasederr1}
		\left\| \wt{J}_\alpha^N v(t) - \wt{J}_\alpha^N \wt{v}(t) \right\|
		\leq \frac{\varkappa t^{\alpha}h }{\Gamma(\alpha)}\sum\limits_{k =-[\varepsilon N]}^{[\delta N]}  \frac{e^{kh}}{(1+e^{kh})^{\alpha + 1}} ,
	\end{equation}
	where
	\begin{equation}\label{eq:FCP_RLint_sbound_alpha}
		\begin{aligned}
			h\sum\limits_{k =-[\varepsilon N]}^{[\delta N]}  \frac{e^{kh}}{(1+e^{kh})^{\alpha + 1}} & \leq  h\sum\limits_{k =0}^{[\delta N]}  e^{-kh \alpha}
			+  h\sum\limits_{k =1}^{[\varepsilon N]}  \frac{e^{-kh}}{(1+e^{-h[\varepsilon N]})^{\alpha + 1}}                                                 \\
			                                                                                        & \leq
			h\frac{1 - e^{-h \alpha [\delta N]}}{1 - e^{-h \alpha}}
			+h\frac{e^{-h}(1 - e^{-h [\varepsilon N]})}{(1 - e^{-h})(1+e^{-h[\varepsilon N]})^{\alpha +1}}                                                   \\
			                                                                                        & \leq
			\frac{h}{1 - e^{-h \alpha}}
			+\frac{he^{-h}}{1 - e^{-h}}
			\leq 	\frac{1}{\alpha} + 1 = \frac{\alpha +1}{\alpha}.                                                                                           \\
		\end{aligned}
	\end{equation}
	The bound $1 - e^{-h} = \sum\limits_{k=1}^\infty \frac{(-1)^{k+1} h^k}{k!} \geq h $ was used to cancel out $h$ in the last estimation step.
	The combination of 	\eqref{eq:FCP_RLInt_err_est}, \eqref{eq:FCP_RLInt_biasederr1} and \eqref{eq:FCP_RLint_sbound_alpha} completes the proof.
\end{proof}

With all the necessary results in place, now we move on to construct the approximation to $u_{\mathrm{ih}}(t)$.
To achieve that, we apply approximations \eqref{eq:FCP_SO_cor_sinc_quad},  \eqref{eq:FCP_RLInt_appr} and discretize the remaining time-dependent integrals in a similar fashion as the Riemann--Liouville integral $J_\alpha$ (see \cref{prop:FCP_RLInt}).
The rationale for such integral discretizations will become apparent when we analyze the error below. Meanwhile, let us introduce the proposed approximation $\wt{u}_{\mathrm{ih}}^N(t)$ of the inhomogeneous solution $u_{\mathrm{ih}}(t)$ from \eqref{eq:FCP_inhom_cor_repr}:
\begin{equation}\label{eq:FCP_inhom_sol_appr}
	\begin{aligned}
		\wt{u}_{\mathrm{ih}}^N(t)  = & \wt{J}_\alpha^{N_0} \wt{S}_{\alpha,1}^N(t)f(0) + h_1 \sum\limits_{k=-N_1}^{N_1}  \mathcal{G}_\alpha^{N_2}(0, t, kh_1) \\
		                             & + \frac{h_3 h_4}{2\pi i}\sum\limits_{\ell =-N_3}^{N_3}F_{\alpha,1} (\ell h_3)
		\sum\limits_{k=-N_4}^{N_4} \mathcal{G}_\alpha^{N_5}(z(l h_3), t, kh_4),
	\end{aligned}
\end{equation}
where $F_{\alpha,1} (\xi)$, $z(\xi)$ are defined in \cref{lem:FCP_Pro_parametrized} and
\[
	\begin{aligned}
		\mathcal{G}_\alpha^N(z, t, p) & = t\psi'(p) e^{z t (1-\psi(p))}\wt{J}_\alpha^{N}  f'\left ( t\psi(p) \right ), \quad \psi(p) = \frac{e^p}{1+e^p}.
	\end{aligned}\]

\begin{theorem}\label{thm:FCP_inhom_sol_err_est}
	Let $A$ be a sectorial operator satisfying the assumptions of \cref{thm:FCP_prop_appr}.
	If the function $f(t)$ from \eqref{eq:FCP_DE} admits the analytic extension to the "eye-shaped" domain $D_d^2$, $d \in (0, \pi/2)$ and
	\begin{equation}\label{eq:FCP_rhs_reg_strip}
		f(0),f'(z) \in D(A^{\chi}), \quad \forall z \in  D_d^2,
	\end{equation}
	with some $\chi > 0$,
	then for any $\alpha \in (0, 2)$ and $t \in [0, T]$,  the approximation $\wt{u}_{\mathrm{ih}}^N(t)$ from \eqref{eq:FCP_inhom_sol_appr} converges to the inhomogeneous part $u_{\mathrm{ih}}(t)$ of the mild solution to \eqref{eq:FCP_DE}, \eqref{eq:FCP_BC}, defined by \eqref{eq:FCP_hom_inhom}.
	Moreover, for any fixed $N \in \N$, the following error bound is valid:
	\begin{equation}\label{eq:FCP_inhom_sol_err_est}
		\left \|u_{\mathrm{ih}}(t) - \wt{u}_{\mathrm{ih}}^N(t) \right \|
		\leq
		{C_{\chi,f}}  \left(\frac{t}{\alpha \chi} + \frac{1+t}{\Gamma(\alpha)}t^\alpha +  \frac{\chi + t(1 + \chi) }{\chi} t^\alpha e^{a_0 t}  \right)
		e^{-c\sqrt{\alpha\chi N}},
	\end{equation}
	{with $c=\sqrt{2\pi d}$,  provided that the values of $N_i$ and $h,h_i$ in \eqref{eq:FCP_inhom_sol_appr}  are determined by the following~formulas}
	\begin{equation}\label{eq:FCP_inhom_sol_N}
		N_1 = N_4 = \lceil \alpha\chi N \rceil,
		\quad
		N_3 = N,
		\quad
		N_0 = N_2 = N_5 = \left\lceil \frac{\alpha\chi N}{\min\left \{1, \alpha\right \}} \right\rceil ,
	\end{equation}
	\begin{equation}\label{eq:FCP_inhom_cor_h}
		h = h_i=\sqrt{\frac{2 \pi d}{\alpha \chi N}}, \quad i = 0, \ldots 5.
	\end{equation}
	Here,
	$d = \frac{\phi_\alpha - \phi_c}{2}$, $\phi_\alpha = \min\left\{\pi, \frac{\pi -\varphi_s}{\alpha}\right\}$  and $\phi_c \in \left[ \tfrac{\pi}{2}, \phi_\alpha \right)$, $a_0>0$  are given.
	The constant $C_{\chi,f}$ from~\eqref{eq:FCP_inhom_sol_err_est} is dependent on $\left\| A^{\chi}f'(z)\right \|$, ${z \in D_d^2}$ and independent of $t,N$.
\end{theorem}
\begin{proof}
	We analyze error $\left \|u_{\mathrm{ih}}(t) - \wt{u}_{\mathrm{ih}}^N(t) \right \|$ of \eqref{eq:FCP_inhom_sol_appr} in a term-by-term manner.

	The first error term is estimated via \cref{eq:FCP_RLint_NA} and \cref{thm:FCP_prop_appr}, applied in succession:
	\begin{align*}
		 & \left\| J_\alpha S_{\alpha}(t)f(0) - \wt{J}_\alpha^{N_0}\wt{S}_{\alpha}^N(t)f(0) \right\|
		\leq \frac{ t^{\alpha}(\alpha + 1)}{\Gamma(\alpha+1)} \left\| S_{\alpha}(t)f(0) - \wt{S}_{\alpha}^N(t)f(0)\right\| \\
		 & +\frac{C_0 t^\alpha}{\Gamma(\alpha)} e^{- \sqrt{2 \pi d \varepsilon N_0} }
		\leq
		C {t^{\alpha} e^{a_0 t}} e^{-c\sqrt{\alpha\chi N}}\|A^{\chi}f(0)\|
		+ \frac{C_0 t^\alpha}{\Gamma(\alpha)} e^{- c\sqrt{\varepsilon N_0} }.
	\end{align*}

	The error bound for the second term can be decomposed as
	\vspace*{-8pt}
	\[	\left\|  \intl_0^t J_\alpha f'(s)\, ds  - h_1 \sum\limits_{k=-N_1}^{N_1}  \mathcal{G}_\alpha^{N_2}(0, t, kh_1)\right\|  \leq \eta_{1} + \eta_{2},
	\]
	with $\eta_1$ being the quadrature error of the outer integral:
	\vspace*{-8pt}
	\[
		\eta_1	 = \left\|  t\intl_{-\infty}^\infty \psi'(p) J_\alpha f'(t\psi(p))\, dp  - th_1 \sum\limits_{k=-N_1}^{N_1} \psi'(k h_1)J_\alpha f'(t\psi(k h_1)) \right\|,
	\]
	stated here after the substitution $s = \psi(p)$ is performed therein, whereas $\eta_2$ is the compound error of the discretized Riemann--Liouville operators:
	\vspace*{-8pt}
	\[\begin{aligned}
			\eta_2
			 & =  th_1 \sum\limits_{k=-N_1}^{N_1} \left\|  \psi'(k h_1) \left(J_\alpha f'(t\psi(k h_1)) - \wt{J}_\alpha^{N_2} f'(t\psi(k h_1)) \right) \right\| \\
			 & \leq t \max\limits_{s \in [0,t]}\left\|J_\alpha f'(s) - \wt{J}_\alpha^{N_2} f'(s) \right\| h_1\sum\limits_{k=-N_1}^{N_1}  \psi'(k h_1).
		\end{aligned}	\]
	It is worth noting that the last series is a specific version of the one from \eqref{eq:FCP_RLInt_biasederr1}, with $\alpha = 1$.
	Thus, formula \eqref{eq:FCP_RLint_sbound_alpha} along with the bound from \cref{prop:FCP_RLInt}, warranted by the analyticity assumptions on $f'(z)$, yield
	\begin{equation*}\label{key}
		\eta_2
		\leq 2t \max\limits_{s \in [0,t]}\left\|J_\alpha f'(s) - \wt{J}_\alpha^{N_2} f'(s) \right\|
		\leq \frac{C_2}{\Gamma(\alpha)}  t^{\alpha + 1} e^{- c\sqrt{\varepsilon N_2} }.
	\end{equation*}

	Let us return to  $\eta_1$.
	The aforementioned analyticity of $f'(z)$ induces the uniform convergence of the integral for $J_\alpha f'(z)$ in formula \eqref{eq:FCP_RLInt_R} with respect to $z \in D_d^2$.
	Furthermore, for an arbitrary value of $p \in (-\infty, \infty)$, the function $z\psi(p)$ from \eqref{eq:FCP_RLInt_R} maps the convex region $D_d^2$ defined by \eqref{eq:FCP_D_d_2}, onto itself.
	By repeating the argument from the Proof of \cref{prop:FCP_RLInt}, these two facts and the relation $D_d \xrightarrow{\psi} D_d^2$ permits us to conclude that $\psi'(p) J_\alpha f'(t\psi(p))$ is analytic for $p \in D_d$.
	Due to the form of $\psi'(p)$, it is also exponentially decaying as $|p| \rightarrow \infty$ in $D_d \subseteq \oC$, with the decay order $1$.
	Hence, the error of sinc-quadrature $\eta_1$ admits the bound established in Theorem 4.2.6 from \cite{Stenger1993}:
	\vspace*{-6pt}
	\[
		\eta_1 \leq  C_1 t e^{- c \sqrt{N_1} }.
	\]

	We treat the third term from \eqref{eq:FCP_inhom_sol_appr} in a similar way as the second term, albeit this time the error decomposition is conducted after the application of \eqref{eq:FCP_SO_cor_repr} in reverse:
	\[
		\begin{array}{rl}
			 & \left\|\intl_{-\infty}^\infty \!\!\frac{F_{\alpha,1}(\xi)}{2\pi i}\intl_0^t \!\! e^{z(\xi)(t-s)}  J_\alpha f'(s) \, ds d\xi
			- t\frac{h_3 h_4}{2\pi i}\sum\limits_{\ell =-N_3}^{N_3}\!\!\!F_{\alpha,1} (\ell h_3)\! \sum\limits_{k=-N_4}^{N_4} \!\!\!\mathcal{G}_\alpha^{N_5}(z(l h_3), t, kh_4)
			\right\|                                                                                                                       \\
			 & =\left\|
			t\intl_{-\infty}^\infty \psi'(p) \left( S_{\alpha}(t - t\psi(p)) - I\right) J_\alpha f'(t\psi(p)) \, dp
			\right .                                                                                                                       \\
			 & \left .
			\hspace*{7em}
			-t\frac{h_3 h_4}{2\pi i} \suml_{k=-N_4}^{N_4} \suml_{\ell =-N_3}^{N_3}\!\! F_{\alpha,1} (\ell h_3)\mathcal{G}_\alpha^{N_5}(z(\ell h_3), t, kh_4)
			\right\|  \leq \eta_3 + \eta_4 + \eta_5 .
		\end{array}\]

	\pagebreak
	\noindent
	Here, the quantity $\eta_4$ is used to denote the quadrature error for the outer integral:
	\vspace*{-8pt}
	\begin{equation}\label{eq:FCP_inhom_sol_appr_eta3}
		\begin{aligned}
			\eta_4
			 & = \left\|
			t\intl_{-\infty}^\infty  \psi'(p) \left( S_{\alpha}(t - t\psi(p)) - I\right) J_\alpha f'(t\psi(p)) \, dp
			\right .                                                                                                                       \\
			 & \left.
			\hspace*{4em}
			- t h_4 \suml_{k=-N_4}^{N_4} \psi'(k h_4 )\left( S_{\alpha}(t - t\psi(k h_4)) - I\right) J_\alpha f'(t\psi(k h_4 )) \right \|. \\
		\end{aligned}
	\end{equation}
	The upper bound for the last integrand is determined by the properties of the norm
	$
		\left\| \left( S_{\alpha}(t - s) - I\right) J_\alpha f'(s) \right\|
		= \frac{1}{2\pi} \left\| \int_{-\infty}^\infty e^{z(\xi)(t-s)} F_{\alpha,1}(\xi) J_\alpha f'(s) \, d \xi\right\|,
	$
	which can be estimated using inequality \eqref{eq:FCP_SO_exp_cor_repr_norm_est_der}.
	Indeed, setting $x_1 = J_\alpha f'(s)$  in \eqref{eq:FCP_SO_cor_sinc_quad} reveals that the above integrand equals to the expression for $\cF_{\alpha,1}(t-s, \xi)$.
	As such, it admits the estimate
	\[
		\begin{aligned}
			\left\| e^{z(\xi)(t-s)} F_{\alpha,1}(\xi)J_\alpha f'(s)\right\|
			\leq
			C_{\alpha,1}(\chi, 0)
			e^{\Re{(z(\xi)(t-s))} - \alpha\chi|\xi|}\|A^{\chi} J_\alpha f'(s)\|                                                   \\
			\leq
			\frac{C_{\alpha,1}(\chi, 0)}{\Gamma(\alpha)}
			e^{\Re{(z(\xi)(t-s))} - \alpha\chi|\xi|}
			\int\limits_{-\infty}^{\infty} \frac{s^\alpha e^p}{(1+e^p)^{\alpha + 1}}\left\| A^{\chi} f'(s\psi(p))\right \|  \, dp \\
			\leq
			\frac{C_{\alpha,1}(\chi, 0) s^\alpha}{\Gamma(\alpha+1)}
			e^{\Re{(z(\xi)(t-s))} - \alpha\chi|\xi|}
			\sup\limits_{p \in \R}\left\| A^{\chi}f'(s\psi(p))\right \|.
		\end{aligned}\]
	Here, we used the relation
	\begin{equation}\label{eq:FCP_inhom_sol_appr_proof1}
		\int\limits_{-\infty}^{\infty} \frac{s^\alpha e^p}{(1+e^p)^{\alpha + 1}}
		= \int\limits_0^s (s-p)^{\alpha-1}dp
		= \frac{s^\alpha}{\alpha} ,
	\end{equation}
	stemming from the equivalence of definitions \eqref{eq:FCP_RLInt_R} and \eqref{eq:FCP_RLInt}.
	The previous chain of estimates leads us to the following bound:
	\vspace*{-6pt}
	\begin{equation}\label{eq:FCP_inhom_sol_appr_eta3_1}
		\begin{aligned}
			\left\| \left( S_{\alpha}(t - s) - I\right) J_\alpha f'(s) \right\|
			\leq \frac{1}{2\pi} \intl_{-\infty}^\infty \left\| e^{z(\xi)(t-s)}  F_{\alpha,1}(\xi) J_\alpha f'(s)\right\| \, d \xi &   & \\
			\leq
			\frac{C_{\alpha,1}(\chi, 0) s^\alpha }{2\pi \Gamma(\alpha+1)}
			\sup\limits_{p \in \R}\left\| A^{\chi}f'(s\psi(p))\right \|
			\intl_{-\infty}^\infty e^{\Re{(z(\xi)(t-s))}  - \alpha\chi|\xi|} \, d \xi                                             & . & \\
		\end{aligned}
	\end{equation}

	The norm $\left\| \left( S_{\alpha}(t - s) - I\right) J_\alpha f'(s) \right\|
	$ remains bounded as long as the last integral converges.
	Since $s = t\psi(p)$ in the expression for $\eta_4$, this convergence requirement translates into the inequality $\Re{(z(\xi)(t-t\psi(p)))} \leq 0$, which needs to be valid as $|\xi|,|p| \rightarrow \infty$.
	Let $p = w + i \nu \in D_{d'}$; then, using the {definition of $a_I$, $b_I$ from \eqref{eq:FCP_hyp_cont_par_final} along with the identity $\Arg{\left( 1 - \psi(w+i \nu)\right)}=-\arctan{\frac{e^w \sin{\nu}}{1 + e^w\cos{\nu}}}$,} we rewrite the inequality in terms of the complex number arguments
	\vspace*{-6pt}
	\[
		\begin{aligned}
			\frac{\pi}{2} & \geq \lim\limits_{\substack{\xi \to \infty \\ w \to \infty}}
			\Arg{(z(\xi)(t-t\psi(w + i \nu)))}%
			= \lim\limits_{\xi \to \infty}\Arg(z(\xi)) +
			\lim\limits_{w  \to \infty}
			\Arg(1-\psi(w + i \nu))                                    \\
			              & = \frac{\phi_s}{2} + \frac{\pi}{4}
			- \lim\limits_{w \to \infty}
			\arctan{\frac{e^w \sin{\nu}}{1 + e^w\cos{\nu}}}%
			= \frac{\phi_s}{2} + \frac{\pi}{4} - \nu .
		\end{aligned}
	\]

	\pagebreak
	\noindent
	Therefore, the integrand from \eqref{eq:FCP_inhom_sol_appr_eta3} is analytic in $D_{d'}$,
	with the value of $d' =  \frac{\phi_s}{2} - \frac{\pi}{4}$, which is equal to $d$ from \eqref{eq:FCP_hyp_cont_par_final}.
	Furthermore, the integrand's norm is exponentially decaying as a function of $p \in D_{d}$, as a consequence of \eqref{eq:FCP_inhom_sol_appr_eta3_1}, the boundedness of $\sup\limits_{z \in D_d^2}\left\| A^{\chi}f'(z)\right \|$ and the convergence of the integral, established before.
	Hence, similarly to $\eta_1$, the bound \mbox{from Theorem 4.2.6 of \cite{Stenger1993} } yields
	\vspace*{-6pt}
	\[
		\eta_4 \leq  \frac{C_4 t}{\alpha \chi} e^{- c \sqrt{N_4} }.
	\]

	Next, we use \eqref{eq:FCP_SO_cor_err_est} in conjunction with \eqref{eq:FCP_RLint_sbound_alpha}  and \eqref{eq:FCP_inhom_sol_appr_proof1} to estimate the propagator approximation error $\eta_3$
	\vspace*{-6pt}
	\[
		\begin{aligned}
			\eta_3
			 & = t h_4 \left\|
			\suml_{k=-N_4}^{N_4} \psi'(k h_4 )\left( S_{\alpha}(t - t\psi(k h_4)) - I\right) J_\alpha f'(t\psi(k h_4 )) \right.                        \\
			 & \left .
			\hspace*{1.2em}
			-\frac{h_3 }{2\pi i} \suml_{k=-N_4}^{N_4} \psi'(k h_4 )\suml_{\ell =-N_3}^{N_3} e^{t z(\ell h_3)  (1-\psi(k h_4))}F_{\alpha,1} (\ell h_3)J_\alpha f'(t\psi(k h_4 ))
			\right\|                                                                                                                                   \\
			 & \leq t h_4 \suml_{k=-N_4}^{N_4} |\psi'(k h_4 )|
			\left\| \frac{1}{2\pi i} \intl_{-\infty}^\infty e^{t z(\xi) (1-\psi(k h_4))}F_{\alpha,1}(\xi) J_\alpha f'(t\psi(k h_4 )) \right.           \\
			 & \left.
			\hspace*{8em}
			- \frac{h_3}{2\pi i}\suml_{\ell =-N_3}^{N_3} e^{t z(\ell h_3) (1-\psi(k h_4))}F_{\alpha,1} (\ell h_3)J_\alpha f'(t\psi(k h_4 ))
			\right\|                                                                                                                                   \\
			 & \leq  {C'_3} {te^{a_0 t}}e^{-c\sqrt{\alpha \chi N_3}} h_4 \suml_{k=-N_4}^{N_4} |\psi'(k h_4 )| 	 \|A^{\chi} J_\alpha f'(t\psi(k h_4 )\| \\
			 & \leq \frac{2{C'_3} {t^{\alpha+1} e^{a_0 t}}}{\Gamma(\alpha)}   e^{-c\sqrt{\alpha \chi N_3}}
			\sup\limits_{p \in \R}\left\| A^{\chi} f'(t\psi(p))\right \|
			\int\limits_{-\infty}^{\infty} \frac{ e^p}{(1+e^p)^{\alpha + 1}}\, dp                                                                      \\
			 & \leq \frac{2{C'_3} {t^{\alpha+1} e^{a_0 t}}}{\Gamma(\alpha + 1)}   e^{-c\sqrt{\alpha \chi N_3}}
			\sup\limits_{p \in [0,t]}\left\| A^{\chi} f'(p)\right \|
			\leq C_3 t^{\alpha+1} e^{a_0 t} e^{-c\sqrt{\alpha \chi N_3}}
			\sup\limits_{p \in [0,t]}\left\| A^{\chi} f'(p)\right \| .
		\end{aligned}
	\]

	The remaining summand $\eta_5$ represent the effect of discretized Riemann--Liouville operators on the error of the third approximation term in \eqref{eq:FCP_inhom_sol_appr}.
	We estimate it as
	\vspace*{-6pt}
	\[\begin{aligned}
			\eta_5 & =
			\frac{t h_3 h_4}{2\pi}
			\left\| \suml_{k=-N_4}^{N_4}\!\!\! \psi'(k h_4 )
			\suml_{\ell =-N_3}^{N_3}\!\!\! e^{t z(\ell h_3) (1-\psi(k h_4))}
			F_{\alpha,1} (\ell h_3)J_\alpha f'(t\psi(k h_4 ))
			\right.       \\
			       &
			\hspace*{4em}
			\left.
			- \suml_{k=-N_4}^{N_4} \!\!\!\psi'(k h_4 )
			\suml_{\ell =-N_3}^{N_3}\!\!\! e^{t z(\ell h_3) (1-\psi(k h_4))}
			F_{\alpha,1} (\ell h_3)\wt{J}_\alpha^{N_5}  f'\left ( t\psi(k h_4) \right )
			\right\|      \\
			       & \leq
			\frac{t h_3 h_4}{2\pi} \!\!\!
			\suml_{k=-N_4}^{N_4}\!\!\! |\psi'(k h_4 )|
			\suml_{\ell =-N_3}^{N_3} \!
			\left| e^{t z(\ell h_3) (1-\psi(k h_4))}\right|
			\\&
			\hspace*{5em}
			\times
			\left\|F_{\alpha,1} (\ell h_3)
			\left(
			J_\alpha f'(t\psi(k h_4)) - \wt{J}_\alpha^{N_5}  f'\left ( t\psi(k h_4) \right )
			\right)
			\right\|      \\
		\end{aligned}\]

	\pagebreak
	\noindent
	\[\begin{aligned}
			 & \leq
			\frac{(1+M)K b_I2^{\alpha\chi}h_3 h_4}
			{2\pi (a_I-a_0)}
			te^{t \Re{z(0)}}
			\suml_{k=-N_4}^{N_4}\!\!\! |\psi'(k h_4 )|
			\suml_{\ell =-N_3}^{N_3}
			\frac{e^{- \alpha\chi |\ell h_3|}}
			{r^{\chi}(\ell h_3,0)} \\
			 &
			\hspace*{5em}
			\times\left\|
			A^{\chi}
			\left( J_\alpha f'(t\psi(k h_4 )) - \wt{J}_\alpha^{N_5}  f'\left ( t\psi(k h_4) \right ) \right)
			\right \|.
		\end{aligned}\]
	Assumption \eqref{eq:FCP_rhs_reg_strip} enables us to estimate the last norm via \cref{prop:FCP_RLInt}:
	\begin{multline*}
		\left\|
		A^{\chi} \!\!
		\left( J_\alpha f'(t\psi(k h_4 )) - \wt{J}_\alpha^{N_5}  f'\left ( t\psi(k h_4) \right ) \right)
		\right \| \\
		\leq
		\left\|
		J_\alpha A^{\chi}\! f'(t\psi(k h_4 )) - \wt{J}_\alpha^{N_5}  A^{\chi} f'\left ( t\psi(k h_4)  \right)
		\right \|\\
		\leq
		\frac{C(\alpha, \chi) (t\psi(k h_4))^\alpha}{\Gamma(\alpha)} e^{- \sqrt{2 \pi d \varepsilon N_5} }
		\leq
		\frac{C(\alpha, \chi) t^\alpha}{\Gamma(\alpha)} e^{- \sqrt{2 \pi d \varepsilon N_5} }.
	\end{multline*}
	This decouples the inner and outer series in the above estimate for $\eta_5$.
	Thus,
	\[\begin{aligned}
			\frac{h_3}{2}\suml_{\ell =-N_3}^{N_3}
			\!\!\frac{e^{- \alpha\chi |k h_3|}}
			{r^{\chi}(k h_3,0)}
			 & \leq
			\frac{h_3}{2r_m^{\chi}} \left(
			\frac{1 - e^{- \alpha\chi N_3 h_3}}{1 - e^{- \alpha\chi h_3}}
			+ \frac{e^{- \alpha\chi h_3}(1 - e^{- \alpha\chi N_3 h_3})}{1 - e^{- \alpha\chi h_3}}
			\right) \\
			 & \leq
			\frac{h_3}{2r_m^{\chi}} \frac{1 + e^{- \alpha\chi h_3}}{1 - e^{- \alpha\chi h_3}}
			\leq \frac{1}{\alpha \chi r_m^{\chi}} ,
		\end{aligned}\]
	with $r_m = \inf\limits_{p \in \R} r_0(p)$ being strictly greater than zero, due to \eqref{eq:FCP_r}.
	By combining two previously obtained bounds with \eqref{eq:FCP_RLint_sbound_alpha}, we arrive at
	\[\begin{aligned}
			\eta_5
			 & \leq
			C'_5  \frac{C(\alpha, \chi) }
			{\chi \Gamma(\alpha+1)}  t^{\alpha + 1}e^{t (a_0 - a_I)}
			e^{- c \sqrt{\varepsilon N_5} }
			\leq
			C_5   \frac{t^{\alpha + 1}}{\chi}e^{t (a_0 - a_I)}
			e^{- c \sqrt{\varepsilon N_5} }.
		\end{aligned}\]
	The constant $C'_5 = \frac{(1+M)K b_I 2^{\alpha\chi + 1} }
		{\pi (a_I - a_0) } $, here,  is independent of $N_5$.

	The bounds derived for the quantities $\eta_i$, $i = 1, \ldots, 5$ show that they all are exponentially decaying as $N_i \to \infty$.
	We make these error bounds asymptotically equal to the error of the first term from \eqref{eq:FCP_inhom_sol_appr}, that is decaying on the order of $e^{-c\sqrt{\alpha\chi N}}$, provided that $\varepsilon N_0 = \alpha\chi N$ in the error estimate from the beginning of the proof.
	The resulting equations for $N_i$ are as~follows:
	\[
		N_1 = \alpha\chi N,
		\quad
		\varepsilon N_2 = \alpha\chi N,
		\quad
		\alpha\chi N_3 = \alpha\chi N,
		\quad
		N_4 = \alpha\chi N,
		\quad
		\varepsilon N_5 = \alpha\chi N,
	\]
	where $\varepsilon = \min\left \{1, \alpha\right \}$, as per \cref{prop:FCP_RLInt}.
	The solution of these equations gives us
	\eqref{eq:FCP_inhom_sol_N}.
	By collecting the derived error bounds for the terms of $\wt{u}_{\mathrm{ih}}^N(t)$, we end up with
	\begin{multline*}
		\left \|u_{\mathrm{ih}}(t) - \wt{u}_{\mathrm{ih}}^N(t) \right \| \leq
		\left(
		C t^{\alpha} e^{a_0 t} \|A^{\chi}f(0)\|
		+ \frac{C_0 t^\alpha}{\Gamma(\alpha)}
		+ C_1 t + \frac{C_4}{\alpha \chi}  t
		\right.\\
		\left.
		+ \frac{C_2}{\Gamma(\alpha)} t^{\alpha + 1}
		+ C_3 t^{\alpha+1} e^{a_0 t}
		\sup\limits_{p \in [0,t]}\left\| A^{\chi} f'(p)\right \|
		+C_5   \frac{t^{\alpha + 1}}{\chi}e^{a_0 t}
		\right) e^{-c\sqrt{\alpha\chi N}}.
	\end{multline*}
	This bound is reduced to \eqref{eq:FCP_inhom_sol_err_est}  by absorbing the individual constants into $C_{\chi, f}$, while retaining the asymptotic behavior with respect to $\alpha$, $\chi$ and $t$.
	The derived bound also proves the convergence of approximation \eqref{eq:FCP_inhom_sol_appr} to \eqref{eq:FCP_inhom_cor_repr} and, therefore, to the original definition for the inhomogeneous part of the solution given by \eqref{eq:FCP_hom_inhom}.
\end{proof}

\Cref{thm:FCP_inhom_sol_err_est} demonstrates that the proposed numerical method to approximate $u_{\mathrm{ih}}(t)$ inherits essential properties of the numerical method for propagator approximation,
it is based upon.
%described in \cref{thm:FCP_prop_appr}.
Firstly, the constructed approximation $\wt{u}_{\mathrm{ih}}^N(t)$ is exponentially convergent on the whole interval $t \in [0, T]$.
Secondly, bound \eqref{eq:FCP_inhom_sol_err_est} exhibits, similar to, \eqref{eq:FCP_SO_cor_err_est} dependence on the fractional order $\alpha$ and the argument smoothness parameter $\chi$.
%  that is formulated in terms of the operator powers via \eqref{eq:FCP_rhs_reg_strip}. 
%Therefore, one should expect that $\wt{u}_{\mathrm{ih}}^N(t)$ is more accurate for those $\alpha$ that are close to $1$.
Thirdly, just like~\eqref{eq:FCP_inhom_cor_repr}, formula~\eqref{eq:FCP_inhom_sol_appr} permits for an independent evaluation of resolvents $R(z^\alpha, -A)$ for the different values $z \in \Gamma_I$.
Moreover, the presence of factor $t^\alpha$ in \eqref{eq:FCP_inhom_sol_err_est} guaranties that the approximation $\wt{u}_{\mathrm{ih}}^N(t)$ matches the asymptotic behavior of the inhomogeneous part ${u}_{\mathrm{ih}}(t)$, when \mbox{$t \to 0+$ \cite{SytnykWohlmuth2023}.}
% \eqref{eq:FCP_inhom_cor_repr}
%that is known to decay as $t^\alpha$ when $t \to 0+$.
%\fxnote{Mention about the inclusion $D(A^a) \subseteq D(A^b)$, if $a<b<=1$.}
\begin{algorithm}[h!tb]
	\renewcommand{\algorithmicrequire}{\textbf{INPUT:}}
	\renewcommand{\algorithmicensure}{\textbf{OUTPUT:}}
	\begin{algorithmic}[1]
		\small
		\REQUIRE{\hspace{2em}  $\alpha, f(t)$, $t_k$, $\varphi_s$, $N, \chi$}
		\ENSURE{\hspace{0.8em}  $\left\{\wt{u}_\mathrm{ih}^N(t_k)\right\}$}
		%	\STATE{$\phi_\alpha\! :=\! \min\{ \pi, \frac{1}{\alpha}\left({\pi -\varphi_s}\right) \}$; $d\! :=\!\! \frac{1}{2}\left(\phi_\alpha + \frac{\pi}{2}\right)$ }
		%		\STATE{$N_1 := N_4 := \alpha\chi N$,
		%			$N_3 := N$,
		%			$N_0 := N_2 := N_5 := \frac{\alpha\chi N}{\min\left \{1, \alpha\right \}}$}
		\STATE{Calculate $a_I, b_I$ and $N_i$, $h,h_i$ by \eqref{eq:FCP_hyp_cont_par_final} and \eqref{eq:FCP_inhom_sol_N}, \eqref{eq:FCP_inhom_cor_h} }
		%	\COMMENT{Where $f$ - scalar analogue of operator function, $\phi$ - vector}
		\FOR{$m=-N$ \TO $N$}
		\STATE{Solve $(z(m h_1)^\alpha I+A)v = f(0)$}
		%\COMMENT{Can be done in parallel}
		\STATE{$F_{1,m}:=  z(m h_1)^{\alpha-1}v - \frac{1}{z(m h_1)}f(0)$}
		\ENDFOR
		\STATE{$M_1 := \left \lceil N_0\min\left \{1, \alpha\right \} \right \rceil$; $M_2 := \left \lceil N_0 \min\left \{\frac{1}{\alpha}, 1\right \} \right \rceil $}
		\FOR{each $t_k$}
		\STATE{%Using \eqref{eq:FCP_RLInt_appr} evaluate $\wt{u}_\mathrm{ih}^N(t_k) := \frac{h_1}{2 \pi i} \suml_{m=-N_1}^{N_1} \!z'(mh_1){e^{z(mh_1)t_k }}F_{1,m}$}
		%		Evaluate
		$\wt{u}_\mathrm{ih}^N(t_k) := \frac{t^{\alpha}h_0}{\Gamma(\alpha)}\!\! \suml_{ \ell=-M_1}^{M_2}\!\! \frac{e^{\ell h_0}}{(1+e^{\ell h_0})^{\alpha + 1}}\!\! \left(f(0) + \frac{h}{2 \pi i}\!\!\suml_{m=-N}^{N}\!\!\!\! z'(m h) {e^{t_k \psi(\ell h_0) z(m h)}} F_{1,m}\right)$
		%		where 
		%	    $\wt{S}_{\alpha,1}^{N_1}(t) = f(0) + \frac{1}{2 \pi i}\suml_{m=-N_1}^{N_1} z'(m h_1) {e^{t z(m h_1)}} F_{1,m}$} 
		%		where $\psi(p) = \frac{e^p}{1+e^p}$
		}
		\ENDFOR
		\FOR{each $t_k$}
		\STATE{$M_1 := \left \lceil N_2\min\left \{1, \alpha\right \} \right \rceil$; $M_2 := \left \lceil N_2 \min\left \{\frac{1}{\alpha}, 1\right \} \right \rceil $}
		\STATE{%
		%				\{Add contribution from $h_1 \sum\limits_{\ell=-N_1}^{N_1}  \mathcal{G}_\alpha^{N_2}(0, t, \ell h_1)$:\} \\
		%				\[\begin{aligned}
		$\wt{u}_\mathrm{ih}^N(t_k) := \wt{u}_\mathrm{ih}^N(t_k)\!
			+ \!\frac{ h_1 h_2}{\Gamma(\alpha)}t_k^{\alpha + 1} \!\!\!\suml_{\ell=-N_1}^{N_1}\!\!\!\! \psi'(\ell h_1) \psi^\alpha(\ell h_1)\!\!\suml_{m=-M_1}^{M_2}\!\!\!\frac{e^{m h_2}f'\left ( t_k \psi(\ell h_1)\psi(m h_2) \right )}{(1+e^{m h_2})^{\alpha + 1}}$
		%				\end{aligned}\]%
		%				, $\quad \psi(p) = \frac{e^p}{1+e^p}$
		}
		%			\\\COMMENT{Evaluate $h_1 \sum\limits_{k=-N_1}^{N_1}  \mathcal{G}_\alpha^{N_2}(0, t, kh_1)$}
		\ENDFOR
		\FOR{each $t_k$}
		\STATE{$M_1 := \left \lceil N_5\min\left \{1, \alpha\right \} \right \rceil$; $M_2 := \left \lceil N_5 \min\left \{\frac{1}{\alpha}, 1\right \} \right \rceil $}
		\FOR{$m=-N_3$ \TO $N_3$}
		%		\STATE{\{Calculate argument $f_m = \suml_{\ell=-N_4}^{N_4} \mathcal{G}_\alpha^{N_5}(z(m h_3), t_k, \ell h_4)$:\}}
		\STATE{% 
		%			\[\begin{aligned}
		$f_m :=\frac{ h_4 h_5}{\Gamma(\alpha)}t_k^{\alpha + 1} \!\!\! \suml_{\ell=-N_4}^{N_4}\!\!\! \psi'(\ell h_4) \psi^\alpha(\ell h_4)e^{t_k z(m h_3) (1-\psi(\ell h_4))} \!\!\! \suml_{j=-M_1}^{M_2}\!\!\!\!\frac{e^{j h_5}f'\left ( t_k\psi(\ell h_4)\psi(j h_5) \right )}{(1+e^{j h_5})^{\alpha + 1}}$
		%			\end{aligned}\]%
		}
		\STATE{Solve $(z(m h_3)^\alpha I+A)v = f_m$}
		%\COMMENT{Can be done in parallel}
		\STATE{$F_{1,m}:=  z(m h_3)^{\alpha-1}v - \frac{1}{z(m h_3)}f_m$}
		\ENDFOR
		\STATE{%
			%			\{Add contribution from $\frac{h_3 h_4}{2\pi i}\sum\limits_{m =-N_3}^{N_3}F_{\alpha,1} (m h_3) 			\sum\limits_{\ell=-N_4}^{N_4} \mathcal{G}_\alpha^{N_5}(z(m h_3), t_k,  \ell h_4)$:\}\\
			$\wt{u}_\mathrm{ih}^N(t_k) := \wt{u}_\mathrm{ih}^N(t_k) + \frac{h_3}{2\pi i}\sum\limits_{m =-N_3}^{N_3} z'(m h_3) F_{1,m}$}

		\ENDFOR
		\RETURN{$\{\wt{u}_\mathrm{ih}^N(t_k)\}$}
	\end{algorithmic}
	\caption{Algorithm for computing the inhomogeneous part approximation $\wt{u}_\mathrm{ih}^N(t)$.%
		\label{alg:FCP_inhom_sol_appr}%
	}
\end{algorithm}
