	\begin{tikzpicture}
		\draw (0,0)   node (flat) {flat};
		\draw (-1.5,1.5)  node (dc)   {DC};
		\draw (1.5,1.5)   node (uc)   {UC};
		\draw (-1.5,-1.5) node (df)   {DF};
