One can easily remark that the property of downwards closure is strictly  stronger assumption than downwards flatness. However, it will be a sufficient assumption for the following propositions.

\begin{proposition}
	\begin{enumerate}
		\item If
		$\exists x\varphi$ is downwards flat, then $\F(\exists x\varphi)\vDash\exists x\F\varphi$.

		\item If
		$\exists x\varphi$ is upwards flat, then $\exists x\F\varphi\vDash\F(\exists x\varphi)$.
	\end{enumerate}
\end{proposition}

\begin{proof} We consider the proof of the first claim.
	Let $\mathfrak{M}$ be a model, and let $X$ be a team over $\mathfrak{M}$ such that $\dom(X)\supseteq\FV(\varphi)\cup\FV(\psi)$. Then

	\begin{align*}
		&\mathfrak{M}\vDash_{X}\F(\exists x\varphi)\\
		\implies&\forall s\in X,\mathfrak{M}\vDash_{\left\{s\right\}}\exists x\varphi\\
		\implies&\forall s\in X,\exists H:\left\{s\right\}\to\powersetstar(M),\mathfrak{M}\vDash_{\left\{s\right\}\left[H\replaces x\right]}\varphi&\text{(semantics of $\exists$)}\\
		\implies&\exists H':X\to\powersetstar(M),\forall s\in X,\mathfrak{M}\vDash_{\left\{s\right\}\left[H'\replaces x\right]}\varphi\\
		\implies&\exists H':X\to\powersetstar(M),\forall s\in X,\forall s'\in\left\{s\right\}\left[H'\replaces x\right],\mathfrak{M}\vDash_{\left\{s'\right\}}\varphi&\text{(downwards flatness)}\\
		\implies&\exists H':X\to\powersetstar(M),\forall s\in X\left[H'\replaces x\right],\mathfrak{M}\vDash_{\left\{s\right\}}\varphi\\
		\implies&\exists H':X\to\powersetstar(M),\mathfrak{M}\vDash_{X\left[H'\replaces x\right]}\F\varphi\\
		\implies&\mathfrak{M}\vDash_{X}\exists x(\F\varphi)
	\end{align*}
\end{proof}

\begin{proposition}
	\begin{enumerate}
		\item if %
		$\forall x\varphi$ is downwards flat, then $\F(\forall x\varphi)\vDash\forall x(\F\varphi)$,

		\item if %
		$\forall x\varphi$ is upwards flat, then $\forall x(\F\varphi)\vDash\F(\forall x\varphi)$.
	\end{enumerate}
\end{proposition}

\begin{proof} Again we consider the proof of the first claim only as the proof is similar in the second case.
	Let $\mathfrak{M}$ be a model, and let $X$ be a team over $\mathfrak{M}$ such that $\dom(X)\supseteq\FV(\varphi)\cup\FV(\psi)$. Then

	\begin{align*}
		&\mathfrak{M}\vDash_{X}\F(\forall x\varphi)\\
		\implies&\forall s\in X,\mathfrak{M}\vDash_{\left\{s\right\}}\forall x\varphi\\
		\implies&\forall s\in X,\mathfrak{M}\vDash_{\left\{s\right\}\left[M\replaces x\right]}\varphi\\
		\implies&\forall s\in X,\forall s'\in\left\{s\right\}\left[M\replaces x\right],\mathfrak{M}\vDash_{\left\{s'\right\}}\varphi&\text{(downwards flatness)}\\
		\implies&\forall s\in X\left[M\replaces x\right],\mathfrak{M}\vDash_{\left\{s\right\}}\varphi\\
		\implies&\mathfrak{M}\vDash_{X\left[M\replaces x\right]}\F\varphi\\
		\implies&\mathfrak{M}\vDash_{X}\forall x(\F\varphi)
	\end{align*}
\end{proof}

\subsection{Preservation of closure properties}

The proof of the next lemma is a routine application of the semantics.
\begin{lemma}\label{lem:preservation-closure-properties}
	\begin{enumerate}
		\item If $\varphi$ is downwards closed (resp. union closed), then $\F\varphi$ is also downwards closed (resp. union closed).
		\item If $\varphi$ is downwards flat (resp. upwards flat), then $\F\varphi$ is also downwards flat (resp. upwards flat).
	\end{enumerate}
\end{lemma}

\begin{corollary}\label{cor:preservation-closure-properties-logics}
	Let $\mathcal{L}$ be team-based logic extending $\FO$ by some dependencies and operators.
	\begin{enumerate}
		\item  If $\mathcal{L}$ is downwards closed (resp. union closed, resp. downwards flat, resp. upwards flat), then so is $\mathcal{L}(\F)$.
		\item If $\mathcal{L}$ is flat, then $\mathcal{L}\equiv\mathcal{L}(\F)$.
	\end{enumerate}
\end{corollary}



\section{The expressive power of the flattening operator}
\label{sec:expressive-power-of-F}

We ask now, does the flattening operator, when added to a logic, increase the expressive power of the logic? In \cite{Galliani:2018} the flattening operator $\F$ was said to be \emph{safe} for a team-based logic $\mathcal{L}$ if  %
$\mathcal{L}\equiv\mathcal{L}(\F)$. 
The idea is that the operator $\F$ can be ``safely'' added to the logic, as it does not increase its expressive power. In this section we systematically study the effect of $\F$ to the expressive power of various team-based logics. %

\subsection{Adding \texorpdfstring{$\F$}{F} to inclusion and anonymity logic}
\label{subsec:safeness-of-F-for-incl}

The goal of this subsection is to show that inclusion logic together with the flattening operator $\FO\left(\incl,\F\right)$ is equivalent to the positive fragment of  greatest fixed-point logic $\GFPpos$. From this it follows that $\FO\left(\incl,\F\right)$ has exactly the same expressive power as $\FOincl$ by the results of \cite{Galliani:2013:inclusion}.%

\begin{theorem}\label{thm:GFPpos-expresses-FOinclF}
	For every $\FO\left(\incl,\F\right)$-formula $\varphi(\tuple{x})$ with free variables in $\tuple{x}=(x_{1},\dots,x_{n})$ there is a $\GFPpos$-formula $\varphi^{*}=\varphi^{*}(R,\tuple{x})$ such that $\ar(R)=n$, $R$ occurs only positively in $\varphi^{*}$, and the condition
	\[
		\mathfrak{M}\vDash_{X}\varphi(\tuple{x})\quad\text{iff}\quad\left<\mathfrak{M},R\coloneqq X(\tuple{x})\right>\vDash_{s}\varphi^{*}(R,\tuple{x})\text{ for all }s\in X
	\]
	holds for all models $\mathfrak{M}$ and all teams $X$ over $\mathfrak{M}$ with $\dom(X)\supseteq\left\{x_{1},\dots,x_{n}\right\}$.
\end{theorem}

\begin{proof}
	The proof is by structural induction on $\varphi$. The cases for first-order literals, inclusion  atoms, connectives, and quantifiers are treated as in \cite[Theorem 15]{Galliani:2013:inclusion}. We show the inductive case corresponding to $\F$.

		 If $\varphi(\tuple{x})$ is of the form $\F\psi(\tuple{x})$, then we define %

		\[
			\varphi^{*}(R,\tuple{x})=\forall\tuple{y}(\neg R\tuple{y}\vee \theta(\tuple{x},\tuple{y}))
		\]
		where $\theta(\tuple{x},\tuple{y})=\psi^{*}(S,\tuple{x})\left[(\tuple{y}=\tuple{t})\replaces S(\tuple{t})\right]$, that is, $\theta$ is the formula $\psi^{*}(S,\tuple{x})$ in which we replaced each atom of the form $S(\tuple{t})$ by the atom $\tuple{y}=\tuple{t}$. Let $\mathfrak{M}$ be a model and $X$ be a team over $\mathfrak{M}$ with $\dom(X)\supseteq\left\{x_{1},\dots,x_{n}\right\}$. One can remark that

		\begin{align}	\notag\mathfrak{M}\vDash_{X}\F\psi(\tuple{x})
			\iff&\forall s\in X.&&\mathfrak{M}\vDash_{\left\{s\right\}}\psi(\tuple{x})&\text{}\\
			\notag\iff&\forall s\in X.\forall s'\in\left\{s\right\}.&&\left<\mathfrak{M},S\coloneqq\left\{s\right\}(\tuple{x})\right>\vDash_{s'}\psi^{*}(S,\tuple{x})&\text{(by IH on $\psi(\tuple{x})$)}\\
			\notag\iff&\forall s\in X.&&\left<\mathfrak{M},S\coloneqq\left\{s\right\}(\tuple{x})\right>\vDash_{s}\psi^{*}(S,\tuple{x})\\
			\notag\iff&\forall s\in X.&&\left<\mathfrak{M},S\coloneqq\left\{s(\tuple{x})\right\}\right>\vDash_{s}\psi^{*}(S,\tuple{x})\\
			\label[condition]{cnd:GFPpos-expresses-FOinclF:proof-case-F}\iff&\forall s\in X.&&\mathfrak{M}\vDash_{s}\psi^{*}(S,\tuple{x})\left[(s(\tuple{x})=\tuple{t})\replaces S(\tuple{t})\right]
		\end{align}


		The last equivalence is justified by the following observation: as $S$ is assigned to a relation with a unique element $s(\tuple{x})$, having an atom on the form $S(\tuple{t})$ is $\psi^{*}$ is equivalent to have the atom $s(\tuple{x})=\tuple{t}$ instead (we do the test \quoexpr{by hand}), so we perform this substitution in $\psi^{*}$ while preserving equivalence.

		Now, suppose $\mathfrak{M}\vDash_{X}\F\psi(\tuple{x})$, then \cref{cnd:GFPpos-expresses-FOinclF:proof-case-F} holds. We want to show
		\[
			\left<\mathfrak{M},R\coloneqq X(\tuple{x})\right>\vDash_{s}\forall\tuple{y}(R\tuple{y}\rightarrow\psi^{*}(S,\tuple{x})\left[(\tuple{y}=\tuple{t})\replaces S(\tuple{t})\right])\quad\text{for all }s\in X
		\]
		To do so, let $\tuple{b}\in M$ such that $\tuple{b}\in X(\tuple{x})$. Then there is an assignment $s\in X$ such that $\tuple{b}=s(\tuple{x})$, we fix such an assignment. And by \cref{cnd:GFPpos-expresses-FOinclF:proof-case-F} we obtain
		\[
			\mathfrak{M}\vDash_{s}\psi^{*}(S,\tuple{x})\left[(\tuple{b}=\tuple{t})\replaces S(\tuple{t})\right]
		\]

		Conversely, suppose that
		\[
			\left<\mathfrak{M},R\coloneqq X(\tuple{x})\right>\vDash_{s}\forall\tuple{y}(R\tuple{y}\rightarrow\psi^{*}(S,\tuple{x})\left[(\tuple{y}=\tuple{t})\replaces S(\tuple{t})\right])\quad\text{for all }s\in X
		\]
		So by taking $\tuple{y}\coloneqq s(x)$, as $s(\tuple{x})\in\left\{s(x)\setsep s\in X\right\}\defeq X(\tuple{x})$, then the condition \extexpr{$R\tuple{y}$} is satisfied, so we get
		\[
			\mathfrak{M}\vDash_{s}\psi^{*}(S,\tuple{x})\left[(s(\tuple{x})=\tuple{t})\replaces S(\tuple{t})\right]\quad\text{for all }s\in X
		\]
		and the result follows from \cref{cnd:GFPpos-expresses-FOinclF:proof-case-F}.
\end{proof}
\begin{corollary}\label{cor:F-safe-inclusion-logic}\label{cor:F-safe-anonymity-logic}
	\leavevmode
	\begin{enumerate}
		\item The logics $\FO\left(\incl,\F\right)$ and $\FOincl$ are equivalent for sentences.
		\item The logics $\FO\left(\anon,\F\right)$ and $\FOanon$ are equivalent for sentences.
	\end{enumerate}
\end{corollary}

\begin{proof}
	The first claim follows by \cref{thm:GFPpos-expresses-FOinclF}.

	The second claim follows from the fact inclusion atoms can be expressed using anonymity atoms and vice versa.
\end{proof}

\subsection{Adding \texorpdfstring{$\F$}{F} to unary inclusion logic}

Galliani \cite{Galliani:2018} proved  that constancy atoms increase the expressive power of unary inclusion logic. More precisely, he proved that non-connectedness of graphs can be expressed  using constancy atoms and unary inclusion atoms, but not in terms of unary inclusion atoms alone. The next proposition shows that the same effect can be obtained using $\F$ and inclusion atoms. %

\begin{notation}
	Let $\phi$ is a first-order formula, and let $\psi$ be a team-based formula. We will then denote $\varphi\regularimplication\psi$ as an abbreviation for $\lnot\varphi\lor(\varphi\land\psi)$.
\end{notation}

We thank Pietro Galliani for suggesting the following proposition.

\begin{proposition}\label{prp:non-connectedness-expressible-FOincl1F}
	The following $\FO\left(\incl[1],\F\right)$ sentence
	\[
		\exists y(\F(\exists x(x\neq y\land\forall z(E(x,z)\regularimplication z\incl x))))
	\]
	is true in a graph $\mathfrak{G}=\left<V,E\right>$ if and only if the graph $\mathfrak{G}$ is disconnected.%
\end{proposition}

\begin{proof}
It is straightforward to check that the formula above is logically equivalent with the formula used in \cite{Galliani:2018} to show the same result.
\end{proof}

\begin{corollary}\label{cor:F-unsafe-unary-inclusion-logic}
	The flattening operator $\F$ increases the expressive power of $\FOincl[1]$.
\end{corollary}

\subsection{Adding \texorpdfstring{$\F$}{F} to unary anonymity logic}

\subsubsection{Expressivity of unary anonymity atoms and the flattening operator}

For any $n\in\mathbb{N}$, we denote by $\mathfrak{A}_{n}$ a graph consisting of two cycles each of length $2^{n+1}$ and $\mathfrak{B}_{n}$ a graph consisting of a single cycle of length $2^{n+2}$.

\begin{proposition}\label{separatingexmple}
	The following $\FO(\anon[1],\F)$ sentence
	\[
		\exists x\F(\exists y(y\neq x\land\forall z(E(y,z)\regularimplication(z\neq x\land y\anon z\land z\anon y))))
	\]
	is true in the models $\mathfrak{A}_{n}$ and is false in $\mathfrak{B}_{n}$.
\end{proposition}

\begin{proof}
	The intuition behind this $\FO\left(\anon[1],\F\right)$-sentence is as follows: consider a cycle of even length. We would like to fill it completely with variable assignments, in order to be able to detect if there exists another node in the graph that is not part of the considered cycle. To do so, we are going to use the mechanism of the anonymity atom to fill this cycle. More precisely, we will partition the cycle into two sets of nodes, that will be assigned to $y$ and $z$ respectively, in such a way that there will be an alternation between the values taken by $y$ and $z$ along the cycle. This is illustrated in the \cref{fig:anonymity-atom-filling-cycle-mechanism}.
	\begin{figure}
		\centering
		\begin{tikzpicture}[
			auto,
			node_style/.style={circle, draw},
			edge_style/.style={},
			]

			\def\radius{1.5cm}
			\def\n{6}

			\foreach \i in {1,...,\n} {
				\node [node_style] at ({360/\n * (\i - 1)}:\radius) (v\i) {$\phantom{y}$};
			}
			\foreach \i in {1,...,\n} {
				\pgfmathtruncatemacro{\next}{mod(\i, \n) + 1}
				\draw [edge_style]  (v\i) edge (v\next);
			}

			\node			at (v2) {$y_{0}$};
			\node [BrickRed] at (v4) {$y_{2}$};
			\node [BrickRed] at (v6) {$y_{2}'$};

			\node [BrickRed] at (v1) {$z_{1}'$};
			\node [BrickRed] at (v3) {$z_{1}$};
			\node [BrickRed] at (v5) {$z_{3}$};

			\def\radiusoffset{5mm}
			\def\angleoffset{10}
			\draw [thick, BrickRed, dashed, |->] (360/\n+\angleoffset:\radius+\radiusoffset) arc (360/\n * (2-1)+\angleoffset:360/\n * (5-1)-\angleoffset:\radius+\radiusoffset);
			\draw [thick, BrickRed, dashed, |->] (360/\n-\angleoffset:\radius+\radiusoffset) arc (360/\n * (2-1)-\angleoffset:360/\n * (5-1)+\angleoffset-360:\radius+\radiusoffset);
		\end{tikzpicture}
		\caption{Illustration of the anonymity atom mechanism to fill a cycle}
		\label{fig:anonymity-atom-filling-cycle-mechanism}
	\end{figure}		

	This filling process is done via the sub-formula $E(y,z)\regularimplication(y\anon z\land z\anon y)$. Here, the black node $y_{0}$ in the \cref{fig:anonymity-atom-filling-cycle-mechanism} corresponds to a starting value for the variable $y$. Then $E(y,z)\regularimplication y\anon z$ forces the variable $z$ to take two different values $z_{1}$ and $z_{1}'$ that are in fact the two adjacent vertices of $y_{0}$. Then $E(y,z)\regularimplication z\anon y$ firstly forces the variable $y$ to take two different values $y_{2}$ and $y_{0}$ that are in fact the two adjacent vertices of $z_{1}$, and secondly forces the variable $y$ to take two different values $y_{2}'$ and $y_{0}$ that are in fact the two adjacent vertices of $z_{1}'$. And so on. At the end, as the considered cycle is of even length, then the last two values assigned to the variable $z$ actually coincide. Such filled components then satisfy the clause $\forall z(E(y,z)\regularimplication y\anon z\land z\anon y)$.

	The whole objective will be to succeed in distinguishing the graphs $\mathfrak{A}_{n}$ from the graphs $\mathfrak{B}_{n}$. In fact, the graphs $\mathfrak{A}_{n}$ and $\mathfrak{B}_{n}$ are all composed of one or two cycles of even length.

	At the end of the filling process, we obtained a cycle filled with an alternation of values for the variables $z$ and $y$. In order to distinguish $\mathfrak{A}_{n}$ from $\mathfrak{B}_{n}$, we need to find an $x$ such that it does not belong to the alternation of $y$ and $z$. Hence, we need to check both that $y\neq x$ and $z\neq x$, which gives
	\[
		y\neq x\land\forall z(E(y,z)\regularimplication(z\neq x\land y\anon z\land z\anon y))
	\]
	The end of the construction of the desired formula is identical to the one we made for the unary inclusion logic together with the flattening operator $\F$, and at the end we finally get
	\[
		\exists x\F(\exists y(y\neq x\land\forall z(E(y,z)\regularimplication(z\neq x\land y\anon z\land z\anon y))))
	\]
	By construction, it is clear that this formula is true for the graphs $\mathfrak{A}_{n}$ but is false for the graphs $\mathfrak{B}_{n}$.
\end{proof}

\subsubsection{Unary anonymity logic does not express non-connectedness}

The next technical lemma will be used to show that the structures $\mathfrak{A}_{n}$  and $\mathfrak{B}_{n}$ from the previous section cannot be separated by formulas of unary anonymity logic.

Let $\mathfrak{M}$ be a model, let $X$ be a team over $\mathfrak{M}$, and let $\mathcal{F}\subseteq\Aut\left(\mathfrak{M}\right)$. Then we define the \defexpr{team closure of $X$ under $\mathcal{F}$}, written $\TeamCl_{\mathcal{F}}\left(X\right)$, as the set of all assignments obtained by applying all automorphisms from $\mathcal{F}$ to all assignments of $X$, that is
\[
	\TeamCl_{\mathcal{F}}\left(X\right)\defeq\left\{f\left(s\right)\setsep s\in X,f\in\mathcal{F}\right\}
\]
For $\mathcal{F}=\Aut\left(\mathfrak{M}\right)$, we simply write $\TeamCl\left(X\right)$ instead of $\TeamCl_{\Aut\left(\mathfrak{M}\right)}\left(X\right)$, that is
\[
	\TeamCl\left(X\right)\defeq\left\{f\left(s\right)\setsep s\in X,f\in\Aut\left(\mathfrak{M}\right)\right\}
\]

Recall that a \defexpr{magma} is a set $M$ equipped with a binary operation $\star$ that sends any two elements from $M$ to another element in $M$, and in this case we call $\star$ an \defexpr{internal binary operation}. We call a \defexpr{unitary magma} any magma whose internal binary operation admits a neutral element (which is then unique), that is, if there is $e\in M$ such that for all $m\in M$ we get $e\star m=m\star e=m$.

\begin{lemma}\label{magma}
	Let $\mathfrak{M}$ be a model. Let $\mathcal{F}\subseteq\Aut(\mathfrak{M})$ be a unitary magma such that for any two points $m_{1},m_{2}\in M$ there exists an automorphism $f\in\mathcal{F}$ such that $f(m_{1})=m_{1}$ and $f(m_{2})\neq m_{2}$. Then for all teams $X$ over $\mathfrak{M}$ such that $\TeamCl_{\mathcal{F}}(X)=X$ and all formulas $\varphi\in\FOanon[1]$ with free variables in $\dom(X)$ 
	we have that
	\[
		\mathfrak{M}\vDash_{X}\varphi\quad\text{iff}\quad\mathfrak{M}\vDash_{X}\varphi^{\f}	
	\]
\end{lemma}

\begin{proof}
		It suffices to show the right to left direction that is proved via structural induction. The proof for the connectives and quantifiers are similar to that of Lemma~21 in \cite{Galliani:2018}.


			Assume $\varphi=x_{1}\anon x_{2}$. %
			As $(x_{1}\anon x_{2})^{\f}=\top$ %
			we need to prove that $\mathfrak{M}\vDash_{X}x_{1}\anon x_{2}$ only from the hypothesis of the lemma, that is, whenever $X$ is a team whose domain contains the variables $x_{1}$ and $x_{2}$ and such that $X=\TeamCl_{\mathcal{F}}(X)$. But this is the case. Indeed, suppose that $s(x_{1})=m_{1}$ and $s(x_{2})=m_{2}$. Then by assumption of the lemma, there is an automorphism $f\in\mathcal{F}$ such that $f(m_{1})=m_{1}$ and $f(m_{2})\neq m_{2}$, and since $X=\TeamCl_{\mathcal{F}}(X)$ there exists some assignment $s'\in X$ such that $s'=f(s)$, that is, $s'(x)=f(s(x))$ for all $x\in\dom(s)$. This implies in particular that
			\[\begin{cases}
				s'(x_{1})=f(s(x_{1}))=f(m_{1})=m_{1}=s(x_{1})\\
				s'(x_{2})=f(s(x_{2}))=f(m_{2})\neq m_{2}=s(x_{2})
			\end{cases}\]
			and thus, for any assignment $s\in X$ there exists some assignment $s'\in X$ such that $s'(x_{1})=s(x_{1})$ but $s'(x_{2})\neq s(x_{2})$. This shows that $\mathfrak{M}\vDash_{X}x_{1}\anon x_{2}$, as required.
\end{proof}

\begin{corollary}\label{cor:F-unsafe-unary-anonymity-logic}
	The flattening operator increases the expressive power of unary anonymity logic.	
\end{corollary}

\begin{proof}
	By Proposition \ref{separatingexmple}, the formula $\Theta$ separates the models $\mathfrak{A}_{n}$ and $\mathfrak{B}_{n}$. Assume for a contradiction that $\Theta$ is equivalent to some $\varphi$ of unary anonymity logic. By Lemma \ref{magma}, $\varphi$ is equivalent to $\varphi^{\f}$ in the models $\mathfrak{A}_{n}$ and $\mathfrak{B}_{n}$, that is
	\[
		\mathfrak{A}_{n}\vDashTarski \varphi^{\f} \iff \mathfrak{B}_{n}\vDashTarski \varphi^{\f},
	\]
	where $\varphi^{\f}$ is a first-order formula. But by an Ehrenfeucht-Fraïssé game argument, this is impossible.
\end{proof}

\subsection{Adding \texorpdfstring{$\F$}{F} to dependence, exclusion and independence logic}

In this section we show that $\FO(\depformat,\F)$ has exactly the same expressive power as $\FOdep$. We will use the same strategy as in \cref{subsec:safeness-of-F-for-incl}. More precisely, we will show that $\FO(\depformat,\F)\subseteqq\ESO$, and as it is well known that $\ESO\equiv\FO(\depformat)$, we will obtain the result. The same idea works also  for exclusion and independence logic.

Exactly as for inclusion logic and $\GFPpos$ (\cref{thm:GFPpos-expresses-FOinclF}), we have to adapt the equivalence between $\FO(\depformat,\F)$ and $\ESO$ because they do not use the same semantics.

Recall that a sentence $\phi(R)$ from second-order logic is called \defexpr{downwards closed} if $(\mathfrak{M},A)\vDash\phi(R)$ and $A'\subseteq A$ imply $(\mathfrak{M},A')\models\phi(R)$.

\begin{lemma}\label{lem:translation-FOdepF-to-ESO}
	For every $\FO(\depformat,\F)$-formula $\varphi(\tuple{x})$ with the free variables in $\tuple{x}=x_{1},\dots,x_{n}$, there is an $\ESO$-formula $\varphi^{*}\equiv\varphi^{*}(R)$ which is downwards closed and such that $\ar(R)=n$, and that satisfies the following condition:
	\begin{equation}\label{eqn:translation-FOdepF-to-ESO}
		\mathfrak{M}\vDash_{X}\varphi(\tuple{x})\quad\text{iff}\quad\left<\mathfrak{M},R\coloneqq X(\tuple{x})\right>\vDash
\varphi^{*}(R)\vee\forall \tuple{x}\neg R(\tuple{x})
	\end{equation}
	holds for all models $\mathfrak{M}$ and all teams $X$ over $\mathfrak{M}$ with $\dom(X)\supseteq\left\{\tuple{x}\right\}$.
\end{lemma}
\begin{proof}
	 We consider the inductive case corresponding to $\varphi=\F\psi$ as the other cases can be dealt with analogously to \cite[Theorem 6.2]{Vaananen:2007:dependence}. It turns out that the formula $\varphi^{*}$ that we need to take is exactly the same as for the translation from $\FO(\incl,\F)$ to $\GFPpos$ which is clearly in $\ESO$ assuming $\psi^{*}$ is.
\end{proof}

\begin{corollary}\label{prp:F-safe-exclusion-logic}\label{prp:F-safe-dependency-logic}
	The operator $\F$ does not increase the expressive power of dependence and exclusion logic.	
\end{corollary}

\begin{proof}
	This follows by \cref{lem:translation-FOdepF-to-ESO} as any downwards closed  $\ESO$-formula $\varphi(R)$ can be translated into a dependence logic formula satisfying \eqref{eqn:translation-FOdepF-to-ESO}, see \cite{Kontinen:2009,Kontinen:2011}. The claim for exclusion logic follows from the fact that exclusion atoms can be  expressed using dependence atoms and vice versa.
\end{proof}  

\begin{corollary}\label{cor:F-safe-independency-logic}
	The operator $\F$ does not increase the expressive power of independence  logic.	
\end{corollary}

\begin{proof}
	The proof is analogous to the case of dependence logic using the analogue of \cref{lem:translation-FOdepF-to-ESO} (without the assumption of downward closure) ans its converse shown in \cite{Galliani:2012}.
\end{proof}   

\subsection{Adding \texorpdfstring{$\F$}{F} to fragments of dependence logic}

We begin by showing that the flattening operator reduces to the flattening of a formula for existential dependence logic formulas. 

\begin{proposition}\label{existentialDEP}
	If $\varphi\in\FOdep$ is existential %
	then $\F\varphi\equiv\varphi^{\f}$.
\end{proposition}

\begin{proof} Recall that  $\mathfrak{M}\vDash_{X}\F\varphi$ iff $\mathfrak{M}\vDash_{\{s\}}\varphi$, for all $s\in X$. Now it is easy to show using induction on $\varphi$ using downwards closure (and singleton-valued supplements functions) that $\mathfrak{M}\vDash_{\{s\}}\varphi$ iff $\mathfrak{M}\vDash_{\{s\}}\varphi^f$ for any singleton team $\{s\}$, from which the claim follows. 
\end{proof}

Next we turn to the so-called constancy logic the formulas of which has the following normal form.

\begin{proposition}[\cite{Galliani:2012}]%
	\label{prp:constancy-logic-normal-form}%
	Let $\varphi(\tuple{x})\in\FOcons$. Then $\varphi$ is logically equivalent to a constancy logic formula of the form
	\[
		\exists\tuple{y}\left(\bigwedge_{i}\dep(y_{i})\land\alpha(\tuple{x},\tuple{y})\right)
	\]
	for some first-order formula $\alpha$.
\end{proposition}

\begin{proposition}\label{prp:F-safe-constancy-logic}\label{prp:F-safe-zero-anonymity-logic}
		The operator $\F$ does not increase the expressive power of constancy logic, that is $\FO(\consformat,\F)\equiv\FOcons$.

\end{proposition}

\begin{proof}
We prove the claim using induction on $\varphi \in \FO(\consformat,\F)$. We consider only the case where $\varphi=\F \psi$. By the induction hypothesis and the previous lemma, 
we get that $\psi$ is equivalent with some formula in the normal form:
	\[
		\exists\tuple{y}\left(\bigwedge_{i}\dep(y_{i})\land\alpha(\tuple{x},\tuple{y})\right)
	\]
	for some first-order formula $\alpha$. It now follows from Proposition \ref{existentialDEP}  that $\varphi\equiv \exists\tuple{y}\alpha$.
\end{proof} 

\subsection{Adding \texorpdfstring{$\F$}{F} to \texorpdfstring{$\FO$}{FO} with the Boolean negation}

In this section we consider the effects of adding $\F$ to $\FOneg$ (also denoted by $\NEG$ in the following).

\begin{definition}
	Let $\varphi$ be a $\sigma$-formula, $\mathfrak{M}$ a $\sigma$-model and $X$ a team over $\mathfrak{M}$ such that $\dom(X)\supseteq\FV(\varphi)$. We define the truth of the formula $\cneg\varphi$ (the Boolean negation of $\varphi$) in the model $\mathfrak{M}$ and the team $X$ as:
	\[
		\mathfrak{M}\vDash_{X}\cneg\varphi\iff\mathfrak{M}\nvDash_{X}\varphi
	\]
\end{definition}

We will use the following notations from \cite{Luck:2020}:
\begin{itemize}
	\item $\E\varphi\defeq\cneg\neg\varphi$, meaning  that at least one assignment in the considered team satisfies $\varphi$;

	\item $\varphi\ovee\psi\defeq\cneg(\cneg\varphi\land\cneg\psi)$, so that $\mathfrak{M}\vDash_{X}\varphi\ovee\psi$ iff $\mathfrak{M}\vDash_{X}\varphi$ or $\mathfrak{M}\vDash_{X}\psi$, which corresponds to the  Boolean disjunction (a.k.a. intuitionistic disjunction). 
\end{itemize}
We will utilize the following normal form theorem.
\begin{proposition}[\cite{Luck:2020}]
	\label{prp:negation-logic-normal-form}%
	Let $\varphi(\tuple{x})\in\FOneg$. Then $\varphi$ is logically equivalent to a formula of the form
	\[
		\bigovee_{i\in I}\left(\alpha_{i}\land\bigwedge_{j\in J_{i}}\E\beta_{i,j}\right)
	\]
	for some finite sets $I$ and $J_{i}$ and for first-order formulas $\alpha_{i}$ and $\beta_{i,j}$ for all $i\in I$ and $j\in J_{i}$.
\end{proposition}

\begin{proposition}\label{prp:F-safe-negation-logic}
	$\FO(\cneg,\F)\equiv\FOneg$.
\end{proposition}

\begin{proof}
	To prove the non-trivial direction ($\Rightarrow$), we need to show that for all $\varphi(\tuple{x})\in\FO(\cneg,\F)$, there is $\varphi^{*}(\tuple{x})\in\FOneg$ such that for all models $\mathfrak{M}$ and for all teams $X$ over $\mathfrak{M}$ such that $\dom(X)\supseteq\left\{\tuple{x}\right\}$, the following holds
	\[
\mathfrak{M}\vDash_{X}\varphi(\tuple{x})\iff\mathfrak{M}\vDash_{x}\varphi^{*}(\tuple{x})
	\]
	We prove it by structural induction on $\varphi$. The only interesting case is when $\varphi(\tuple{x})=\F\psi(\tuple{x})$.

	According to \cref{prp:negation-logic-normal-form}, we get that
	\[
	   \psi(\tuple{x})\equiv\bigovee_{i\in I}\left(\alpha_{i}\land\bigwedge_{j\in J_{i}}\E\beta_{i,j}\right)
	\]
	for some finite sets $I$ and $J_{i}$ and for first-order formulas $\alpha_{i}$ and $\beta_{i,j}$ for all $i\in I$ and $j\in J_{i}$. It is now a routine application of the semantics to show that $\varphi$ is equivalent with the first-order formula 
	\[
	   \bigvee_{i\in I}\left(\alpha_{i}\land\bigwedge_{j\in J_{i}}\beta_{i,j}\right),
	\]
	using the facts that in singleton teams $\E\beta$ is equivalent with $\beta$ and that for all $s\in X$
	\[
		\mathfrak{M}\vDash_{\{s\}} \bigovee_i \varphi_i\quad\text{iff}\quad\mathfrak{M}\models_{X} \bigvee_i \varphi_i,
	\]
	for  first-order formulas $\varphi_i$.
\end{proof}



\section{Summing up expressive powers}

We sum up all the previous results in the following \cref{fig:sum-up}. It shows when a fragment is comparable to another in terms of expressive power, and when it is the case, it indicates which fragment is more expressive than another. The red edges are the comparisons that are not known at the moment, but which we believe to be true. These questions have some echoes in finite model theory where beyond the seminal and old results about the monadic case (i.e. arity $1$) of existential second order logic, very few separation results are known~\cite{Ajtai:1983,Ajtai:2000,Durand:1998}. Considering the tight connections between arity based fragments of existential second order logic and of some team logics~\cite{Durand:2012}, such a situation is all but surprising.

