\def\titlerunning{Towards an Analysis of Proofs in Arithmetic}
\def\authorrunning{Leitsch, Loli\'c, Mahler}
\begin{document}
\maketitle

\begin{abstract}
Inductive proofs can be represented as proof schemata, i.e. as parameterized sequences of proofs defined in a primitive recursive way. Applications of proof schemata can be found in the area of automated proof analysis where the schemata admit (schematic) cut-elimination and the construction of Herbrand systems.
This work focuses on the expressivity of proof schemata. We show that proof schemata can simulate primitive recursive arithmetic. The translation of proofs in arithmetic to proof schemata can be considered as a crucial step in the analysis of inductive proofs. 
\end{abstract}


