\subsection{Proof of Theorem \ref{Theorem_1}}\label{Proof_A}
Since $\log\det(\cdot)$ is a concave function, we could utilize Jensen's inequality to obtain the upper bound of $\mathcal{R}_{\text{sic}}$ in \eqref{R_SIC}:
\begin{align}\label{Jensen}
\mathcal{R}_{\text{sic}} &\leq \overline{\mathcal{R}}_{\text{sic}} \\
&=\log\det\left( \mathbf{I}_L+\mathbf{Q}^{\mathsf H} \mathbf{H}^{\mathsf H} \sum_{k=1}^{K} \mathbbmss{E}\left\{\mathbf{g}_k \mathbf{g}_k^{\mathsf H} \right\} \mathbf{H}\mathbf{Q}(\mathbf{P})^{-1} \right),\nonumber
\end{align}
where $\mathbbmss{E}\left\{\mathbf{g}_k \mathbf{g}_k^{\mathsf H} \right\}$ can be calculated as
\begin{align}\label{expectation}
\mathbbmss{E}\left\{\mathbf{g}_k \mathbf{g}_k^{\mathsf H} \right\}&=\mathbbmss{E}\left\{\left(\sqrt{\alpha_k\frac{K_0}{1+K_0}} \bar{\mathbf{g}}_k+ \sqrt{\alpha_k\frac{1}{1+K_0}}\tilde{\mathbf{g}}_k\right) \right. \nonumber\\
& \left. \cdot \left( \sqrt{\alpha_k\frac{K_0}{1+K_0}}\bar{\mathbf{g}}_k+ \sqrt{\alpha_k\frac{1}{1+K_0}}\tilde{\mathbf{g}}_k\right)^{\mathsf H} \right\} \nonumber \\
&= \frac{\alpha_k K_0}{1+K_0}\bar{\mathbf{g}}_k\bar{\mathbf{g}}_k^{\mathsf H}+\frac{\alpha_k}{1+K_0} \mathbf{R}_k.
\end{align}
By denoting $\tilde{\mathbf{G}}_k=\left[\sqrt{\frac{\alpha_k K_0}{1+K_0}}\bar{\mathbf{g}}_k,\sqrt{\frac{\alpha_k }{1+K_0}}\mathbf{R}_k^{1/2}\right]\in \mathbbmss{C}^{N \times (N+1)}$, we have $\tilde{\mathbf{G}}_k\tilde{\mathbf{G}}_k^{\mathsf H}=\mathbbmss{E}\left\{\mathbf{g}_k \mathbf{g}_k^{\mathsf H} \right\}$. Let $\mathbf{G}=\left[\tilde{\mathbf{G}}_1,\dots,\tilde{\mathbf{G}}_K \right] \in \mathbbmss{C}^{N \times K(N+1)}$, then we can obtain $\mathbf{G}\mathbf{G}^{\mathsf H}=\sum_{k=1}^{K} \tilde{\mathbf{G}}_k\tilde{\mathbf{G}}_k^{\mathsf H}$. The final results follow immediately.

\subsection{Proof of Theorem \ref{Theorem_2}}\label{Proof_B}
By denoting $\mathbf{A}=\sum_{i=1}^{K}\mathbf{Q}^{\mathsf H} \mathbf{H}^{\mathsf H}\mathbf{g}_i \mathbf{g}_i ^{\mathsf H} \mathbf{HQ}+ \mathbf{P}$ and $\mathbf{B}_k=\sum_{i\neq k}^{K}\mathbf{Q}^{\mathsf H} \mathbf{H}^{\mathsf H}\mathbf{g}_i \mathbf{g}_i ^{\mathsf H} \mathbf{HQ}+ \mathbf{P}$, we have
\begin{align} \label{R_nsic_2}
\mathcal{R}_\text{nsic}=\sum_{k=1}^{K}\mathbbmss{E} \left\{\log\det(\mathbf{A})- \log\det(\mathbf{B}_k)\right\}.
\end{align}
By exploiting Jensen’s inequality, we obtain the following relationships:
\begin{align}
\mathbbmss{E} \left\{\log\det(\mathbf{A})\right\}\leq \log\det\left(\sum_{i=1}^{K}\mathbf{Q}^{\mathsf H} \mathbf{H}^{\mathsf H}\tilde{\mathbf{G}}_i \tilde{\mathbf{G}}_i^{\mathsf H} \mathbf{HQ}+ \mathbf{P}\right), \nonumber \\
\mathbbmss{E} \left\{\log\det(\mathbf{B}_k)\right\}\leq \log\det\left(\sum_{i\neq k}^{K}\mathbf{Q}^{\mathsf H} \mathbf{H}^{\mathsf H}\tilde{\mathbf{G}}_i \tilde{\mathbf{G}}_i^{\mathsf H} \mathbf{HQ}+ \mathbf{P}\right).  \nonumber
\end{align}
Instituting the above two inequations into \eqref{R_nsic_2} and after some basic mathematical manipulations, we can get the approximation of the sum rate with MMSE-nSIC decoding, i.e., $\tilde{\mathcal{R}}_\text{nsic}$ in \eqref{MMSE_nSIC_approximate}.

\subsection{Proof of Theorem \ref{Theorem_4}}\label{Proof_D}
To prove this theorem, we first introduce the following lemma.
\begin{lemma} \label{Lagrangian}
Problem $\mathcal{P}_\text{d}$ is equivalent to
\begin{subequations}
\begin{align}
{\mathcal P}_t: ~\max_{\mathbf{Q},\mathbf{W},\bm\rho} &~ \mathcal{F}_0 (\mathbf{Q},\mathbf{W},\bm\rho) =\sum_{k=1}^{K} \log_2(1+\rho_k) \nonumber\\
&~ -\sum_{k=1}^{K}\rho_k +\sum_{k=1}^{K}(1+\rho_k) \mathcal{B}_k \label{Pt_obj}\\
{\rm{s.t.}}&~ \eqref{cons_Q},\eqref{cons_Q2},~ \sum\nolimits_{k=1}^{K}\|\mathbf{HQ}\mathbf{w}_k\|^2\leq P_\text{max},
\end{align}
\end{subequations}
where $\mathcal{B}_k=\left(\sum_{i=1}^{K}\mathbf{w}_i^{\mathsf H}\mathbf{H}_k \mathbf{w}_i+N_k\right)^{-1}\mathbf{w}_k^{\mathsf H} \mathbf{H}_k\mathbf{w}_k$.
\end{lemma}
\begin{proof}
It is noted that $\mathcal{F}_0$ is concave over $\bm\rho$ with other variables fixed, thus the optimal $\bm\rho$ can be obtained by setting $\frac{\partial \mathcal{F}_0}{\partial \rho_k}=0$, which results in $\rho_k^{\star}=\frac{\mathcal{D}_k}{1-\mathcal{D}_k}$. By exploiting the Woodbury formula, we have $\rho_k^{\star}=\frac{\mathbf{w}_k^{\mathsf H}\mathbf{H}_k\mathbf{w}_k}{\sum_{i\neq k}^{K} \mathbf{w}_i^{\mathsf H}\mathbf{H}_k \mathbf{w}_i+N_k}$ with $\mathbf{H}_k=\mathbf{Q}^{\mathsf H}\mathbf{H}^{\mathsf H} \tilde{\mathbf{G}}_k \tilde{\mathbf{G}}_k^{\mathsf H} \mathbf{H} \mathbf{Q}$. It is worth noting that instituting $\rho_k^\star$ into \eqref{Pt_obj} recovers the objective function of $\mathcal{P}_\text{d}$ in \eqref{P3_obj}, which means that $\mathcal{P}_\text{d}$ and $\mathcal{P}_t$ have the same optimal objective value and optimal solution over $\mathbf{Q}$ and $\mathbf{W}$, i.e., $\max\limits_{\mathbf{Q},\mathbf{W},\bm\rho} \mathcal{F}_0 =\max\limits_{\mathbf{Q},\mathbf{W}} \tilde{\mathcal{R}}_\text{d}$ and  $\argmax\limits_{\mathbf{Q},\mathbf{W}} \mathcal{F}_0 (\mathbf{Q},\mathbf{W},\bm\rho_k^\star)=\argmax \limits_{\mathbf{Q},\mathbf{W}} \tilde{\mathcal{R}}_d$. These results suggest the two problems are equal.
\end{proof}
Lemma \ref{Lagrangian} establishes the equivalence of $\mathcal{P}_t$ and $\mathcal{P}_\text{d}$. Next we prove the equivalence of $\mathcal{P}_3$ and $\mathcal{P}_t$. Similarly, $\mathcal{F}_1$ is a concave differentiable function over $\bm\gamma_k$ with other variables fixed. Therefore, we let each $\frac{\partial \mathcal{F}_1}{\partial \bm\gamma_k}=0$ and the optimal $\bm\gamma_k^\star$ is given by $\bm\gamma_k^{\star}=\left(\sum_{i=1}^{K}\mathbf{w}_i^{\mathsf H}\mathbf{H}_k \mathbf{w}_i+N_k\right)^{-1} \tilde{\mathbf{G}}_k^{\mathsf H} \mathbf{H} \mathbf{Q} \mathbf{w}_k$. Inserting $\bm\gamma_k^\star$ back to $\mathcal{F}_1$ recovers the
objective function in \eqref{Pt_obj}, which means $\mathcal{P}_3$ and $\mathcal{P}_t$ are two equal problems, the equivalence between $\mathcal{P}_3$ and $\mathcal{P}_\text{d}$ is thus established.
