We can of course get a strong elimination order by applying the (algorithmic) proof
by Farber \cite{Farber83} that finds such an order as long as every induced subgraph
has a simple vertex.  However,
Farber's algorithm is somewhat complicated and involves ordering the vertices by
the subset-relation of their neighbourhoods while changing the graph.   The run-time
has not been analyzed, but is at least quadratic and possibly worse.   We give here
instead an algorithm that reads a strong elimination order directly from the
tree representation, and works in linear time if know for any edge $(v,w)$ 
which of $T(v),T(w)$ overshadows the other.   We need some helper-results.

\begin{observation}
\label{obs:compatible}
\label{obs:overshadow}
If $(v,w)$ is an edge and $T(v) \overshadows T(w)$,
then $d(\mathbf{v})\leq d(\mathbf{w})$ (and in
particular therefore $\mathbf{w}\in T(v)$).
%Let $\{T(v)\}$ be a compatible tree representation.
%If $(v,w)$ is an edge and $T(v) \overshadows T(w)$,
%then $\mathbf{w}\in T(v)$.
\end{observation}
\begin{proof}
If we had $d(\mathbf{v})>d(\mathbf{w})$, then $\mathbf{v}$
(which is in $T(w)$ by Observation~\ref{obs:intersection})
would be a strict descendant of $\mathbf{w}$.   But
then $\mathbf{w}\in T(w)\setminus T(v)$ has smaller depth
than $\mathbf{v}\in T(w)\cap T(v)$, which implies
$T(v)\notovershadows T(w)$.
\end{proof}


\begin{lemma}
\label{lem:bottom_up_good}
Let $\{T(v)\}$ be a tree-representation, and let $v_1,\dots,v_n$
be an enumeration of the vertices such that $T(v_j)\overshadows T(v_i)$ for all $i<j$.
%that satisfies the following:
%\begin{itemize}
%\item $d(\mathbf{v_1})\geq \dots \geq d(\mathbf{v_n})$,
%\item if $d(\mathbf{v_\ell})=d(\mathbf{v_k})$ for some $\ell>k$, then $T(v_\ell)\overshadows T(v_k)$.
%\end{itemize}
Then $v_1,\dots,v_n$ is a strong elimination order.
\end{lemma}

Before proving this, we note that such an order is always a bottom-up
enumeration order by Observation~\ref{obs:overshadow}.  But the reverse is not true;
for example in Figure~\ref{fig:bottom_up_bad} we have bottom-up enumeration order $i,j,k,\ell$,
but $T(\ell) \notovershadows T(k)$.

\begin{proof}
For ease of writing, we use $T_i$ rather than $T(v_i)$ for all $i$.
To show the condition for a strong elimination order,
fix arbitrary indices $i<j$ and $k<\ell$ with $v_i,v_j\in N[v_k]$ and $v_i\in N[v_\ell]$;
we have to show that $v_j\in N[v_\ell]$.
Note that the premise is symmetric in $\{i,j\}$ and $\{k,\ell\}$, so up to renaming
we have $i\leq k$.   By Observation~\ref{obs:intersection} and $d(\mathbf{v_i})
\geq d(\mathbf{v_k}) \geq d(\mathbf{v_\ell})$ then $\mathbf{v_i}\in T_k\cap T_\ell$;
in particular therefore $(v_k,v_\ell)$ is an edge and $\mathbf{v_k}\in T_\ell$.


If $j\geq k$ then $v_j\in N[v_k]$ implies $\mathbf{v_k}\in T_j$; since $\mathbf{v_k}\in T_\ell$
then trees $T_j$ and $T_\ell$ intersect and $v_j\in N[v_\ell]$ as desired.   So we are done
unless $j<k$, which implies $\mathbf{v_j}\in T_k$.
By assumption we have $T_\ell \overshadows T_k$, and so all nodes in $T_k\setminus T_\ell$
must have depth strictly greater than $\mathbf{v_i}\in T_k\cap T_\ell$.     Since $d(\mathbf{v_j})\leq d(\mathbf{v_i})$
and $\mathbf{v_j}\in T_k$, therefore $\mathbf{v_j}\in T_\ell$ and $v_j\in N[v_\ell]$ as desired.
\end{proof}

Observe
that $d(\mathbf{v})>d(\mathbf{w})$ immediately implies that $T(w)\notovershadows T(v)$
by Observation~\ref{obs:overshadow}, 
as does $d(\mathbf{v})=d(\mathbf{w})$ if the nodes $\mathbf{v},\mathbf{w}$
are distinct (and therefore the tree $T(v),T(w)$ are disjoint).    
Therefore we have to break ties by overshadowing only between
vertex-pairs $v,w$ with $\mathbf{v}=\mathbf{w}$.   In particular, if (as in
the tree representation obtained via Lemma~\ref{lem:ordering_treerep}) all
vertices have distinct roots of subtrees, then any bottom-up enumeration order is
a strong elimination order.

Before turning Lemma~\ref{lem:bottom_up_good}
into an algorithm to find the order, we first
show a result that was claimed in~\cite{BG-CCCG24}, but
the proof (erroneously) assumed that a strong elimination order can be
obtained by lining up simple vertices. 
An \emph{RDV graph} is a graph with a tree-representation $\{T(v)\}$ where 
every subtree has exactly one leaf.   In other words, it is the intersection
graph of downward paths in a rooted tree.    

\begin{corollary}
Let $G$ be an RDV-graph with a tree-representation $\{T(v)\}$ where every
subtree is a downward path in the host tree.    Then any bottom-up enumeration order
$v_1,\dots,v_n$ is a strong elimination order.
\end{corollary}
\begin{proof}
We will show that for any two vertices $v,w$ with $d(\mathbf{v})\leq d(\mathbf{w})$
tree $T(v)$ overshadows $T(w)$; this shows that the tree-representation is compatible
and the result then follows from Lemma~\ref{lem:bottom_up_good}.
Clearly we have $T(v)\overshadows T(w)$ if the trees are disjoint.
So assume they share nodes, which means $\mathbf{w}\in T(v)$ by Observation~\ref{obs:intersect}.
Since both subtrees are downward paths,
they go downward from $\mathbf{w}$ along the same path until some node $\mathbf{z}$,
whence they diverge and the rest of the paths are disjoint.   Setting
the cut-off point to be $d(\mathbf{z})$, therefore  $T(v)\overshadows T(w)$.
\end{proof}

To turn Lemma~\ref{lem:bottom_up_good} into an algorithm (and hence
prove Theorem~\ref{thm:treerep_peo}), we only
have to describe how to quickly find a suitable order.   

\TreerepPEO*
\begin{proof} %(of Theorem~\ref{thm:treerep_peo})
Define an auxiliary directed graph $H$ with the same vertices as $G$
and the following directed edges:    For any edge $(v,w)$ of $G$,
add a directed graph $v\rightarrow w$ to $H$ if $T(v)\notovershadows T(w)$,
i.e., if we \emph{must} put $v$ earlier in the order.    By
Lemma~\ref{lem:not_cyclic}, a directed cycle in $H$ means that the
tree-representation was not compatible, and we can detect this in 
$O(m+n)$ time since $H$ has $O(m)$ edges.    So we are done if $H$
has a directed cycle.   Otherwise, find a topological order $v_1,\dots,v_n$
of $H$, which can be done in linear time.    For any $v_i,v_j$ with $i<j$, 
if there is no edge $(v_i,v_j)$ 
in $G$ then the trees $T(v_i),T(v_j)$ are disjoint and therefore $T(v_j)\overshadows T(v_i)$.
If there is an edge $(v_i,v_j)$
in $G$, then by choice of the topological order we do \emph{not} have a 
directed edge $v_j\rightarrow v_i$ in $H$.   Therefore $T(v_j)\overshadows T(v_i)$ by definition of $H$,
and $v_1,\dots,v_n$ is a strong elimination order by Lemma~\ref{lem:bottom_up_good}.
\end{proof}

